    int number = 15;

    if (number % 2 == 0) {
        printf("%d is even.\n", number);
    } else {
        printf("%d is odd.\n", number);
    }

    return 0;
}


if-else if-else Chain
For multiple conditions, chain if-else if-else statements. Order matters: the first true branch wins.
#include &lt;stdio.h&gt;

int main(void) {
    int score = 85;

    if (score &gt;= 90) {
        printf("Grade: A\n");
    } else if (score &gt;= 80) {
        printf("Grade: B\n");
    } else if (score &gt;= 70) {
        printf("Grade: C\n");
    } else if (score &gt;= 60) {
        printf("Grade: D\n");
    } else {
        printf("Grade: F\n");
    }

    return 0;
}

The switch Statement
The switch statement provides an alternative to long if-else if chains when comparing a single expression against multiple constant integer values (including character constants).

Basic Syntax
switch (expression) {
    case constant1:
        // Code for constant1
        break;
    case constant2:
        // Code for constant2
        break;
    default:
        // Code for no match
        break;
}


Simple switch Example
#include &lt;stdio.h&gt;

int main(void) {
    int day = 3;

    switch (day) {
        case 1:  printf("Monday\n");    break;
        case 2:  printf("Tuesday\n");   break;
        case 3:  printf("Wednesday\n"); break;
        case 4:  printf("Thursday\n");  break;
        case 5:  printf("Friday\n");    break;
        case 6:  printf("Saturday\n");  break;
        case 7:  printf("Sunday\n");    break;
        default: printf("Invalid day\n"); break;
    }

    return 0;
}


Intentional Fall-Through
Without break, control falls into the next case. Use this only deliberately, and document it:
#include &lt;stdio.h&gt;

int main(void) {
    int month = 2;

    switch (month) {
        case 12:
        case 1:
        case 2:
            printf("Winter\n");
            break;
        case 3:
        case 4:
        case 5:
            printf("Spring\n");
            break;
        case 6:
        case 7:
        case 8:
            printf("Summer\n");
            break;
        case 9:
        case 10:
        case 11:
            printf("Autumn\n");
            break;
        default:
            printf("Invalid month\n");
            break;
    }

    return 0;
}
