Worked Example 3: Simple ATM Menu with switch
Balance, deposit, withdraw, and PIN check — menu loop with switch.
/* atm_menu.c — console ATM simulation */
#include &lt;stdio.h&gt;
#include &lt;stdbool.h&gt;

#define PIN_CODE 1234
#define MAX_TRIES 3

int main(void) {
    double balance = 1000.00;
    int pin;
    int tries = 0;
    bool authenticated = false;

    printf("=== Mini ATM ===\n");
    while (tries &lt; MAX_TRIES) {
        printf("Enter PIN: ");
        if (scanf("%d", &pin) != 1) {
            printf("Invalid input.\n");
            /* drain line */
            int ch;
            while ((ch = getchar()) != '\n' && ch != EOF) {
            }
            tries++;
            continue;
        }
        if (pin == PIN_CODE) {
            authenticated = true;
            break;
        }
        tries++;
        printf("Wrong PIN (%d/%d).\n", tries, MAX_TRIES);
    }

    if (!authenticated) {
        printf("Card locked. Goodbye.\n");
        return 1;
    }

    int choice = -1;
    do {
        printf("\n--- Menu ---\n");
        printf("1. Check balance\n");
        printf("2. Deposit\n");
        printf("3. Withdraw\n");
        printf("4. Quick $50 withdraw\n");
        printf("0. Exit\n");
        printf("Choice: ");

        if (scanf("%d", &choice) != 1) {
            printf("Please enter a number.\n");
            int ch;
            while ((ch = getchar()) != '\n' && ch != EOF) {
            }
            choice = -1;
            continue;
        }

        switch (choice) {
            case 1:
                printf("Balance: $%.2f\n", balance);
                break;

            case 2: {
                double amount;
                printf("Deposit amount: ");
                if (scanf("%lf", &amount) != 1 || amount &lt;= 0.0) {
                    printf("Invalid amount.\n");
                    break;
                }
                balance += amount;
                printf("Deposited. New balance: $%.2f\n", balance);
                break;
            }

            case 3: {
                double amount;
                printf("Withdraw amount: ");
                if (scanf("%lf", &amount) != 1 || amount &lt;= 0.0) {
                    printf("Invalid amount.\n");
                    break;
                }
                if (amount &gt; balance) {
                    printf("Insufficient funds.\n");
                } else {
                    balance -= amount;
                    printf("Withdrawn. New balance: $%.2f\n", balance);
                }
                break;
            }

            case 4:
                if (balance &lt; 50.0) {
                    printf("Insufficient funds for quick withdraw.\n");
                } else {
                    balance -= 50.0;
                    printf("Dispensed $50.00. Balance: $%.2f\n", balance);
                }
                break;

            case 0:
                printf("Thank you. Session ended.\n");
                break;

            default:
                printf("Unknown option.\n");
                break;
        }
    } while (choice != 0);

    return 0;
}
