#include &lt;stdio.h&gt;

int main(void) {
    int choice;

    do {
        printf("\n=== Menu ===\n");
        printf("1. Option 1\n");
        printf("2. Option 2\n");
        printf("0. Exit\n");
        printf("Choice: ");
