Loop Control: break and continue

break
Leaves the innermost loop immediately.
#include &lt;stdio.h&gt;

int main(void) {
    for (int i = 1; i &lt;= 10; i++) {
        if (i == 5) {
            break;
        }
        printf("%d ", i);
    }
    printf("\nDone.\n");
    return 0;
}


continue
Skips the rest of the current iteration and proceeds to the next test/update.
#include &lt;stdio.h&gt;

int main(void) {
    for (int i = 1; i &lt;= 10; i++) {
        if (i % 2 == 0) {
            continue;  /* skip evens */
