Pattern: Retry with Cap (avoid true infinite hang)
#include &lt;stdio.h&gt;
#include &lt;stdbool.h&gt;

static bool try_connect(int attempt) {
    printf("connect attempt %d\n", attempt);
    return attempt &gt;= 3;  /* succeed on 3rd try in this demo */
}

int main(void) {
    const int max_attempts = 5;
    int attempt = 0;
    bool ok = false;

    while (attempt &lt; max_attempts) {
        attempt++;
        if (try_connect(attempt)) {
            ok = true;
            break;
        }
    }

    printf(ok ? "Connected.\n" : "Gave up.\n");
    return ok ? 0 : 1;
}

Worked Example 1: Prime Check
/* prime_check.c */
#include &lt;stdio.h&gt;
#include &lt;stdbool.h&gt;
#include &lt;math.h&gt;

static bool is_prime(long n) {
    if (n &lt;= 1) {
        return false;
    }
    if (n &lt;= 3) {
        return true;
    }
    if (n % 2 == 0 || n % 3 == 0) {
        return false;
    }
    /* check 6k ± 1 up to sqrt(n) */
    for (long i = 5; i * i &lt;= n; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) {
            return false;
        }
    }
    return true;
}

int main(void) {
    long n;
    printf("Enter integer: ");
    if (scanf("%ld", &n) != 1) {
        printf("Invalid input.\n");
        return 1;
    }

    if (is_prime(n)) {
        printf("%ld is prime.\n", n);
    } else {
        printf("%ld is not prime.\n", n);
    }

    printf("Primes up to 50: ");
    for (long i = 2; i &lt;= 50; i++) {
        if (is_prime(i)) {
            printf("%ld ", i);
        }
    }
    printf("\n");
    return 0;
}
