scanf("%s", buf)
scanf("%63s", buf) or fgets


strcpy(dst, src)
snprintf(dst, dst_sz, "%s", src)


strcat(dst, src)
str_append helper with remaining size


strncpy without forced '\0'
snprintf or copy + dst[sz-1]='\0'


sprintf(dst, …)
snprintf(dst, dst_sz, …)


DIY loops without n
index loops with i + 1 &lt; sz





Full Program: Safe Line Reader and Copy
#include &lt;stdio.h&gt;
#include &lt;string.h&gt;

enum { LINE_MAX = 128 };

static int read_line(char *buf, size_t buf_sz) {
    if (buf == NULL || buf_sz == 0) {
        return -1;
    }
    if (fgets(buf, (int)buf_sz, stdin) == NULL) {
        return -1;
    }
    size_t n = strlen(buf);
    if (n &gt; 0 && buf[n - 1] == '\n') {
        buf[n - 1] = '\0';
    } else {
        /* Line may have been longer than buffer — drain rest of line */
        int c;
        int overflow = (n == buf_sz - 1);
        if (overflow) {
            while ((c = getchar()) != '\n' && c != EOF) {
                /* discard */
            }
            return -2;  /* truncated */
        }
    }
    return 0;
}

int main(void) {
    char name[LINE_MAX];
    char greeting[LINE_MAX];

    printf("Enter your name: ");
    int rc = read_line(name, sizeof name);
    if (rc == -1) {
        fprintf(stderr, "no input\n");
        return 1;
    }
    if (rc == -2) {
        fprintf(stderr, "input too long (truncated)\n");
    }

    if (snprintf(greeting, sizeof greeting, "Hello, %s!", name) &lt; 0) {
        return 1;
    }
    printf("%s\n", greeting);
    return 0;
}


