Practical Examples

Sudoku Validator
#include &lt;stdio.h&gt;
#include &lt;stdbool.h&gt;

#define SIZE 9

bool is_valid_sudoku(int board[SIZE][SIZE]) {
    // Check rows
    for (int i = 0; i &lt; SIZE; i++) {
        bool seen[SIZE + 1] = {false};
        for (int j = 0; j &lt; SIZE; j++) {
            if (board[i][j] != 0) {
                if (seen[board[i][j]]) return false;
                seen[board[i][j]] = true;
            }
        }
    }

    // Check columns
    for (int j = 0; j &lt; SIZE; j++) {
        bool seen[SIZE + 1] = {false};
        for (int i = 0; i &lt; SIZE; i++) {
            if (board[i][j] != 0) {
                if (seen[board[i][j]]) return false;
                seen[board[i][j]] = true;
            }
        }
    }

    // Check 3x3 boxes
    for (int box_row = 0; box_row &lt; 3; box_row++) {
        for (int box_col = 0; box_col &lt; 3; box_col++) {
            bool seen[SIZE + 1] = {false};
            for (int i = 0; i &lt; 3; i++) {
                for (int j = 0; j &lt; 3; j++) {
                    int row = box_row * 3 + i;
                    int col = box_col * 3 + j;
                    if (board[row][col] != 0) {
                        if (seen[board[row][col]]) return false;
                        seen[board[row][col]] = true;
                    }
                }
            }
        }
    }

    return true;
}

int main() {
    int sudoku[SIZE][SIZE] = {
        {5, 3, 0, 0, 7, 0, 0, 0, 0},
        {6, 0, 0, 1, 9, 5, 0, 0, 0},
        {0, 9, 8, 0, 0, 0, 0, 6, 0},
        {8, 0, 0, 0, 6, 0, 0, 0, 3},
        {4, 0, 0, 8, 0, 3, 0, 0, 1},
        {7, 0, 0, 0, 2, 0, 0, 0, 6},
        {0, 6, 0, 0, 0, 0, 2, 8, 0},
        {0, 0, 0, 4, 1, 9, 0, 0, 5},
        {0, 0, 0, 0, 8, 0, 0, 7, 9}
    };

    if (is_valid_sudoku(sudoku)) {
        printf("Valid Sudoku\n");
    } else {
        printf("Invalid Sudoku\n");
    }

    return 0;
}


Image Processing Example
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

#define WIDTH 100
#define HEIGHT 100

// Simple image structure
typedef struct {
    unsigned char pixels[HEIGHT][WIDTH][3];  // RGB pixels
    int width, height;
} Image;

// Convert to grayscale
void grayscale(Image *img) {
    for (int i = 0; i &lt; img-&gt;height; i++) {
        for (int j = 0; j &lt; img-&gt;width; j++) {
            // Calculate grayscale value
            unsigned char gray = (img-&gt;pixels[i][j][0] * 0.3 +
                                img-&gt;pixels[i][j][1] * 0.59 +
                                img-&gt;pixels[i][j][2] * 0.11);

            // Set all channels to grayscale value
            img-&gt;pixels[i][j][0] = gray;
            img-&gt;pixels[i][j][1] = gray;
            img-&gt;pixels[i][j][2] = gray;
        }
    }
}

// Apply simple blur filter
void blur(Image *img) {
    // Create a copy for processing
    unsigned char temp[HEIGHT][WIDTH][3];

    for (int i = 1; i &lt; img-&gt;height - 1; i++) {
        for (int j = 1; j &lt; img-&gt;width - 1; j++) {
            for (int c = 0; c &lt; 3; c++) {
                // Average of 3x3 neighborhood
                int sum = 0;
                for (int di = -1; di &lt;= 1; di++) {
                    for (int dj = -1; dj &lt;= 1; dj++) {
                        sum += img-&gt;pixels[i + di][j + dj][c];
                    }
                }
                temp[i][j][c] = sum / 9;
            }
        }
    }

    // Copy back to original image
    for (int i = 1; i &lt; img-&gt;height - 1; i++) {
        for (int j = 1; j &lt; img-&gt;width - 1; j++) {
            for (int c = 0; c &lt; 3; c++) {
                img-&gt;pixels[i][j][c] = temp[i][j][c];
            }
        }
    }
}

What Is a Pointer?
Every object in your program lives at a memory address. The address-of operator & yields that address; the dereference operator * follows a pointer to the object.
#include &lt;stdio.h&gt;

int main(void) {
    int x = 42;
    printf("Value of x:   %d\n", x);
    printf("Address of x: %p\n", (void *)&x);
    return 0;
}
Always cast to void * when printing with %p.

Visual Step-by-Step: & and *
Think of memory as numbered boxes. Variable names label boxes; pointers hold box numbers.

Step 1 — Create an int
int x = 42;
  name: x
  ┌────────┐
  │   42   │   address e.g. 0x1000
  └────────┘


Step 2 — Point at it
int *p = &x;   /* p holds the address of x */
  name: p                      name: x
  ┌──────────┐                 ┌────────┐
  │  0x1000  │ ──────────────► │   42   │  0x1000
  └──────────┘                 └────────┘


Step 3 — Read through the pointer
int y = *p;    /* y becomes 42 */
*p means “the int sitting at the address stored in p.”


Step 4 — Write through the pointer
*p = 99;       /* x is now 99 */
  p ──► x: 99


Full Demo Program
#include &lt;stdio.h&gt;

int main(void) {
    int x = 42;
    int *p = &x;

    printf("1) x=%d  &x=%p  p=%p  *p=%d\n",
           x, (void *)&x, (void *)p, *p);

    *p = 99;
    printf("2) after *p=99: x=%d  *p=%d\n", x, *p);

    x = 7;
    printf("3) after x=7:   x=%d  *p=%d\n", x, *p);

    int z = 100;
    p = &z;
    printf("4) p now points at z: *p=%d  x still %d\n", *p, x);
    return 0;
}
