    size_t data_size;
} LinkedList;

LinkedList* create_list(size_t data_size) {
    LinkedList *list = malloc(sizeof(LinkedList));
    if (list != NULL) {
        list-&gt;head = NULL;
        list-&gt;data_size = data_size;
    }
    return list;
}

void list_append(LinkedList *list, const void *data) {
    Node *new_node = malloc(sizeof(Node));
    if (new_node == NULL) return;

    new_node-&gt;data = malloc(list-&gt;data_size);
    if (new_node-&gt;data == NULL) {
        free(new_node);
        return;
    }

    // Copy data
    char *src = (char*)data;
    char *dest = (char*)new_node-&gt;data;
    for (size_t i = 0; i &lt; list-&gt;data_size; i++) {
        dest[i] = src[i];
    }

    new_node-&gt;next = NULL;

    // Add to end of list
    if (list-&gt;head == NULL) {
        list-&gt;head = new_node;
    } else {
        Node *current = list-&gt;head;
        while (current-&gt;next != NULL) {
            current = current-&gt;next;
        }
        current-&gt;next = new_node;
    }
}

void list_print_int(LinkedList *list) {
    Node *current = list-&gt;head;
    while (current != NULL) {
        printf("%d ", *(int*)current-&gt;data);
        current = current-&gt;next;
    }
    printf("\n");
}

void list_free(LinkedList *list) {
    Node *current = list-&gt;head;
    while (current != NULL) {
        Node *next = current-&gt;next;
        free(current-&gt;data);
        free(current);
        current = next;
    }
    free(list);
}

int main() {
    LinkedList *int_list = create_list(sizeof(int));

    // Add integers to list
    for (int i = 1; i &lt;= 5; i++) {
        list_append(int_list, &i);
    }

    printf("List contents: ");
    list_print_int(int_list);

    list_free(int_list);

    return 0;
}


Event System with Function Pointers
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

// Event types
typedef enum {
    EVENT_CLICK,
    EVENT_KEYPRESS,
    EVENT_MOUSEMOVE,
    EVENT_COUNT
} EventType;

// Event data structures
typedef struct {
    int x, y;
} ClickEvent;

typedef struct {
    char key;
} KeyPressEvent;

typedef struct {
    int x, y;
} MouseMoveEvent;

// Event handler function type
typedef void (*EventHandler)(void *event_data);

// Event system structure
typedef struct {
    EventHandler handlers[EVENT_COUNT];
} EventSystem;

// Event handler functions
void handle_click(void *data) {
    ClickEvent *event = (ClickEvent*)data;
    printf("Click at (%d, %d)\n", event-&gt;x, event-&gt;y);
}

void handle_keypress(void *data) {
    KeyPressEvent *event = (KeyPressEvent*)data;
    printf("Key pressed: %c\n", event-&gt;key);
}

void handle_mousemove(void *data) {
    MouseMoveEvent *event = (MouseMoveEvent*)data;
    printf("Mouse moved to (%d, %d)\n", event-&gt;x, event-&gt;y);
}

// Event system functions
EventSystem* create_event_system() {
    EventSystem *system = malloc(sizeof(EventSystem));
    if (system != NULL) {
        for (int i = 0; i &lt; EVENT_COUNT; i++) {
            system-&gt;handlers[i] = NULL;
        }
    }
    return system;
}

void register_handler(EventSystem *system, EventType type, EventHandler handler) {
    if (type &gt;= 0 && type &lt; EVENT_COUNT) {
        system-&gt;handlers[type] = handler;
    }
}

void trigger_event(EventSystem *system, EventType type, void *event_data) {
    if (type &gt;= 0 && type &lt; EVENT_COUNT && system-&gt;handlers[type] != NULL) {
        system-&gt;handlers[type](event_data);
    }
}

void destroy_event_system(EventSystem *system) {
    free(system);
}

int main() {
    EventSystem *events = create_event_system();

    // Register event handlers
    register_handler(events, EVENT_CLICK, handle_click);
    register_handler(events, EVENT_KEYPRESS, handle_keypress);
    register_handler(events, EVENT_MOUSEMOVE, handle_mousemove);

    // Trigger events
    ClickEvent click = {100, 200};
    trigger_event(events, EVENT_CLICK, &click);

    KeyPressEvent keypress = {'A'};
    trigger_event(events, EVENT_KEYPRESS, &keypress);

    MouseMoveEvent mousemove = {50, 75};
    trigger_event(events, EVENT_MOUSEMOVE, &mousemove);

    destroy_event_system(events);

    return 0;
}

Dangling Pointers

What Are Dangling Pointers?
A dangling pointer is a pointer that points to memory that has been deallocated or is no longer valid. Dereferencing a dangling pointer leads to undefined behavior.


Common Causes

1. Premature Deallocation
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

int* create_integer(int value) {
    int *ptr = malloc(sizeof(int));
    if (ptr != NULL) {
        *ptr = value;
    }
    return ptr;
}

int main() {
    int *ptr = create_integer(42);

    // Problem: Using pointer after deallocation
    free(ptr);
    printf("Value: %d\n", *ptr);  // Dangling pointer - undefined behavior!

    return 0;
}


2. Returning Pointer to Local Variable
#include &lt;stdio.h&gt;

int* get_pointer() {
    int local_var = 42;
    return &local_var;  // Problem: Returning pointer to local variable
}

int main() {
    int *ptr = get_pointer();
    printf("Value: %d\n", *ptr);  // Dangling pointer - undefined behavior!

    return 0;
}



Prevention Strategies

1. Set Pointers to NULL After Freeing
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

int main() {
    int *ptr = malloc(sizeof(int));
    if (ptr != NULL) {
        *ptr = 42;
        printf("Value: %d\n", *ptr);

        free(ptr);
        ptr = NULL;  // Prevent dangling pointer

        // Safe check before use
        if (ptr != NULL) {
            printf("Value: %d\n", *ptr);
        } else {
            printf("Pointer is NULL\n");
        }
    }

    return 0;
}


2. Avoid Returning Pointers to Local Variables
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

// Solution 1: Use dynamic allocation
int* create_integer_safe(int value) {
    int *ptr = malloc(sizeof(int));
    if (ptr != NULL) {
        *ptr = value;
    }
    return ptr;
}

// Solution 2: Use output parameters
void get_value(int *output) {
    *output = 42;  // Modify through parameter
}

int main() {
    // Using dynamic allocation
    int *ptr = create_integer_safe(42);
    if (ptr != NULL) {
        printf("Value: %d\n", *ptr);
        free(ptr);
    }

    // Using output parameter
    int value;
    get_value(&value);
    printf("Value: %d\n", value);

    return 0;
}

Memory Leaks

What Are Memory Leaks?
A memory leak occurs when dynamically allocated memory is not properly deallocated, making it unavailable for reuse during program execution.


Common Causes

1. Forgetting to Call free()
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

void memory_leak_example() {
    int *ptr = malloc(100 * sizeof(int));
    if (ptr != NULL) {
        // Use the memory...
        for (int i = 0; i &lt; 100; i++) {
            ptr[i] = i;
        }

        // Problem: Forgot to call free() - memory leak!
        // free(ptr);
    }
}

int main() {
    for (int i = 0; i &lt; 1000; i++) {
        memory_leak_example();  // Leaks 400 bytes each iteration
    }

    return 0;
}


2. Losing Pointer References
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

int main() {
    int *ptr1 = malloc(100 * sizeof(int));
    int *ptr2 = malloc(100 * sizeof(int));

    if (ptr1 != NULL && ptr2 != NULL) {
        // Use memory...

        // Problem: Losing reference to ptr1 - memory leak!
        ptr1 = ptr2;

        free(ptr2);  // Only frees one block
        // ptr1's memory is leaked
    }

    return 0;
}



Prevention Strategies

1. Use RAII-like Patterns
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

typedef struct {
    int *data;
    size_t size;
} ManagedArray;

ManagedArray* create_array(size_t size) {
    ManagedArray *arr = malloc(sizeof(ManagedArray));
    if (arr != NULL) {
        arr-&gt;data = malloc(size * sizeof(int));
        if (arr-&gt;data == NULL) {
            free(arr);
            return NULL;
        }
        arr-&gt;size = size;
    }
    return arr;
}

void destroy_array(ManagedArray *arr) {
    if (arr != NULL) {
        free(arr-&gt;data);
        free(arr);
    }
}

int main() {
    ManagedArray *arr = create_array(100);
    if (arr != NULL) {
        // Use array...

        // Always clean up
        destroy_array(arr);
    }

    return 0;
}


2. Match Every malloc with free
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

void safe_memory_usage() {
    int *ptr = malloc(100 * sizeof(int));
    if (ptr == NULL) {
        return;  // Handle allocation failure
    }

    // Use the memory...
    for (int i = 0; i &lt; 100; i++) {
        ptr[i] = i;
    }

    // Always free allocated memory
    free(ptr);
    ptr = NULL;  // Prevent dangling pointer
}

Buffer Overflows

What Are Buffer Overflows?
A buffer overflow occurs when more data is written to a buffer than it can hold, potentially corrupting adjacent memory.


Common Causes

1. Array Index Out of Bounds
#include &lt;stdio.h&gt;

int main() {
    int arr[5] = {1, 2, 3, 4, 5};

    // Problem: Writing beyond array bounds
    for (int i = 0; i &lt; 10; i++) {  // i goes to 9, but array only has 5 elements
        arr[i] = i * i;  // Buffer overflow when i &gt;= 5
    }

    return 0;
}


2. String Buffer Overflows
#include &lt;stdio.h&gt;
#include &lt;string.h&gt;

int main() {
    char buffer[10];

    // Problem: String too long for buffer
    strcpy(buffer, "This string is too long for the buffer!");
    // Buffer overflow - undefined behavior!

    return 0;
}



Prevention Strategies

1. Always Check Array Bounds
#include &lt;stdio.h&gt;

int main() {
    int arr[5] = {1, 2, 3, 4, 5};
    int size = sizeof(arr) / sizeof(arr[0]);

    // Safe: Check bounds before access
    for (int i = 0; i &lt; size; i++) {
        arr[i] = i * i;
    }

    // Alternative: Use safer loop
    for (int i = 0; i &lt; 5; i++) {
        arr[i] = i * i;
    }

    return 0;
}


2. Use Safe String Functions
#include &lt;stdio.h&gt;
#include &lt;string.h&gt;

int main() {
    char buffer[10];

    // Safe: Use strncpy with proper bounds checking
    const char *source = "This string is too long";
    strncpy(buffer, source, sizeof(buffer) - 1);
    buffer[sizeof(buffer) - 1] = '\0';  // Ensure null termination

    printf("Buffer: %s\n", buffer);

    return 0;
}

Uninitialized Pointers

What Are Uninitialized Pointers?
An uninitialized pointer contains garbage values and points to random memory locations. Dereferencing such pointers leads to undefined behavior.


Common Causes

1. Using Uninitialized Local Pointers
#include &lt;stdio.h&gt;

int main() {
    int *ptr;  // Uninitialized pointer

    // Problem: Using uninitialized pointer
    *ptr = 42;  // Undefined behavior!

    return 0;
}


2. Partial Initialization
#include &lt;stdio.h&gt;

int main() {
    int *ptr1, *ptr2;

    ptr1 = malloc(sizeof(int));
    if (ptr1 != NULL) {
        *ptr1 = 42;
    }

    // Problem: ptr2 is uninitialized
    *ptr2 = 100;  // Undefined behavior!

    free(ptr1);

    return 0;
}



Prevention Strategies

1. Always Initialize Pointers
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

int main() {
    // Good: Initialize to NULL
    int *ptr = NULL;

    // Safe: Check before use
    if (ptr != NULL) {
        *ptr = 42;
    }

    // Or initialize with valid address
    int value = 42;
    int *ptr2 = &value;  // Safe initialization

    printf("Value: %d\n", *ptr2);

    return 0;
}


2. Use Separate Declarations
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

int main() {
    // Good: Separate declarations for clarity
    int *ptr1 = NULL;
    int *ptr2 = NULL;

    ptr1 = malloc(sizeof(int));
    if (ptr1 != NULL) {
        *ptr1 = 42;
    }

    ptr2 = malloc(sizeof(int));
    if (ptr2 != NULL) {
        *ptr2 = 100;
    }

    // Safe usage
    if (ptr1 != NULL) {
        printf("ptr1: %d\n", *ptr1);
    }

    if (ptr2 != NULL) {
        printf("ptr2: %d\n", *ptr2);
    }

    // Clean up
    free(ptr1);
    free(ptr2);

    return 0;
}

Pointer Arithmetic Errors

Common Mistakes

1. Incorrect Pointer Arithmetic
#include &lt;stdio.h&gt;

int main() {
    int arr[5] = {1, 2, 3, 4, 5};
    int *ptr = arr;

    // Problem: Incorrect arithmetic
    ptr = ptr + 10;  // Points beyond array bounds

    // Undefined behavior when dereferencing
    // printf("Value: %d\n", *ptr);

    return 0;
}


2. Pointer Arithmetic with Different Types
#include &lt;stdio.h&gt;

int main() {
    int arr[5] = {1, 2, 3, 4, 5};
    char *char_ptr = (char*)arr;

    // Problem: Different pointer arithmetic
    printf("int ptr + 1: %p\n", (void*)(arr + 1));
    printf("char ptr + 1: %p\n", (void*)(char_ptr + 1));
    // These point to different memory locations!

    return 0;
}



Prevention Strategies

1. Validate Pointer Arithmetic
#include &lt;stdio.h&gt;

int main() {
    int arr[5] = {1, 2, 3, 4, 5};
    int *ptr = arr;
    int size = sizeof(arr) / sizeof(arr[0]);

    // Safe: Validate bounds before arithmetic
    int offset = 2;
    if (offset &gt;= 0 && offset &lt; size) {
        int *new_ptr = ptr + offset;
        printf("Value at offset %d: %d\n", offset, *new_ptr);
    } else {
        printf("Offset out of bounds\n");
    }

    return 0;
}

NULL Pointer Dereferencing

What Is NULL Pointer Dereferencing?
Dereferencing a NULL pointer leads to program crashes or undefined behavior.


Common Causes

1. Forgetting to Check Return Values
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

int main() {
    int *ptr = malloc(100 * sizeof(int));

    // Problem: Not checking for NULL
    *ptr = 42;  // Crash if malloc failed!

    free(ptr);

    return 0;
}



Prevention Strategies

1. Always Check for NULL
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

int main() {
    int *ptr = malloc(100 * sizeof(int));

    // Safe: Check for NULL
    if (ptr != NULL) {
        *ptr = 42;
        printf("Value: %d\n", *ptr);
        free(ptr);
    } else {
        printf("Memory allocation failed\n");
        return 1;
    }

    return 0;
}

Type Safety Issues

Common Problems

1. Incorrect Casting
#include &lt;stdio.h&gt;

int main() {
    int x = 42;
    int *int_ptr = &x;

    // Problem: Incorrect casting
    char *char_ptr = (char*)int_ptr;
    printf("Char value: %c\n", *char_ptr);  // Interprets as character

    return 0;
}


2. Function Pointer Mismatches
#include &lt;stdio.h&gt;

int add(int a, int b) { return a + b; }
void print_message(void) { printf("Hello\n"); }

int main() {
    // Problem: Wrong function pointer type
    int (*func_ptr)(int, int) = (int (*)(int, int))print_message;

    // Undefined behavior when called
    // int result = func_ptr(5, 3);

    return 0;
}



Prevention Strategies

1. Use Proper Typedefs
#include &lt;stdio.h&gt;

// Safe: Use typedef for function pointers
typedef int (*binary_op)(int, int);

int add(int a, int b) { return a + b; }
int subtract(int a, int b) { return a - b; }

int main() {
    binary_op operations[] = {add, subtract};

    int result1 = operations[0](10, 5);  // Safe: add(10, 5)
    int result2 = operations[1](10, 5);  // Safe: subtract(10, 5)

    printf("10 + 5 = %d\n", result1);
    printf("10 - 5 = %d\n", result2);

    return 0;
}

Best Practices for Pointer Safety

1. Initialize Pointers
// Good
int *ptr = NULL;

// Good
int value = 42;
int *ptr = &value;

// Bad
int *ptr;  // Uninitialized


2. Check for NULL
int *ptr = malloc(sizeof(int));
if (ptr != NULL) {
    *ptr = 42;
    // Use ptr...
    free(ptr);
    ptr = NULL;
}


3. Validate Array Bounds
int arr[10];
int size = sizeof(arr) / sizeof(arr[0]);

for (int i = 0; i &lt; size; i++) {
    arr[i] = i;
}


4. Use Safe String Functions
char buffer[100];
const char *source = "Some text";

// Safe copy
strncpy(buffer, source, sizeof(buffer) - 1);
buffer[sizeof(buffer) - 1] = '\0';


5. Match Allocation with Deallocation
// For malloc/calloc/realloc
int *ptr = malloc(100 * sizeof(int));
// ... use ptr ...
free(ptr);
ptr = NULL;

// For arrays
int *arr = calloc(100, sizeof(int));
// ... use arr ...
free(arr);
arr = NULL;

Practical Example: Safe Dynamic Array
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;

typedef struct {
    int *data;
    size_t size;
    size_t capacity;
} SafeArray;

SafeArray* safe_array_create(size_t initial_capacity) {
    SafeArray *arr = malloc(sizeof(SafeArray));
    if (arr == NULL) {
        return NULL;
    }

    arr-&gt;data = malloc(initial_capacity * sizeof(int));
    if (arr-&gt;data == NULL) {
        free(arr);
        return NULL;
    }

    arr-&gt;size = 0;
    arr-&gt;capacity = initial_capacity;
    return arr;
}

int safe_array_push(SafeArray *arr, int value) {
    if (arr == NULL) {
        return -1;  // Error: NULL pointer
    }

    // Resize if needed
    if (arr-&gt;size &gt;= arr-&gt;capacity) {
        size_t new_capacity = arr-&gt;capacity * 2;
        int *temp = realloc(arr-&gt;data, new_capacity * sizeof(int));
        if (temp == NULL) {
            return -1;  // Error: Reallocation failed
        }
        arr-&gt;data = temp;
        arr-&gt;capacity = new_capacity;
    }

    arr-&gt;data[arr-&gt;size] = value;
    arr-&gt;size++;
    return 0;  // Success
}

int safe_array_get(SafeArray *arr, size_t index) {
    if (arr == NULL || index &gt;= arr-&gt;size) {
        return 0;  // Error: Invalid parameters
    }
    return arr-&gt;data[index];
}

void safe_array_destroy(SafeArray *arr) {
    if (arr != NULL) {
        free(arr-&gt;data);
        free(arr);
    }
}

int main() {
    SafeArray *arr = safe_array_create(2);
    if (arr == NULL) {
        printf("Array creation failed\n");
        return 1;
    }

    // Add elements
    for (int i = 0; i &lt; 10; i++) {
        if (safe_array_push(arr, i * i) != 0) {
            printf("Array push failed\n");
            safe_array_destroy(arr);
            return 1;
        }
    }

    // Print elements
    printf("Array elements: ");
    for (size_t i = 0; i &lt; arr-&gt;size; i++) {
        printf("%d ", safe_array_get(arr, i));
    }
    printf("\n");

    // Clean up
    safe_array_destroy(arr);

    return 0;
}

Structure Declaration and Definition

Basic Structure Declaration
A structure is declared using the struct keyword followed by the structure name and a list of members enclosed in braces:
struct Person {
    char name[50];
    int age;
    float height;
    char gender;
};


Structure Variable Declaration
Structure variables can be declared in several ways:
// Method 1: Declare structure and variables separately
struct Person {
    char name[50];
    int age;
    float height;
    char gender;
};

struct Person person1, person2;

// Method 2: Declare structure and variables together
struct {
    char name[50];
    int age;
    float height;
    char gender;
} person1, person2;

// Method 3: Use typedef for cleaner syntax
typedef struct {
    char name[50];
    int age;
    float height;
    char gender;
} Person;

Person person1, person2;

Structure Initialization

Designated Initializers (C99)
typedef struct {
    char name[50];
    int age;
    float height;
    char gender;
} Person;

// Initialize all members
Person person1 = {"John Doe", 25, 5.9, 'M'};

// Designated initializers (C99)
Person person2 = {
    .name = "Jane Smith",
    .age = 30,
    .height = 5.5,
    .gender = 'F'
};

// Partial initialization
Person person3 = {
    .name = "Bob Johnson",
    .age = 35
    // height and gender will be zero-initialized
};


Nested Structure Initialization
typedef struct {
    int day;
    int month;
    int year;
} Date;

typedef struct {
    char name[50];
    Date birth_date;
    float salary;
} Employee;

// Nested structure initialization
Employee emp = {
    .name = "Alice Brown",
    .birth_date = {15, 6, 1990},
    .salary = 75000.0
};

// Designated initialization with nested structures
Employee emp2 = {
    .name = "Charlie Wilson",
    .birth_date.day = 20,
    .birth_date.month = 3,
    .birth_date.year = 1985,
    .salary = 80000.0
};

Accessing Structure Members

Dot Operator (.)
The dot operator is used to access members of a structure variable:
typedef struct {
    char name[50];
    int age;
    float height;
    char gender;
} Person;

int main() {
    Person person = {"John Doe", 25, 5.9, 'M'};

    // Access members using dot operator
    printf("Name: %s\n", person.name);
    printf("Age: %d\n", person.age);
    printf("Height: %.1f\n", person.height);
    printf("Gender: %c\n", person.gender);

    // Modify members
    person.age = 26;
    person.height = 6.0;
    strcpy(person.name, "John Smith");

    return 0;
}


Arrow Operator (-&gt;)
The arrow operator is used to access members through a pointer to a structure:
typedef struct {
    char name[50];
    int age;
    float height;
    char gender;
} Person;

int main() {
    Person person = {"John Doe", 25, 5.9, 'M'};
    Person *ptr = &person;

    // Access members using arrow operator
    printf("Name: %s\n", ptr-&gt;name);
    printf("Age: %d\n", ptr-&gt;age);
    printf("Height: %.1f\n", ptr-&gt;height);
    printf("Gender: %c\n", ptr-&gt;gender);

    // Modify members through pointer
    ptr-&gt;age = 26;
    ptr-&gt;height = 6.0;
    strcpy(ptr-&gt;name, "John Smith");

    return 0;
}

Arrays of Structures

Declaration and Initialization
typedef struct {
    char name[50];
    int id;
    float gpa;
} Student;

int main() {
    // Array of structures
    Student students[3] = {
        {"Alice", 101, 3.8},
        {"Bob", 102, 3.5},
        {"Charlie", 103, 3.9}
    };

    // Access array elements
    for (int i = 0; i &lt; 3; i++) {
        printf("Student %d: %s, ID: %d, GPA: %.1f\n",
               i + 1, students[i].name, students[i].id, students[i].gpa);
    }

    return 0;
}


Dynamic Array of Structures
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;

typedef struct {
    char name[50];
    int id;
    float gpa;
} Student;

int main() {
    int count = 3;

    // Dynamic array of structures
    Student *students = malloc(count * sizeof(Student));
    if (students == NULL) {
        printf("Memory allocation failed\n");
        return 1;
    }

    // Initialize array elements
    strcpy(students[0].name, "Alice");
    students[0].id = 101;
    students[0].gpa = 3.8;

    strcpy(students[1].name, "Bob");
    students[1].id = 102;
    students[1].gpa = 3.5;

    strcpy(students[2].name, "Charlie");
    students[2].id = 103;
    students[2].gpa = 3.9;

    // Access array elements
    for (int i = 0; i &lt; count; i++) {
        printf("Student %d: %s, ID: %d, GPA: %.1f\n",
               i + 1, students[i].name, students[i].id, students[i].gpa);
    }

    // Free memory
    free(students);

    return 0;
}

Nested Structures

Basic Nested Structures
typedef struct {
    int day;
    int month;
    int year;
} Date;

typedef struct {
    char street[100];
    char city[50];
    char state[30];
    int zip_code;
} Address;

typedef struct {
    char name[50];
    Date birth_date;
    Address home_address;
    float salary;
} Employee;

int main() {
    Employee emp = {
        .name = "John Doe",
        .birth_date = {15, 6, 1990},
        .home_address = {
            .street = "123 Main St",
            .city = "Anytown",
            .state = "CA",
            .zip_code = 12345
        },
        .salary = 75000.0
    };

    // Access nested structure members
    printf("Name: %s\n", emp.name);
    printf("Birth Date: %d/%d/%d\n", 
           emp.birth_date.month, emp.birth_date.day, emp.birth_date.year);
    printf("Address: %s, %s, %s %d\n",
           emp.home_address.street, emp.home_address.city,
           emp.home_address.state, emp.home_address.zip_code);
    printf("Salary: $%.2f\n", emp.salary);

    return 0;
}


Self-Referential Structures
Structures can contain pointers to their own type, enabling linked data structures:
typedef struct Node {
    int data;
    struct Node *next;  // Pointer to same structure type
} Node;

int main() {
    // Create nodes
    Node node1 = {10, NULL};
    Node node2 = {20, NULL};
    Node node3 = {30, NULL};

    // Link nodes
    node1.next = &node2;
    node2.next = &node3;

    // Traverse linked list
    Node *current = &node1;
    while (current != NULL) {
        printf("Data: %d\n", current-&gt;data);
        current = current-&gt;next;
    }

    return 0;
}

Structure Assignment and Comparison

Structure Assignment
Structures can be assigned to each other if they are of the same type:
typedef struct {
    char name[50];
    int age;
    float height;
} Person;

int main() {
    Person person1 = {"John Doe", 25, 5.9};
    Person person2;

    // Structure assignment
    person2 = person1;

    printf("Person 1: %s, %d, %.1f\n", person1.name, person1.age, person1.height);
    printf("Person 2: %s, %d, %.1f\n", person2.name, person2.age, person2.height);

    return 0;
}


Structure Comparison
Structures cannot be directly compared using comparison operators. You need to compare members individually:
typedef struct {
    char name[50];
    int age;
    float height;
} Person;

int compare_persons(const Person *p1, const Person *p2) {
    // Compare names
    int name_cmp = strcmp(p1-&gt;name, p2-&gt;name);
    if (name_cmp != 0) return name_cmp;

    // Compare ages
    if (p1-&gt;age != p2-&gt;age) return p1-&gt;age - p2-&gt;age;

    // Compare heights
    if (p1-&gt;height &lt; p2-&gt;height) return -1;
    if (p1-&gt;height &gt; p2-&gt;height) return 1;

    return 0;  // Structures are equal
}

int main() {
    Person person1 = {"John Doe", 25, 5.9};
    Person person2 = {"John Doe", 25, 5.9};

    if (compare_persons(&person1, &person2) == 0) {
        printf("Persons are equal\n");
    } else {
        printf("Persons are different\n");
    }

    return 0;
}

Passing Structures to Functions

Pass by Value
When passing structures by value, a copy of the entire structure is made:
typedef struct {
    char name[50];
    int age;
    float height;
} Person;

void print_person(Person p) {
    printf("Name: %s\n", p.name);
    printf("Age: %d\n", p.age);
    printf("Height: %.1f\n", p.height);
}

void modify_person(Person p) {
    // Modifications affect only the copy
    p.age = 30;
    strcpy(p.name, "Modified Name");
}

int main() {
    Person person = {"John Doe", 25, 5.9};

    printf("Before modification:\n");
    print_person(person);

    modify_person(person);

    printf("After modification:\n");
    print_person(person);  // Original unchanged

    return 0;
}


Pass by Reference (Pointer)
Passing pointers to structures is more efficient and allows modification:
typedef struct {
    char name[50];
    int age;
    float height;
} Person;

void print_person(const Person *p) {
    printf("Name: %s\n", p-&gt;name);
    printf("Age: %d\n", p-&gt;age);
    printf("Height: %.1f\n", p-&gt;height);
}

void modify_person(Person *p) {
    // Modifications affect the original structure
    p-&gt;age = 30;
    strcpy(p-&gt;name, "Modified Name");
}

int main() {
    Person person = {"John Doe", 25, 5.9};

    printf("Before modification:\n");
    print_person(&person);

    modify_person(&person);

    printf("After modification:\n");
    print_person(&person);  // Original changed

    return 0;
}

Structure Size and Memory Layout

Calculating Structure Size
#include &lt;stdio.h&gt;

typedef struct {
    char a;      // 1 byte
    int b;       // 4 bytes
    char c;      // 1 byte
} Example;

int main() {
    printf("Size of char: %zu bytes\n", sizeof(char));
    printf("Size of int: %zu bytes\n", sizeof(int));
    printf("Size of Example: %zu bytes\n", sizeof(Example));
    // Note: Size may be larger than sum due to padding

    return 0;
}


Memory Alignment
Compilers may add padding to ensure proper alignment:
#include &lt;stdio.h&gt;

// Without pragma pack
typedef struct {
    char a;      // 1 byte
    int b;       // 4 bytes (may have 3 bytes padding before)
    char c;      // 1 byte (may have 3 bytes padding after)
} Unpacked;

// With pragma pack (1) - no padding
#pragma pack(1)
typedef struct {
    char a;      // 1 byte
    int b;       // 4 bytes (no padding)
    char c;      // 1 byte (no padding)
} Packed;
#pragma pack()

int main() {
    printf("Size of Unpacked: %zu bytes\n", sizeof(Unpacked));
    printf("Size of Packed: %zu bytes\n", sizeof(Packed));

    return 0;
}

Practical Examples

Student Management System
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;

typedef struct {
    int id;
    char name[50];
    float grades[5];
    float average;
} Student;

void calculate_average(Student *student) {
    float sum = 0;
    for (int i = 0; i &lt; 5; i++) {
        sum += student-&gt;grades[i];
    }
    student-&gt;average = sum / 5;
}

void print_student(const Student *student) {
    printf("ID: %d\n", student-&gt;id);
    printf("Name: %s\n", student-&gt;name);
    printf("Grades: ");
    for (int i = 0; i &lt; 5; i++) {
        printf("%.1f ", student-&gt;grades[i]);
    }
    printf("\nAverage: %.2f\n", student-&gt;average);
    printf("------------------------\n");
}

int main() {
    Student students[3] = {
        {1, "Alice", {85.5, 90.0, 78.5, 92.0, 88.5}, 0},
        {2, "Bob", {76.0, 82.5, 79.0, 85.5, 81.0}, 0},
        {3, "Charlie", {95.0, 92.5, 98.0, 90.5, 94.0}, 0}
    };

    // Calculate averages
    for (int i = 0; i &lt; 3; i++) {
        calculate_average(&students[i]);
    }

    // Print student information
    for (int i = 0; i &lt; 3; i++) {
        print_student(&students[i]);
    }

    // Find student with highest average
    int top_student = 0;
    for (int i = 1; i &lt; 3; i++) {
        if (students[i].average &gt; students[top_student].average) {
            top_student = i;
        }
    }

    printf("Top student:\n");
    print_student(&students[top_student]);

    return 0;
}


Point Structure with Operations
#include &lt;stdio.h&gt;
#include &lt;math.h&gt;

typedef struct {
    double x;
    double y;
} Point;

// Function to create a point
Point create_point(double x, double y) {
    Point p = {x, y};
    return p;
}

// Function to calculate distance between two points
double distance(const Point *p1, const Point *p2) {
    double dx = p1-&gt;x - p2-&gt;x;
    double dy = p1-&gt;y - p2-&gt;y;
    return sqrt(dx * dx + dy * dy);
}

// Function to move a point
void move_point(Point *p, double dx, double dy) {
    p-&gt;x += dx;
    p-&gt;y += dy;
}

// Function to print a point
void print_point(const Point *p) {
    printf("(%.2f, %.2f)", p-&gt;x, p-&gt;y);
}

int main() {
    Point p1 = create_point(0, 0);
    Point p2 = create_point(3, 4);

    printf("Point 1: ");
    print_point(&p1);
    printf("\n");

    printf("Point 2: ");
    print_point(&p2);
    printf("\n");

    printf("Distance: %.2f\n", distance(&p1, &p2));

    move_point(&p1, 1, 1);
    printf("After moving Point 1: ");
    print_point(&p1);
    printf("\n");

    printf("New distance: %.2f\n", distance(&p1, &p2));

    return 0;
}

Unions

Union Declaration and Basics
A union is a special data type that allows storing different data types in the same memory location. Unlike structures where each member has its own memory, all members of a union share the same memory space.
#include &lt;stdio.h&gt;

union Data {
    int i;
    float f;
    char str[20];
};

int main() {
    union Data data;

    printf("Memory size occupied by data: %zu\n", sizeof(data));

    data.i = 10;
    printf("data.i: %d\n", data.i);

    data.f = 220.5;
    printf("data.f: %f\n", data.f);

    // Note: Previous value of data.i is lost
    printf("data.i after setting data.f: %d\n", data.i);

    strcpy(data.str, "C Programming");
    printf("data.str: %s\n", data.str);

    return 0;
}


Union Memory Layout
All members of a union occupy the same memory location, so the size of a union is the size of its largest member:
#include &lt;stdio.h&gt;

union Example {
    char c;        // 1 byte
    int i;         // 4 bytes (typically)
    double d;      // 8 bytes (typically)
    char str[20];  // 20 bytes
};

int main() {
    union Example ex;

    printf("Size of char: %zu bytes\n", sizeof(char));
    printf("Size of int: %zu bytes\n", sizeof(int));
    printf("Size of double: %zu bytes\n", sizeof(double));
    printf("Size of char[20]: %zu bytes\n", sizeof(char[20]));
    printf("Size of union Example: %zu bytes\n", sizeof(ex));

    // All members share the same memory address
    printf("Address of ex.c: %p\n", (void*)&ex.c);
    printf("Address of ex.i: %p\n", (void*)&ex.i);
    printf("Address of ex.d: %p\n", (void*)&ex.d);
    printf("Address of ex.str: %p\n", (void*)ex.str);

    return 0;
}


Practical Union Usage

1. Memory Optimization
Unions are useful when you need to store different types of data but only one at a time:
#include &lt;stdio.h&gt;
#include &lt;string.h&gt;

typedef enum {
    TYPE_INT,
    TYPE_FLOAT,
    TYPE_STRING
} DataType;

typedef struct {
    DataType type;
    union {
        int i;
        float f;
        char str[50];
    } data;
} Variant;

void print_variant(const Variant *v) {
    switch (v-&gt;type) {
        case TYPE_INT:
            printf("Integer: %d\n", v-&gt;data.i);
            break;
        case TYPE_FLOAT:
            printf("Float: %.2f\n", v-&gt;data.f);
            break;
        case TYPE_STRING:
            printf("String: %s\n", v-&gt;data.str);
            break;
    }
}

int main() {
    Variant var1 = {TYPE_INT, .data.i = 42};
    Variant var2 = {TYPE_FLOAT, .data.f = 3.14f};
    Variant var3 = {TYPE_STRING, .data = {.str = "Hello, World!"}};

    print_variant(&var1);
    print_variant(&var2);
    print_variant(&var3);

    return 0;
}


2. Hardware Register Representation
Unions are commonly used in embedded programming to represent hardware registers:
#include &lt;stdio.h&gt;
#include &lt;stdint.h&gt;

// 32-bit register with bit fields
typedef union {
    uint32_t value;
    struct {
        uint32_t enable : 1;
        uint32_t mode : 2;
        uint32_t reserved : 5;
        uint32_t frequency : 8;
        uint32_t address : 16;
    } bits;
} Register;

int main() {
    Register reg;

    // Set register value
    reg.value = 0x12345678;
    printf("Register value: 0x%08X\n", reg.value);
    printf("Enable: %d\n", reg.bits.enable);
    printf("Mode: %d\n", reg.bits.mode);
    printf("Frequency: %d\n", reg.bits.frequency);
    printf("Address: 0x%04X\n", reg.bits.address);

    // Modify individual bits
    reg.bits.enable = 1;
    reg.bits.mode = 2;
    printf("Modified register: 0x%08X\n", reg.value);

    return 0;
}



Anonymous Unions (C11)
C11 introduced anonymous unions, which allow direct access to union members without specifying the union name:
#include &lt;stdio.h&gt;

typedef struct {
    int type;
    union {
        int integer_value;
        float float_value;
        char string_value[20];
    };  // Anonymous union
} DataRecord;

int main() {
    DataRecord record;

    record.type = 1;
    record.integer_value = 42;  // Direct access to union member
    printf("Integer value: %d\n", record.integer_value);

    record.type = 2;
    record.float_value = 3.14f;  // Direct access to union member
    printf("Float value: %.2f\n", record.float_value);

    return 0;
}

Enumerations

Basic Enumeration Declaration
Enumerations provide a way to define named integer constants, making code more readable and maintainable:
#include &lt;stdio.h&gt;

// Basic enumeration
enum Color {
    RED,
    GREEN,
    BLUE
};

// Enumeration with typedef
typedef enum {
    MONDAY,
    TUESDAY,
    WEDNESDAY,
    THURSDAY,
    FRIDAY,
    SATURDAY,
    SUNDAY
} Day;

int main() {
    enum Color favorite_color = BLUE;
    Day today = WEDNESDAY;

    printf("Favorite color: %d\n", favorite_color);
    printf("Today is day: %d\n", today);

    // Using in switch statements
    switch (today) {
        case MONDAY:
            printf("It's Monday\n");
            break;
        case WEDNESDAY:
            printf("It's Wednesday\n");
            break;
        case FRIDAY:
            printf("It's Friday\n");
            break;
        default:
            printf("It's another day\n");
    }

    return 0;
}


Explicit Enumeration Values
Enumeration constants can be assigned specific values:
#include &lt;stdio.h&gt;

typedef enum {
    HTTP_OK = 200,
    HTTP_BAD_REQUEST = 400,
    HTTP_UNAUTHORIZED = 401,
    HTTP_FORBIDDEN = 403,
    HTTP_NOT_FOUND = 404,
    HTTP_INTERNAL_SERVER_ERROR = 500
} HttpStatusCode;

typedef enum {
    FLAG_NONE = 0,
    FLAG_READ = 1,
    FLAG_WRITE = 2,
    FLAG_EXECUTE = 4,
    FLAG_DELETE = 8
} FilePermission;

int main() {
    HttpStatusCode status = HTTP_NOT_FOUND;
    FilePermission permissions = FLAG_READ | FLAG_WRITE;

    printf("HTTP Status: %d\n", status);
    printf("Permissions: %d\n", permissions);

    // Check permissions using bitwise operations
    if (permissions & FLAG_READ) {
        printf("Read permission granted\n");
    }

    if (permissions & FLAG_EXECUTE) {
        printf("Execute permission granted\n");
    } else {
        printf("Execute permission denied\n");
    }

    return 0;
}


Enumeration with Negative Values
Enumerations can include negative values:
#include &lt;stdio.h&gt;

typedef enum {
    TEMPERATURE_FREEZING = 0,
    TEMPERATURE_COLD = 10,
    TEMPERATURE_WARM = 20,
    TEMPERATURE_HOT = 30,
    TEMPERATURE_BOILING = 100
} Temperature;

typedef enum {
    DIRECTION_NORTH = 0,
    DIRECTION_EAST = 90,
    DIRECTION_SOUTH = 180,
    DIRECTION_WEST = 270
} Direction;

// Enumeration with negative values
typedef enum {
    STATUS_ERROR = -1,
    STATUS_UNKNOWN = 0,
    STATUS_SUCCESS = 1
} Status;

int main() {
    Temperature temp = TEMPERATURE_HOT;
    Direction dir = DIRECTION_EAST;
