Enumeration Size and Type Specification (C23)
C23 introduces more control over enumeration types:
#include &lt;stdio.h&gt;

// Specify underlying type (C23 feature)
typedef enum : unsigned char {
    SMALL_RED,
    SMALL_GREEN,
    SMALL_BLUE
} SmallColor;

typedef enum : long long {
    LARGE_VALUE1 = 1000000000000LL,
    LARGE_VALUE2 = 2000000000000LL
} LargeEnum;

int main() {
    SmallColor color = SMALL_GREEN;
    LargeEnum large = LARGE_VALUE2;

    printf("Size of SmallColor: %zu bytes\n", sizeof(color));
    printf("Size of LargeEnum: %zu bytes\n", sizeof(large));
    printf("SmallColor value: %d\n", color);
    printf("LargeEnum value: %lld\n", large);

    return 0;
}

Combining Unions and Enumerations

Tagged Union Pattern
A common pattern combines unions with enumerations to create type-safe variant types:
#include &lt;stdio.h&gt;
#include &lt;string.h&gt;

typedef enum {
    VALUE_INTEGER,
    VALUE_FLOAT,
    VALUE_STRING,
    VALUE_BOOLEAN
} ValueType;

typedef struct {
    ValueType type;
    union {
        int integer_value;
        float float_value;
        char string_value[100];
        int boolean_value;  // 0 = false, 1 = true
    } data;
} Value;

// Constructor functions
Value create_integer(int value) {
    Value v = {VALUE_INTEGER, .data.integer_value = value};
    return v;
}

Value create_float(float value) {
    Value v = {VALUE_FLOAT, .data.float_value = value};
    return v;
}

Value create_string(const char *value) {
    Value v = {VALUE_STRING};
    strncpy(v.data.string_value, value, sizeof(v.data.string_value) - 1);
    v.data.string_value[sizeof(v.data.string_value) - 1] = '\0';
    return v;
}

Value create_boolean(int value) {
    Value v = {VALUE_BOOLEAN, .data.boolean_value = value ? 1 : 0};
    return v;
}

// Print function
void print_value(const Value *v) {
    switch (v-&gt;type) {
        case VALUE_INTEGER:
            printf("Integer: %d\n", v-&gt;data.integer_value);
            break;
        case VALUE_FLOAT:
            printf("Float: %.2f\n", v-&gt;data.float_value);
            break;
        case VALUE_STRING:
            printf("String: %s\n", v-&gt;data.string_value);
            break;
        case VALUE_BOOLEAN:
            printf("Boolean: %s\n", v-&gt;data.boolean_value ? "true" : "false");
            break;
    }
}

int main() {
    Value values[] = {
        create_integer(42),
        create_float(3.14f),
        create_string("Hello, World!"),
        create_boolean(1)
    };

    int count = sizeof(values) / sizeof(values[0]);

    for (int i = 0; i &lt; count; i++) {
        print_value(&values[i]);
    }

    return 0;
}


Configuration Structure with Unions
Using unions and enumerations for flexible configuration:
#include &lt;stdio.h&gt;
#include &lt;string.h&gt;

typedef enum {
    CONFIG_TYPE_INT,
    CONFIG_TYPE_FLOAT,
    CONFIG_TYPE_STRING,
    CONFIG_TYPE_BOOL
} ConfigType;

typedef struct {
    char key[50];
    ConfigType type;
    union {
        int int_value;
        float float_value;
        char string_value[100];
        int bool_value;
    } value;
} ConfigItem;

typedef struct {
    ConfigItem *items;
    int count;
    int capacity;
} Config;

Config* create_config() {
    Config *config = malloc(sizeof(Config));
    if (config != NULL) {
        config-&gt;items = malloc(10 * sizeof(ConfigItem));
        if (config-&gt;items != NULL) {
            config-&gt;count = 0;
            config-&gt;capacity = 10;
        } else {
            free(config);
            config = NULL;
        }
    }
    return config;
}

void add_int_config(Config *config, const char *key, int value) {
    if (config-&gt;count &gt;= config-&gt;capacity) {
        // Resize array
        ConfigItem *new_items = realloc(config-&gt;items, 
                                       (config-&gt;capacity + 10) * sizeof(ConfigItem));
        if (new_items != NULL) {
            config-&gt;items = new_items;
            config-&gt;capacity += 10;
        } else {
            return;  // Allocation failed
        }
    }

    ConfigItem *item = &config-&gt;items[config-&gt;count];
    strncpy(item-&gt;key, key, sizeof(item-&gt;key) - 1);
    item-&gt;key[sizeof(item-&gt;key) - 1] = '\0';
    item-&gt;type = CONFIG_TYPE_INT;
    item-&gt;value.int_value = value;

    config-&gt;count++;
}

void print_config(const Config *config) {
    for (int i = 0; i &lt; config-&gt;count; i++) {
        const ConfigItem *item = &config-&gt;items[i];
        printf("Key: %s, ", item-&gt;key);

        switch (item-&gt;type) {
            case CONFIG_TYPE_INT:
                printf("Value: %d (int)\n", item-&gt;value.int_value);
                break;
            case CONFIG_TYPE_FLOAT:
                printf("Value: %.2f (float)\n", item-&gt;value.float_value);
                break;
            case CONFIG_TYPE_STRING:
                printf("Value: %s (string)\n", item-&gt;value.string_value);
                break;
            case CONFIG_TYPE_BOOL:
                printf("Value: %s (bool)\n", item-&gt;value.bool_value ? "true" : "false");
                break;
        }
    }
}

int main() {
    Config *config = create_config();
    if (config == NULL) {
        printf("Failed to create config\n");
        return 1;
    }

    add_int_config(config, "window_width", 800);
    add_int_config(config, "window_height", 600);

    print_config(config);

    // Clean up
    free(config-&gt;items);
    free(config);

    return 0;
}

Practical Examples

Network Packet Header
Using unions and enumerations for network protocol implementation:
#include &lt;stdio.h&gt;
#include &lt;stdint.h&gt;

typedef enum {
    PACKET_TYPE_DATA = 0x01,
    PACKET_TYPE_ACK = 0x02,
    PACKET_TYPE_NACK = 0x03,
    PACKET_TYPE_CONTROL = 0x04
} PacketType;

typedef enum {
    CONTROL_START = 0x01,
    CONTROL_STOP = 0x02,
    CONTROL_RESET = 0x03
} ControlType;

typedef struct {
    uint8_t version : 4;
    uint8_t type : 4;
    uint16_t length;
    uint32_t sequence;
    union {
        struct {
            uint8_t data[1024];
        } data_packet;

        struct {
            uint32_t ack_sequence;
        } ack_packet;

        struct {
            uint8_t control_type;
            uint8_t reserved[3];
        } control_packet;
    } payload;
} NetworkPacket;

void print_packet_info(const NetworkPacket *packet) {
    printf("Packet Version: %d\n", packet-&gt;version);
    printf("Packet Type: 0x%02X\n", packet-&gt;type);
    printf("Packet Length: %d\n", packet-&gt;length);
    printf("Sequence Number: %u\n", packet-&gt;sequence);

    switch (packet-&gt;type) {
        case PACKET_TYPE_DATA:
            printf("Data Packet\n");
            break;
        case PACKET_TYPE_ACK:
            printf("ACK for sequence: %u\n", packet-&gt;payload.ack_packet.ack_sequence);
            break;
        case PACKET_TYPE_CONTROL:
            printf("Control Type: 0x%02X\n", packet-&gt;payload.control_packet.control_type);
            break;
        default:
            printf("Unknown Packet Type\n");
    }
}

int main() {
    NetworkPacket packet = {
        .version = 1,
        .type = PACKET_TYPE_CONTROL,
        .length = sizeof(packet.payload.control_packet),
        .sequence = 1000,
        .payload.control_packet = {
            .control_type = CONTROL_RESET,
            .reserved = {0}
        }
    };

    print_packet_info(&packet);

    return 0;
}


Mathematical Expression Evaluator
Using unions and enumerations for a simple expression evaluator:
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;

typedef enum {
    TOKEN_NUMBER,
    TOKEN_OPERATOR,
    TOKEN_VARIABLE
} TokenType;

typedef enum {
    OP_ADD = '+',
    OP_SUBTRACT = '-',
    OP_MULTIPLY = '*',
    OP_DIVIDE = '/',
    OP_ASSIGN = '='
} Operator;

typedef struct {
    TokenType type;
    union {
        double number_value;
        Operator operator_value;
        char variable_name[20];
    } data;
} Token;

typedef struct {
    Token *tokens;
    int count;
    int capacity;
} Expression;

Expression* create_expression() {
    Expression *expr = malloc(sizeof(Expression));
    if (expr != NULL) {
        expr-&gt;tokens = malloc(10 * sizeof(Token));
        if (expr-&gt;tokens != NULL) {
            expr-&gt;count = 0;
            expr-&gt;capacity = 10;
        } else {
            free(expr);
            expr = NULL;
        }
    }
    return expr;
}

void add_number_token(Expression *expr, double value) {
    if (expr-&gt;count &gt;= expr-&gt;capacity) {
        Token *new_tokens = realloc(expr-&gt;tokens, 
                                   (expr-&gt;capacity + 10) * sizeof(Token));
        if (new_tokens != NULL) {
            expr-&gt;tokens = new_tokens;
            expr-&gt;capacity += 10;
        } else {
            return;
        }
    }

    Token *token = &expr-&gt;tokens[expr-&gt;count];
    token-&gt;type = TOKEN_NUMBER;
    token-&gt;data.number_value = value;
    expr-&gt;count++;
}

void add_operator_token(Expression *expr, Operator op) {
    if (expr-&gt;count &gt;= expr-&gt;capacity) {
        Token *new_tokens = realloc(expr-&gt;tokens, 
                                   (expr-&gt;capacity + 10) * sizeof(Token));
        if (new_tokens != NULL) {
            expr-&gt;tokens = new_tokens;
            expr-&gt;capacity += 10;
        } else {
            return;
        }
    }

    Token *token = &expr-&gt;tokens[expr-&gt;count];
    token-&gt;type = TOKEN_OPERATOR;
    token-&gt;data.operator_value = op;
    expr-&gt;count++;
}

void print_expression(const Expression *expr) {
    for (int i = 0; i &lt; expr-&gt;count; i++) {
        const Token *token = &expr-&gt;tokens[i];

        switch (token-&gt;type) {
            case TOKEN_NUMBER:
                printf("%.2f ", token-&gt;data.number_value);
                break;
            case TOKEN_OPERATOR:
                printf("%c ", token-&gt;data.operator_value);
                break;
            case TOKEN_VARIABLE:
                printf("%s ", token-&gt;data.variable_name);
                break;
        }
    }
    printf("\n");
}

int main() {
    Expression *expr = create_expression();
    if (expr == NULL) {
        printf("Failed to create expression\n");
        return 1;
    }

    // Create expression: 3.14 + 2.5 * x
    add_number_token(expr, 3.14);
    add_operator_token(expr, OP_ADD);
    add_number_token(expr, 2.5);
    add_operator_token(expr, OP_MULTIPLY);
    // For simplicity, we'll represent variable as a number
    add_number_token(expr, 0);  // Placeholder for variable x

    printf("Expression: ");
    print_expression(expr);

    // Clean up
    free(expr-&gt;tokens);
    free(expr);

    return 0;
}

Bit Fields

Basic Bit Field Declaration
Bit fields allow you to specify the exact number of bits used for structure members, enabling efficient memory usage for small values:
#include &lt;stdio.h&gt;

struct FilePermissions {
    unsigned int read : 1;     // 1 bit
    unsigned int write : 1;    // 1 bit
    unsigned int execute : 1;  // 1 bit
    unsigned int reserved : 5; // 5 bits
};

int main() {
    struct FilePermissions perm;

    // Set permissions
    perm.read = 1;
    perm.write = 1;
    perm.execute = 0;
    perm.reserved = 0;

    printf("Size of struct: %zu bytes\n", sizeof(perm));
    printf("Read: %d\n", perm.read);
    printf("Write: %d\n", perm.write);
    printf("Execute: %d\n", perm.execute);
    printf("Reserved: %d\n", perm.reserved);

    return 0;
}


Practical Bit Field Usage

1. Hardware Register Representation
Bit fields are commonly used to represent hardware registers with specific bit layouts:
#include &lt;stdio.h&gt;
#include &lt;stdint.h&gt;

struct GPIO_Register {
    uint32_t pin0  : 2;  // 2 bits for pin 0 configuration
    uint32_t pin1  : 2;  // 2 bits for pin 1 configuration
    uint32_t pin2  : 2;  // 2 bits for pin 2 configuration
    uint32_t pin3  : 2;  // 2 bits for pin 3 configuration
    uint32_t mode  : 4;  // 4 bits for mode selection
    uint32_t reserved : 20; // Remaining bits reserved
};

int main() {
    struct GPIO_Register gpio = {0};

    // Configure pins
    gpio.pin0 = 1;  // Output mode
    gpio.pin1 = 0;  // Input mode
    gpio.pin2 = 1;  // Output mode
    gpio.pin3 = 2;  // Alternate function
    gpio.mode = 5;  // Specific mode

    printf("GPIO Register Value: 0x%08X\n", *(uint32_t*)&gpio);
    printf("Pin 0 Configuration: %d\n", gpio.pin0);
    printf("Pin 1 Configuration: %d\n", gpio.pin1);
    printf("Mode: %d\n", gpio.mode);

    return 0;
}


2. Network Protocol Headers
Bit fields are useful for implementing network protocol headers with specific bit layouts:
#include &lt;stdio.h&gt;
#include &lt;stdint.h&gt;

struct IP_Header {
    uint32_t version : 4;        // 4 bits
    uint32_t ihl : 4;           // 4 bits
    uint32_t tos : 8;           // 8 bits
    uint32_t total_length : 16; // 16 bits
    uint32_t identification : 16; // 16 bits
    uint32_t flags : 3;         // 3 bits
    uint32_t fragment_offset : 13; // 13 bits
    uint32_t ttl : 8;           // 8 bits
    uint32_t protocol : 8;      // 8 bits
    uint32_t checksum : 16;     // 16 bits
    uint32_t source_ip : 32;    // 32 bits
    uint32_t dest_ip : 32;      // 32 bits
};

int main() {
    struct IP_Header ip_header = {0};

    // Set header values
    ip_header.version = 4;           // IPv4
    ip_header.ihl = 5;              // 5 * 4 = 20 bytes
    ip_header.tos = 0;
    ip_header.total_length = 100;
    ip_header.identification = 12345;
    ip_header.flags = 2;            // Don't fragment
    ip_header.fragment_offset = 0;
    ip_header.ttl = 64;
    ip_header.protocol = 6;         // TCP
    ip_header.source_ip = 0xC0A80101; // 192.168.1.1
    ip_header.dest_ip = 0xC0A80102;   // 192.168.1.2

    printf("IP Header Size: %zu bytes\n", sizeof(ip_header));
    printf("Version: %d\n", ip_header.version);
    printf("Header Length: %d words\n", ip_header.ihl);
    printf("Total Length: %d bytes\n", ip_header.total_length);
    printf("Protocol: %d\n", ip_header.protocol);

    return 0;
}



Bit Field Limitations and Considerations

1. Portability Issues
Bit field layout is implementation-defined and may vary between compilers:
#include &lt;stdio.h&gt;

struct BitFieldExample {
    unsigned int a : 3;
    unsigned int b : 4;
    unsigned int c : 5;
};

int main() {
    struct BitFieldExample bf = {1, 2, 3};

    printf("Size: %zu bytes\n", sizeof(bf));
    printf("Values: a=%d, b=%d, c=%d\n", bf.a, bf.b, bf.c);

    // Bit layout is implementation-defined
    unsigned int *ptr = (unsigned int*)&bf;
    printf("Raw value: 0x%08X\n", *ptr);

    return 0;
}


2. Alignment and Padding
Bit fields may introduce padding for alignment:
#include &lt;stdio.h&gt;

struct PackedBits {
    unsigned int a : 1;
    unsigned int b : 1;
    unsigned int c : 1;
};

struct AlignedStruct {
    char x;
    struct PackedBits bits;
    char y;
};

int main() {
    printf("Size of PackedBits: %zu bytes\n", sizeof(struct PackedBits));
    printf("Size of AlignedStruct: %zu bytes\n", sizeof(struct AlignedStruct));

    return 0;
}

Structure Packing and Alignment

Default Structure Alignment
Compilers add padding to structures to ensure proper alignment:
#include &lt;stdio.h&gt;

struct Unpacked {
    char a;      // 1 byte
    int b;       // 4 bytes (may have 3 bytes padding before)
    char c;      // 1 byte (may have 3 bytes padding after)
};

#pragma pack(1)
struct Packed {
    char a;      // 1 byte
    int b;       // 4 bytes (no padding)
    char c;      // 1 byte (no padding)
};
#pragma pack()

int main() {
    printf("Size of Unpacked: %zu bytes\n", sizeof(struct Unpacked));
    printf("Size of Packed: %zu bytes\n", sizeof(struct Packed));

    // Show member offsets
    struct Unpacked u = {0};
    printf("Unpacked offsets - a: %td, b: %td, c: %td\n",
           (char*)&u.a - (char*)&u,
           (char*)&u.b - (char*)&u,
           (char*)&u.c - (char*)&u);

    struct Packed p = {0};
    printf("Packed offsets - a: %td, b: %td, c: %td\n",
           (char*)&p.a - (char*)&p,
           (char*)&p.b - (char*)&p,
           (char*)&p.c - (char*)&p);

    return 0;
}


Controlling Alignment with Pragma Pack
The #pragma pack directive controls structure packing:
#include &lt;stdio.h&gt;

// Default alignment
struct Default {
    char a;
    int b;
    char c;
};

// 1-byte alignment (no padding)
#pragma pack(1)
struct Packed1 {
    char a;
    int b;
    char c;
};
#pragma pack()

// 2-byte alignment
#pragma pack(2)
struct Packed2 {
    char a;
    int b;
    char c;
};
#pragma pack()

// 4-byte alignment
#pragma pack(4)
struct Packed4 {
    char a;
    int b;
    char c;
};
#pragma pack()

int main() {
    printf("Default alignment: %zu bytes\n", sizeof(struct Default));
    printf("1-byte packing: %zu bytes\n", sizeof(struct Packed1));
    printf("2-byte packing: %zu bytes\n", sizeof(struct Packed2));
    printf("4-byte packing: %zu bytes\n", sizeof(struct Packed4));

    return 0;
}


Using _Alignas (C11)
C11 introduces _Alignas for explicit alignment control:
#include &lt;stdio.h&gt;
#include &lt;stdalign.h&gt;

struct AlignedStruct {
    _Alignas(16) char data[16];  // Align to 16-byte boundary
    int value;
};

int main() {
    struct AlignedStruct s = {0};

    printf("Size: %zu bytes\n", sizeof(s));
    printf("Address of data: %p\n", (void*)s.data);
