Flexible Array Members (C99)

Basic Flexible Array Member
Flexible array members allow structures to have variable-sized arrays at the end:
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;

struct DynamicArray {
    size_t count;
    int data[];  // Flexible array member (must be last)
};

struct DynamicArray* create_array(size_t count) {
    // Allocate memory for structure + array
    struct DynamicArray *arr = malloc(sizeof(struct DynamicArray) + 
                                     count * sizeof(int));
    if (arr != NULL) {
        arr-&gt;count = count;
        // arr-&gt;data can now be used as array of 'count' integers
    }
    return arr;
}

int main() {
    struct DynamicArray *arr = create_array(5);
    if (arr != NULL) {
        // Initialize array elements
        for (size_t i = 0; i &lt; arr-&gt;count; i++) {
            arr-&gt;data[i] = (int)(i * i);
        }

        // Print array elements
        printf("Array elements: ");
        for (size_t i = 0; i &lt; arr-&gt;count; i++) {
            printf("%d ", arr-&gt;data[i]);
        }
        printf("\n");

        printf("Size of structure: %zu bytes\n", sizeof(struct DynamicArray));
        printf("Total allocated size: %zu bytes\n", 
               sizeof(struct DynamicArray) + arr-&gt;count * sizeof(int));

        // Free memory
        free(arr);
    }

    return 0;
}


Flexible Array in String Structure
Using flexible array members for dynamic strings:
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;

struct DynamicString {
    size_t length;
    char data[];  // Flexible array member
};

struct DynamicString* create_string(const char *source) {
    size_t len = strlen(source);
    // Allocate memory for structure + string + null terminator
    struct DynamicString *str = malloc(sizeof(struct DynamicString) + 
                                      len + 1);
    if (str != NULL) {
        str-&gt;length = len;
        strcpy(str-&gt;data, source);
    }
    return str;
}

struct DynamicString* append_strings(const struct DynamicString *s1, 
                                   const char *s2) {
    size_t len2 = strlen(s2);
    size_t new_len = s1-&gt;length + len2;

    struct DynamicString *result = malloc(sizeof(struct DynamicString) + 
                                         new_len + 1);
    if (result != NULL) {
        result-&gt;length = new_len;
        strcpy(result-&gt;data, s1-&gt;data);
        strcat(result-&gt;data, s2);
    }
    return result;
}

int main() {
    struct DynamicString *str1 = create_string("Hello, ");
    if (str1 != NULL) {
        printf("String 1: %s (length: %zu)\n", str1-&gt;data, str1-&gt;length);

        struct DynamicString *str2 = append_strings(str1, "World!");
        if (str2 != NULL) {
            printf("String 2: %s (length: %zu)\n", str2-&gt;data, str2-&gt;length);
            free(str2);
        }

        free(str1);
    }

    return 0;
}

Self-Referential Structures

Linked List Implementation
Self-referential structures are fundamental for implementing linked data structures:
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

struct Node {
    int data;
    struct Node *next;
};

// Function to create a new node
struct Node* create_node(int data) {
    struct Node *node = malloc(sizeof(struct Node));
    if (node != NULL) {
        node-&gt;data = data;
        node-&gt;next = NULL;
    }
    return node;
}

// Function to insert at beginning
struct Node* insert_at_beginning(struct Node *head, int data) {
    struct Node *new_node = create_node(data);
    if (new_node != NULL) {
        new_node-&gt;next = head;
        head = new_node;
    }
    return head;
}

// Function to print the list
void print_list(struct Node *head) {
    struct Node *current = head;
    while (current != NULL) {
        printf("%d -&gt; ", current-&gt;data);
        current = current-&gt;next;
    }
    printf("NULL\n");
}

// Function to free the list
void free_list(struct Node *head) {
    struct Node *current = head;
    while (current != NULL) {
        struct Node *next = current-&gt;next;
        free(current);
        current = next;
    }
}

int main() {
    struct Node *head = NULL;

    // Build the list: 3 -&gt; 2 -&gt; 1 -&gt; NULL
    head = insert_at_beginning(head, 1);
    head = insert_at_beginning(head, 2);
    head = insert_at_beginning(head, 3);

    printf("Linked List: ");
    print_list(head);

    // Free the list
    free_list(head);

    return 0;
}


Binary Tree Implementation
Self-referential structures for binary trees:
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

struct TreeNode {
    int data;
    struct TreeNode *left;
    struct TreeNode *right;
};

// Function to create a new node
struct TreeNode* create_node(int data) {
    struct TreeNode *node = malloc(sizeof(struct TreeNode));
    if (node != NULL) {
        node-&gt;data = data;
        node-&gt;left = NULL;
        node-&gt;right = NULL;
    }
    return node;
}

// Function to insert a node in BST
struct TreeNode* insert(struct TreeNode *root, int data) {
    if (root == NULL) {
        return create_node(data);
    }

    if (data &lt; root-&gt;data) {
        root-&gt;left = insert(root-&gt;left, data);
    } else if (data &gt; root-&gt;data) {
        root-&gt;right = insert(root-&gt;right, data);
    }

    return root;
}

// In-order traversal
void inorder_traversal(struct TreeNode *root) {
    if (root != NULL) {
        inorder_traversal(root-&gt;left);
        printf("%d ", root-&gt;data);
        inorder_traversal(root-&gt;right);
    }
}

// Free the tree
void free_tree(struct TreeNode *root) {
    if (root != NULL) {
        free_tree(root-&gt;left);
        free_tree(root-&gt;right);
        free(root);
    }
}

int main() {
    struct TreeNode *root = NULL;

    // Insert nodes
    root = insert(root, 50);
    insert(root, 30);
    insert(root, 70);
    insert(root, 20);
    insert(root, 40);
    insert(root, 60);
    insert(root, 80);

    printf("In-order traversal: ");
    inorder_traversal(root);
    printf("\n");

    // Free the tree
    free_tree(root);

    return 0;
}

Advanced Structure Techniques

Structure with Function Pointers (C Object-Oriented Approach)
Using function pointers to implement object-oriented concepts in C:
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;

// Forward declaration
struct Shape;

// Function pointer types
typedef double (*area_func)(const struct Shape *self);
typedef void (*print_func)(const struct Shape *self);

// Base structure
struct Shape {
    area_func area;
    print_func print;
    char name[20];
};

// Rectangle structure
struct Rectangle {
    struct Shape base;
    double width;
    double height;
};

// Circle structure
struct Circle {
    struct Shape base;
    double radius;
};

// Area calculation functions
double rectangle_area(const struct Shape *self) {
    const struct Rectangle *rect = (const struct Rectangle *)self;
    return rect-&gt;width * rect-&gt;height;
}

double circle_area(const struct Shape *self) {
    const struct Circle *circle = (const struct Circle *)self;
    return 3.14159 * circle-&gt;radius * circle-&gt;radius;
}

// Print functions
void rectangle_print(const struct Shape *self) {
    const struct Rectangle *rect = (const struct Rectangle *)self;
    printf("Rectangle: %s, Width: %.2f, Height: %.2f\n",
           self-&gt;name, rect-&gt;width, rect-&gt;height);
}

void circle_print(const struct Shape *self) {
    const struct Circle *circle = (const struct Circle *)self;
    printf("Circle: %s, Radius: %.2f\n",
           self-&gt;name, circle-&gt;radius);
}

// Constructor functions
struct Rectangle* create_rectangle(const char *name, double width, double height) {
    struct Rectangle *rect = malloc(sizeof(struct Rectangle));
    if (rect != NULL) {
        strncpy(rect-&gt;base.name, name, sizeof(rect-&gt;base.name) - 1);
        rect-&gt;base.name[sizeof(rect-&gt;base.name) - 1] = '\0';
        rect-&gt;base.area = rectangle_area;
        rect-&gt;base.print = rectangle_print;
        rect-&gt;width = width;
        rect-&gt;height = height;
    }
    return rect;
}

struct Circle* create_circle(const char *name, double radius) {
    struct Circle *circle = malloc(sizeof(struct Circle));
    if (circle != NULL) {
        strncpy(circle-&gt;base.name, name, sizeof(circle-&gt;base.name) - 1);
        circle-&gt;base.name[sizeof(circle-&gt;base.name) - 1] = '\0';
        circle-&gt;base.area = circle_area;
        circle-&gt;base.print = circle_print;
        circle-&gt;radius = radius;
    }
    return circle;
}

int main() {
    struct Rectangle *rect = create_rectangle("MyRectangle", 5.0, 3.0);
    struct Circle *circle = create_circle("MyCircle", 4.0);

    if (rect != NULL && circle != NULL) {
        // Polymorphic behavior
        struct Shape *shapes[] = {
            (struct Shape*)rect,
            (struct Shape*)circle
        };

        for (int i = 0; i &lt; 2; i++) {
            shapes[i]-&gt;print(shapes[i]);
            printf("Area: %.2f\n", shapes[i]-&gt;area(shapes[i]));
        }

        free(rect);
        free(circle);
    }

    return 0;
}


Structure with Nested Anonymous Structures (C11)
Using nested anonymous structures for cleaner APIs:
#include &lt;stdio.h&gt;

struct Point3D {
    union {
        struct {
            double x, y, z;
        };
        double coords[3];
    };
};

struct Color {
    union {
        struct {
            unsigned char r, g, b, a;
        };
        unsigned char components[4];
    };
};

int main() {
    struct Point3D point = {1.0, 2.0, 3.0};
    struct Color color = {255, 128, 64, 255};

    // Access using named members
    printf("Point: (%.1f, %.1f, %.1f)\n", point.x, point.y, point.z);

    // Access using array
    printf("Coordinates: ");
    for (int i = 0; i &lt; 3; i++) {
        printf("%.1f ", point.coords[i]);
    }
    printf("\n");

    // Access color components
    printf("Color: RGBA(%d, %d, %d, %d)\n", 
           color.r, color.g, color.b, color.a);

    // Modify using array access
    for (int i = 0; i &lt; 4; i++) {
        color.components[i] = 128;
    }

    printf("Modified color: RGBA(%d, %d, %d, %d)\n",
           color.r, color.g, color.b, color.a);

    return 0;
}

Practical Examples

Configuration Manager with Advanced Structures
Combining advanced structure concepts for a configuration manager:
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;

// Configuration entry types
typedef enum {
    CONFIG_INT,
    CONFIG_FLOAT,
    CONFIG_STRING,
    CONFIG_BOOL
} ConfigType;

// Configuration entry with bit fields
struct ConfigEntry {
    unsigned int type : 3;        // 3 bits for type
    unsigned int is_default : 1;  // 1 bit for default flag
    unsigned int is_locked : 1;   // 1 bit for lock flag
    unsigned int reserved : 27;   // 27 bits reserved

    char key[32];
    union {
        int int_value;
        float float_value;
        char *string_value;
        int bool_value;
    } value;
};

// Configuration manager
struct ConfigManager {
    struct ConfigEntry *entries;
    size_t count;
    size_t capacity;
};

struct ConfigManager* create_config_manager() {
    struct ConfigManager *cm = malloc(sizeof(struct ConfigManager));
    if (cm != NULL) {
        cm-&gt;entries = malloc(10 * sizeof(struct ConfigEntry));
        if (cm-&gt;entries != NULL) {
            cm-&gt;count = 0;
            cm-&gt;capacity = 10;
        } else {
            free(cm);
            cm = NULL;
        }
    }
    return cm;
}

int add_int_config(struct ConfigManager *cm, const char *key, int value) {
    if (cm-&gt;count &gt;= cm-&gt;capacity) {
        struct ConfigEntry *new_entries = realloc(cm-&gt;entries,
            (cm-&gt;capacity + 10) * sizeof(struct ConfigEntry));
        if (new_entries == NULL) return -1;
        cm-&gt;entries = new_entries;
        cm-&gt;capacity += 10;
    }

    struct ConfigEntry *entry = &cm-&gt;entries[cm-&gt;count];
    entry-&gt;type = CONFIG_INT;
    entry-&gt;is_default = 0;
    entry-&gt;is_locked = 0;
    entry-&gt;reserved = 0;
    strncpy(entry-&gt;key, key, sizeof(entry-&gt;key) - 1);
    entry-&gt;key[sizeof(entry-&gt;key) - 1] = '\0';
    entry-&gt;value.int_value = value;

    cm-&gt;count++;
    return 0;
}

void print_config(const struct ConfigManager *cm) {
    for (size_t i = 0; i &lt; cm-&gt;count; i++) {
        const struct ConfigEntry *entry = &cm-&gt;entries[i];
        printf("Key: %s, Type: %d, Default: %d, Locked: %d\n",
               entry-&gt;key, entry-&gt;type, entry-&gt;is_default, entry-&gt;is_locked);

        switch (entry-&gt;type) {
            case CONFIG_INT:
                printf("  Value: %d (int)\n", entry-&gt;value.int_value);
                break;
            // Add other cases as needed
        }
    }
}

void free_config_manager(struct ConfigManager *cm) {
    if (cm != NULL) {
        free(cm-&gt;entries);
        free(cm);
    }
}

int main() {
    struct ConfigManager *cm = create_config_manager();
    if (cm == NULL) {
        printf("Failed to create config manager\n");
        return 1;
    }

    add_int_config(cm, "window_width", 800);
    add_int_config(cm, "window_height", 600);
    add_int_config(cm, "max_fps", 60);

    print_config(cm);

    free_config_manager(cm);
    return 0;
}


Memory Pool with Flexible Array Members
Implementing a memory pool using flexible array members:
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;

struct MemoryBlock {
    size_t size;
    int is_free;
    char data[];  // Flexible array member
};

struct MemoryPool {
    size_t block_size;
    size_t total_blocks;
    struct MemoryBlock blocks[];  // Flexible array member
};

struct MemoryPool* create_memory_pool(size_t block_size, size_t num_blocks) {
    size_t pool_size = sizeof(struct MemoryPool) + 
                      num_blocks * (sizeof(struct MemoryBlock) + block_size);

    struct MemoryPool *pool = malloc(pool_size);
    if (pool != NULL) {
        pool-&gt;block_size = block_size;
        pool-&gt;total_blocks = num_blocks;

        // Initialize blocks
        char *block_data = (char*)(pool-&gt;blocks);
        for (size_t i = 0; i &lt; num_blocks; i++) {
            struct MemoryBlock *block = (struct MemoryBlock*)block_data;
            block-&gt;size = block_size;
            block-&gt;is_free = 1;
            block_data += sizeof(struct MemoryBlock) + block_size;
        }
    }
    return pool;
}

void* pool_alloc(struct MemoryPool *pool, size_t size) {
    if (size &gt; pool-&gt;block_size) return NULL;

    char *block_data = (char*)(pool-&gt;blocks);
    for (size_t i = 0; i &lt; pool-&gt;total_blocks; i++) {
        struct MemoryBlock *block = (struct MemoryBlock*)block_data;
        if (block-&gt;is_free && block-&gt;size &gt;= size) {
            block-&gt;is_free = 0;
            return block-&gt;data;
        }
        block_data += sizeof(struct MemoryBlock) + pool-&gt;block_size;
    }
    return NULL;
}

void pool_free(struct MemoryPool *pool, void *ptr) {
    if (ptr == NULL) return;

    char *pool_start = (char*)pool;
    char *ptr_char = (char*)ptr;

    if (ptr_char &gt;= pool_start && 
        ptr_char &lt; pool_start + sizeof(struct MemoryPool) + 
                   pool-&gt;total_blocks * (sizeof(struct MemoryBlock) + pool-&gt;block_size)) {

        char *block_data = (char*)(pool-&gt;blocks);
        for (size_t i = 0; i &lt; pool-&gt;total_blocks; i++) {
            struct MemoryBlock *block = (struct MemoryBlock*)block_data;
            if (ptr_char == block-&gt;data) {
                block-&gt;is_free = 1;
                return;
            }
            block_data += sizeof(struct MemoryBlock) + pool-&gt;block_size;
        }
    }
}

void free_memory_pool(struct MemoryPool *pool) {
    free(pool);
}

int main() {
    struct MemoryPool *pool = create_memory_pool(64, 10);
    if (pool == NULL) {
        printf("Failed to create memory pool\n");
        return 1;
    }

    // Allocate memory from pool
    int *numbers = (int*)pool_alloc(pool, 10 * sizeof(int));
    if (numbers != NULL) {
        for (int i = 0; i &lt; 10; i++) {
            numbers[i] = i * i;
        }

        printf("Numbers: ");
        for (int i = 0; i &lt; 10; i++) {
            printf("%d ", numbers[i]);
        }
        printf("\n");

        // Free memory
        pool_free(pool, numbers);
    }

    free_memory_pool(pool);
    return 0;
}

Information Hiding Principles

Separation of Interface and Implementation
Information hiding is achieved by separating the public interface (what users can access) from the private implementation (internal details):
// stack.h - Public interface
#ifndef STACK_H
#define STACK_H

#include &lt;stddef.h&gt;

// Opaque pointer - hides implementation details
typedef struct Stack Stack;

// Public functions
Stack* stack_create(size_t capacity);
void stack_destroy(Stack *stack);
int stack_push(Stack *stack, int value);
int stack_pop(Stack *stack);
int stack_peek(const Stack *stack);
int stack_is_empty(const Stack *stack);
int stack_is_full(const Stack *stack);
size_t stack_size(const Stack *stack);

#endif // STACK_H
// stack.c - Private implementation
#include "stack.h"
#include &lt;stdlib.h&gt;
#include &lt;stdbool.h&gt;

// Actual structure definition (hidden from users)
struct Stack {
    int *data;
    size_t capacity;
    size_t top;
};

Stack* stack_create(size_t capacity) {
    Stack *stack = malloc(sizeof(Stack));
    if (stack != NULL) {
        stack-&gt;data = malloc(capacity * sizeof(int));
        if (stack-&gt;data != NULL) {
            stack-&gt;capacity = capacity;
            stack-&gt;top = 0;
        } else {
            free(stack);
            stack = NULL;
        }
    }
    return stack;
}

void stack_destroy(Stack *stack) {
    if (stack != NULL) {
        free(stack-&gt;data);
        free(stack);
    }
}

int stack_push(Stack *stack, int value) {
    if (stack == NULL || stack-&gt;top &gt;= stack-&gt;capacity) {
        return -1; // Error
    }
    stack-&gt;data[stack-&gt;top] = value;
    stack-&gt;top++;
    return 0; // Success
}

int stack_pop(Stack *stack) {
    if (stack == NULL || stack-&gt;top == 0) {
        return -1; // Error
    }
    stack-&gt;top--;
    return stack-&gt;data[stack-&gt;top];
}

int stack_peek(const Stack *stack) {
    if (stack == NULL || stack-&gt;top == 0) {
        return -1; // Error
    }
    return stack-&gt;data[stack-&gt;top - 1];
}

int stack_is_empty(const Stack *stack) {
    return (stack == NULL || stack-&gt;top == 0);
}

int stack_is_full(const Stack *stack) {
    return (stack != NULL && stack-&gt;top &gt;= stack-&gt;capacity);
}

size_t stack_size(const Stack *stack) {
    return (stack != NULL) ? stack-&gt;top : 0;
}
// main.c - Using the ADT
#include &lt;stdio.h&gt;
#include "stack.h"

int main() {
    Stack *stack = stack_create(10);
    if (stack == NULL) {
        printf("Failed to create stack\n");
        return 1;
    }

    // Use the stack
    stack_push(stack, 10);
    stack_push(stack, 20);
    stack_push(stack, 30);

    printf("Stack size: %zu\n", stack_size(stack));
    printf("Top element: %d\n", stack_peek(stack));

    while (!stack_is_empty(stack)) {
        printf("Popped: %d\n", stack_pop(stack));
    }

    stack_destroy(stack);
    return 0;
}

Opaque Pointers

Creating Opaque Pointers
Opaque pointers hide the implementation details of a data structure by only declaring the structure type in the header file:
// vector.h - Opaque pointer example
#ifndef VECTOR_H
#define VECTOR_H

#include &lt;stddef.h&gt;

// Forward declaration - no structure definition
typedef struct Vector Vector;

// Public interface
Vector* vector_create(size_t initial_capacity);
void vector_destroy(Vector *vector);
int vector_push_back(Vector *vector, int value);
int vector_pop_back(Vector *vector);
int vector_get(const Vector *vector, size_t index);
int vector_set(Vector *vector, size_t index, int value);
size_t vector_size(const Vector *vector);
size_t vector_capacity(const Vector *vector);

#endif // VECTOR_H
// vector.c - Implementation with opaque pointer
#include "vector.h"
#include &lt;stdlib.h&gt;

// Actual structure definition (private)
struct Vector {
    int *data;
    size_t size;
    size_t capacity;
};

Vector* vector_create(size_t initial_capacity) {
    Vector *vector = malloc(sizeof(Vector));
    if (vector != NULL) {
        vector-&gt;data = malloc(initial_capacity * sizeof(int));
        if (vector-&gt;data != NULL) {
            vector-&gt;size = 0;
            vector-&gt;capacity = initial_capacity;
        } else {
            free(vector);
            vector = NULL;
        }
    }
    return vector;
}

void vector_destroy(Vector *vector) {
    if (vector != NULL) {
        free(vector-&gt;data);
        free(vector);
    }
}

int vector_push_back(Vector *vector, int value) {
    if (vector == NULL) return -1;

    // Resize if needed
    if (vector-&gt;size &gt;= vector-&gt;capacity) {
        size_t new_capacity = vector-&gt;capacity * 2;
        int *new_data = realloc(vector-&gt;data, new_capacity * sizeof(int));
        if (new_data == NULL) return -1;

        vector-&gt;data = new_data;
        vector-&gt;capacity = new_capacity;
    }

    vector-&gt;data[vector-&gt;size] = value;
    vector-&gt;size++;
    return 0;
}

int vector_pop_back(Vector *vector) {
    if (vector == NULL || vector-&gt;size == 0) return -1;
    vector-&gt;size--;
    return vector-&gt;data[vector-&gt;size];
}

int vector_get(const Vector *vector, size_t index) {
    if (vector == NULL || index &gt;= vector-&gt;size) return -1;
    return vector-&gt;data[index];
}

int vector_set(Vector *vector, size_t index, int value) {
    if (vector == NULL || index &gt;= vector-&gt;size) return -1;
    vector-&gt;data[index] = value;
    return 0;
}

size_t vector_size(const Vector *vector) {
    return (vector != NULL) ? vector-&gt;size : 0;
}

size_t vector_capacity(const Vector *vector) {
    return (vector != NULL) ? vector-&gt;capacity : 0;
}

Constructor and Destructor Patterns

Resource Acquisition Is Initialization (RAII) in C
Implementing constructor and destructor patterns for proper resource management:
// file_manager.h
#ifndef FILE_MANAGER_H
#define FILE_MANAGER_H

#include &lt;stdio.h&gt;

typedef struct FileManager FileManager;

FileManager* file_manager_create(const char *filename, const char *mode);
void file_manager_destroy(FileManager *fm);
int file_manager_write(FileManager *fm, const char *data);
int file_manager_read(FileManager *fm, char *buffer, size_t size);
long file_manager_get_size(FileManager *fm);

#endif // FILE_MANAGER_H
// file_manager.c
#include "file_manager.h"
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;

struct FileManager {
    FILE *file;
    char *filename;
    char *mode;
};

FileManager* file_manager_create(const char *filename, const char *mode) {
    FileManager *fm = malloc(sizeof(FileManager));
    if (fm == NULL) return NULL;

    fm-&gt;filename = malloc(strlen(filename) + 1);
    if (fm-&gt;filename == NULL) {
        free(fm);
        return NULL;
    }

    fm-&gt;mode = malloc(strlen(mode) + 1);
    if (fm-&gt;mode == NULL) {
        free(fm-&gt;filename);
        free(fm);
        return NULL;
    }

    strcpy(fm-&gt;filename, filename);
    strcpy(fm-&gt;mode, mode);

    fm-&gt;file = fopen(filename, mode);
    if (fm-&gt;file == NULL) {
        free(fm-&gt;mode);
        free(fm-&gt;filename);
        free(fm);
        return NULL;
    }

    return fm;
}

void file_manager_destroy(FileManager *fm) {
    if (fm != NULL) {
        if (fm-&gt;file != NULL) {
            fclose(fm-&gt;file);
        }
        free(fm-&gt;mode);
        free(fm-&gt;filename);
        free(fm);
    }
}

int file_manager_write(FileManager *fm, const char *data) {
    if (fm == NULL || fm-&gt;file == NULL || data == NULL) return -1;
    return fputs(data, fm-&gt;file) &gt;= 0 ? 0 : -1;
}

int file_manager_read(FileManager *fm, char *buffer, size_t size) {
    if (fm == NULL || fm-&gt;file == NULL || buffer == NULL) return -1;
    return fgets(buffer, (int)size, fm-&gt;file) != NULL ? 0 : -1;
}

long file_manager_get_size(FileManager *fm) {
    if (fm == NULL || fm-&gt;file == NULL) return -1;

    long current_pos = ftell(fm-&gt;file);
    fseek(fm-&gt;file, 0, SEEK_END);
    long size = ftell(fm-&gt;file);
    fseek(fm-&gt;file, current_pos, SEEK_SET);

    return size;
}

Generic Abstract Data Types

Using Void Pointers for Generic ADTs
Creating generic ADTs that can work with any data type:
// generic_list.h
#ifndef GENERIC_LIST_H
#define GENERIC_LIST_H

#include &lt;stddef.h&gt;

typedef struct GenericList GenericList;

// Function pointer types for generic operations
typedef void (*destructor_func)(void *data);
typedef int (*compare_func)(const void *a, const void *b);
typedef void (*print_func)(const void *data);

GenericList* generic_list_create(destructor_func destructor);
void generic_list_destroy(GenericList *list);
int generic_list_append(GenericList *list, void *data);
int generic_list_prepend(GenericList *list, void *data);
void* generic_list_get(const GenericList *list, size_t index);
int generic_list_remove(GenericList *list, size_t index);
size_t generic_list_size(const GenericList *list);
void generic_list_print(const GenericList *list, print_func printer);

#endif // GENERIC_LIST_H
// generic_list.c
#include "generic_list.h"
#include &lt;stdlib.h&gt;

struct Node {
    void *data;
    struct Node *next;
};

struct GenericList {
    struct Node *head;
    size_t size;
    destructor_func destructor;
};

GenericList* generic_list_create(destructor_func destructor) {
    GenericList *list = malloc(sizeof(GenericList));
    if (list != NULL) {
        list-&gt;head = NULL;
        list-&gt;size = 0;
        list-&gt;destructor = destructor;
    }
    return list;
}

void generic_list_destroy(GenericList *list) {
    if (list != NULL) {
        struct Node *current = list-&gt;head;
        while (current != NULL) {
            struct Node *next = current-&gt;next;
            if (list-&gt;destructor != NULL) {
                list-&gt;destructor(current-&gt;data);
            }
            free(current);
            current = next;
        }
        free(list);
    }
}

int generic_list_append(GenericList *list, void *data) {
    if (list == NULL) return -1;

    struct Node *new_node = malloc(sizeof(struct Node));
    if (new_node == NULL) return -1;

    new_node-&gt;data = data;
    new_node-&gt;next = NULL;

    if (list-&gt;head == NULL) {
        list-&gt;head = new_node;
    } else {
        struct Node *current = list-&gt;head;
        while (current-&gt;next != NULL) {
            current = current-&gt;next;
        }
        current-&gt;next = new_node;
    }

    list-&gt;size++;
    return 0;
}

void* generic_list_get(const GenericList *list, size_t index) {
    if (list == NULL || index &gt;= list-&gt;size) return NULL;

    struct Node *current = list-&gt;head;
    for (size_t i = 0; i &lt; index && current != NULL; i++) {
        current = current-&gt;next;
    }

    return (current != NULL) ? current-&gt;data : NULL;
}

int generic_list_remove(GenericList *list, size_t index) {
    if (list == NULL || index &gt;= list-&gt;size) return -1;

    struct Node *to_remove;
    if (index == 0) {
        to_remove = list-&gt;head;
        list-&gt;head = to_remove-&gt;next;
    } else {
        struct Node *current = list-&gt;head;
        for (size_t i = 0; i &lt; index - 1 && current != NULL; i++) {
            current = current-&gt;next;
        }
        if (current == NULL || current-&gt;next == NULL) return -1;

        to_remove = current-&gt;next;
        current-&gt;next = to_remove-&gt;next;
    }

    if (list-&gt;destructor != NULL) {
        list-&gt;destructor(to_remove-&gt;data);
    }
    free(to_remove);
    list-&gt;size--;

    return 0;
}

size_t generic_list_size(const GenericList *list) {
    return (list != NULL) ? list-&gt;size : 0;
}

void generic_list_print(const GenericList *list, print_func printer) {
    if (list == NULL || printer == NULL) return;

    struct Node *current = list-&gt;head;
    while (current != NULL) {
        printer(current-&gt;data);
        current = current-&gt;next;
    }
}
// Example usage with different data types
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;
#include "generic_list.h"

// Integer destructor
void int_destructor(void *data) {
    free(data);
}

// Integer printer
void int_printer(const void *data) {
    printf("%d ", *(int*)data);
}

// String destructor
void string_destructor(void *data) {
    free(data);
}

// String printer
void string_printer(const void *data) {
    printf("%s ", (char*)data);
}

int main() {
    // Integer list
    GenericList *int_list = generic_list_create(int_destructor);
    if (int_list != NULL) {
        for (int i = 1; i &lt;= 5; i++) {
            int *value = malloc(sizeof(int));
            *value = i * 10;
            generic_list_append(int_list, value);
        }

        printf("Integer list: ");
        generic_list_print(int_list, int_printer);
        printf("\n");

        generic_list_destroy(int_list);
    }

    // String list
    GenericList *string_list = generic_list_create(string_destructor);
    if (string_list != NULL) {
        char *str1 = malloc(20);
        char *str2 = malloc(20);
        char *str3 = malloc(20);

        strcpy(str1, "Hello");
        strcpy(str2, "World");
        strcpy(str3, "C");

        generic_list_append(string_list, str1);
        generic_list_append(string_list, str2);
        generic_list_append(string_list, str3);

        printf("String list: ");
        generic_list_print(string_list, string_printer);
        printf("\n");

        generic_list_destroy(string_list);
    }

    return 0;
}

Interface Design in C

Designing Clean APIs
Creating well-designed interfaces that are easy to use and maintain:
// hash_table.h - Well-designed hash table interface
#ifndef HASH_TABLE_H
#define HASH_TABLE_H

#include &lt;stddef.h&gt;
#include &lt;stdbool.h&gt;

typedef struct HashTable HashTable;

// Function pointer types for custom operations
typedef size_t (*hash_func)(const void *key);
typedef int (*compare_func)(const void *key1, const void *key2);
typedef void (*destructor_func)(void *data);

// Error codes
typedef enum {
    HASH_SUCCESS = 0,
    HASH_ERROR_NULL_POINTER = -1,
    HASH_ERROR_MEMORY = -2,
    HASH_ERROR_KEY_NOT_FOUND = -3,
    HASH_ERROR_DUPLICATE_KEY = -4
} HashError;

// Public functions
HashTable* hash_table_create(size_t initial_capacity,
                           hash_func hash_function,
                           compare_func compare_function,
                           destructor_func key_destructor,
                           destructor_func value_destructor);

void hash_table_destroy(HashTable *table);
HashError hash_table_insert(HashTable *table, void *key, void *value);
HashError hash_table_remove(HashTable *table, const void *key);
void* hash_table_lookup(const HashTable *table, const void *key);
bool hash_table_contains(const HashTable *table, const void *key);
size_t hash_table_size(const HashTable *table);
void hash_table_clear(HashTable *table);

// Utility functions
size_t hash_string(const void *key);  // Default string hash function
int compare_strings(const void *key1, const void *key2);  // Default string compare

#endif // HASH_TABLE_H
// hash_table.c - Implementation
#include "hash_table.h"
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;

// Hash table entry
struct Entry {
    void *key;
    void *value;
    struct Entry *next;
};

// Hash table structure
struct HashTable {
    struct Entry **buckets;
    size_t bucket_count;
    size_t size;
    hash_func hash_function;
    compare_func compare_function;
    destructor_func key_destructor;
    destructor_func value_destructor;
};

// Default hash function for strings
size_t hash_string(const void *key) {
    const char *str = (const char*)key;
    size_t hash = 5381;
    int c;

    while ((c = *str++)) {
        hash = ((hash &lt;&lt; 5) + hash) + c;  // hash * 33 + c
    }

    return hash;
}

// Default compare function for strings
int compare_strings(const void *key1, const void *key2) {
    return strcmp((const char*)key1, (const char*)key2);
}

HashTable* hash_table_create(size_t initial_capacity,
                           hash_func hash_function,
                           compare_func compare_function,
                           destructor_func key_destructor,
                           destructor_func value_destructor) {
    HashTable *table = malloc(sizeof(HashTable));
    if (table == NULL) return NULL;

    table-&gt;buckets = calloc(initial_capacity, sizeof(struct Entry*));
    if (table-&gt;buckets == NULL) {
        free(table);
        return NULL;
    }

    table-&gt;bucket_count = initial_capacity;
    table-&gt;size = 0;
    table-&gt;hash_function = hash_function ? hash_function : hash_string;
    table-&gt;compare_function = compare_function ? compare_function : compare_strings;
    table-&gt;key_destructor = key_destructor;
    table-&gt;value_destructor = value_destructor;

    return table;
}

void hash_table_destroy(HashTable *table) {
    if (table != NULL) {
        hash_table_clear(table);
        free(table-&gt;buckets);
        free(table);
    }
}

HashError hash_table_insert(HashTable *table, void *key, void *value) {
    if (table == NULL || key == NULL) return HASH_ERROR_NULL_POINTER;

    size_t index = table-&gt;hash_function(key) % table-&gt;bucket_count;

    // Check for duplicate key
    struct Entry *current = table-&gt;buckets[index];
    while (current != NULL) {
        if (table-&gt;compare_function(current-&gt;key, key) == 0) {
            return HASH_ERROR_DUPLICATE_KEY;
        }
        current = current-&gt;next;
    }

    // Create new entry
    struct Entry *new_entry = malloc(sizeof(struct Entry));
    if (new_entry == NULL) return HASH_ERROR_MEMORY;

    new_entry-&gt;key = key;
    new_entry-&gt;value = value;
    new_entry-&gt;next = table-&gt;buckets[index];
    table-&gt;buckets[index] = new_entry;
    table-&gt;size++;

    return HASH_SUCCESS;
}

void* hash_table_lookup(const HashTable *table, const void *key) {
    if (table == NULL || key == NULL) return NULL;

    size_t index = table-&gt;hash_function(key) % table-&gt;bucket_count;

    struct Entry *current = table-&gt;buckets[index];
    while (current != NULL) {
        if (table-&gt;compare_function(current-&gt;key, key) == 0) {
            return current-&gt;value;
        }
        current = current-&gt;next;
    }

    return NULL;
}

HashError hash_table_remove(HashTable *table, const void *key) {
    if (table == NULL || key == NULL) return HASH_ERROR_NULL_POINTER;

    size_t index = table-&gt;hash_function(key) % table-&gt;bucket_count;

    struct Entry *current = table-&gt;buckets[index];
    struct Entry *previous = NULL;

    while (current != NULL) {
        if (table-&gt;compare_function(current-&gt;key, key) == 0) {
            if (previous == NULL) {
                table-&gt;buckets[index] = current-&gt;next;
            } else {
                previous-&gt;next = current-&gt;next;
            }

            if (table-&gt;key_destructor != NULL) {
                table-&gt;key_destructor(current-&gt;key);
            }
            if (table-&gt;value_destructor != NULL) {
                table-&gt;value_destructor(current-&gt;value);
            }

            free(current);
            table-&gt;size--;
            return HASH_SUCCESS;
        }

        previous = current;
        current = current-&gt;next;
    }

    return HASH_ERROR_KEY_NOT_FOUND;
}

bool hash_table_contains(const HashTable *table, const void *key) {
    return hash_table_lookup(table, key) != NULL;
}

size_t hash_table_size(const HashTable *table) {
    return (table != NULL) ? table-&gt;size : 0;
}

void hash_table_clear(HashTable *table) {
    if (table == NULL) return;

    for (size_t i = 0; i &lt; table-&gt;bucket_count; i++) {
        struct Entry *current = table-&gt;buckets[i];
        while (current != NULL) {
            struct Entry *next = current-&gt;next;

            if (table-&gt;key_destructor != NULL) {
                table-&gt;key_destructor(current-&gt;key);
            }
            if (table-&gt;value_destructor != NULL) {
                table-&gt;value_destructor(current-&gt;value);
            }

            free(current);
            current = next;
        }
        table-&gt;buckets[i] = NULL;
    }

    table-&gt;size = 0;
}

Practical Examples

Complete ADT Implementation: Dynamic Array
A complete implementation of a dynamic array ADT with comprehensive error handling:
// dynamic_array.h
#ifndef DYNAMIC_ARRAY_H
#define DYNAMIC_ARRAY_H

#include &lt;stddef.h&gt;

typedef struct DynamicArray DynamicArray;

// Error codes
typedef enum {
    DYNARRAY_SUCCESS = 0,
    DYNARRAY_ERROR_NULL_POINTER = -1,
    DYNARRAY_ERROR_OUT_OF_BOUNDS = -2,
    DYNARRAY_ERROR_MEMORY = -3,
    DYNARRAY_ERROR_INVALID_SIZE = -4
} DynamicArrayError;

// Function pointer types
typedef void (*destructor_func)(void *data);
typedef int (*compare_func)(const void *a, const void *b);

// Public interface
DynamicArray* dynamic_array_create(size_t element_size, destructor_func destructor);
void dynamic_array_destroy(DynamicArray *array);
DynamicArrayError dynamic_array_push_back(DynamicArray *array, const void *element);
DynamicArrayError dynamic_array_pop_back(DynamicArray *array, void *element);
DynamicArrayError dynamic_array_get(const DynamicArray *array, size_t index, void *element);
DynamicArrayError dynamic_array_set(DynamicArray *array, size_t index, const void *element);
DynamicArrayError dynamic_array_insert(DynamicArray *array, size_t index, const void *element);
DynamicArrayError dynamic_array_remove(DynamicArray *array, size_t index);
size_t dynamic_array_size(const DynamicArray *array);
size_t dynamic_array_capacity(const DynamicArray *array);
DynamicArrayError dynamic_array_resize(DynamicArray *array, size_t new_size);
DynamicArrayError dynamic_array_clear(DynamicArray *array);
DynamicArrayError dynamic_array_sort(DynamicArray *array, compare_func compare);

#endif // DYNAMIC_ARRAY_H
// dynamic_array.c
#include "dynamic_array.h"
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;

#define INITIAL_CAPACITY 8
#define GROWTH_FACTOR 2

struct DynamicArray {
    void *data;
    size_t size;
    size_t capacity;
    size_t element_size;
    destructor_func destructor;
};

DynamicArray* dynamic_array_create(size_t element_size, destructor_func destructor) {
    if (element_size == 0) return NULL;

    DynamicArray *array = malloc(sizeof(DynamicArray));
    if (array == NULL) return NULL;

    array-&gt;data = malloc(INITIAL_CAPACITY * element_size);
    if (array-&gt;data == NULL) {
        free(array);
        return NULL;
    }

    array-&gt;size = 0;
    array-&gt;capacity = INITIAL_CAPACITY;
    array-&gt;element_size = element_size;
    array-&gt;destructor = destructor;

    return array;
}

void dynamic_array_destroy(DynamicArray *array) {
    if (array != NULL) {
        dynamic_array_clear(array);
        free(array-&gt;data);
        free(array);
    }
}

DynamicArrayError dynamic_array_push_back(DynamicArray *array, const void *element) {
    if (array == NULL || element == NULL) return DYNARRAY_ERROR_NULL_POINTER;

    if (array-&gt;size &gt;= array-&gt;capacity) {
        size_t new_capacity = array-&gt;capacity * GROWTH_FACTOR;
        void *new_data = realloc(array-&gt;data, new_capacity * array-&gt;element_size);
        if (new_data == NULL) return DYNARRAY_ERROR_MEMORY;

        array-&gt;data = new_data;
        array-&gt;capacity = new_capacity;
    }

    void *dest = (char*)array-&gt;data + array-&gt;size * array-&gt;element_size;
    memcpy(dest, element, array-&gt;element_size);
    array-&gt;size++;

    return DYNARRAY_SUCCESS;
}

DynamicArrayError dynamic_array_pop_back(DynamicArray *array, void *element) {
    if (array == NULL) return DYNARRAY_ERROR_NULL_POINTER;
    if (array-&gt;size == 0) return DYNARRAY_ERROR_OUT_OF_BOUNDS;

    if (element != NULL) {
        void *src = (char*)array-&gt;data + (array-&gt;size - 1) * array-&gt;element_size;
        memcpy(element, src, array-&gt;element_size);
    }

    array-&gt;size--;
    return DYNARRAY_SUCCESS;
}

DynamicArrayError dynamic_array_get(const DynamicArray *array, size_t index, void *element) {
    if (array == NULL || element == NULL) return DYNARRAY_ERROR_NULL_POINTER;
    if (index &gt;= array-&gt;size) return DYNARRAY_ERROR_OUT_OF_BOUNDS;

    void *src = (char*)array-&gt;data + index * array-&gt;element_size;
    memcpy(element, src, array-&gt;element_size);

    return DYNARRAY_SUCCESS;
}

DynamicArrayError dynamic_array_set(DynamicArray *array, size_t index, const void *element) {
    if (array == NULL || element == NULL) return DYNARRAY_ERROR_NULL_POINTER;
    if (index &gt;= array-&gt;size) return DYNARRAY_ERROR_OUT_OF_BOUNDS;

    void *dest = (char*)array-&gt;data + index * array-&gt;element_size;
    memcpy(dest, element, array-&gt;element_size);

    return DYNARRAY_SUCCESS;
}

size_t dynamic_array_size(const DynamicArray *array) {
    return (array != NULL) ? array-&gt;size : 0;
}

size_t dynamic_array_capacity(const DynamicArray *array) {
    return (array != NULL) ? array-&gt;capacity : 0;
}

DynamicArrayError dynamic_array_clear(DynamicArray *array) {
    if (array == NULL) return DYNARRAY_ERROR_NULL_POINTER;

    if (array-&gt;destructor != NULL) {
        for (size_t i = 0; i &lt; array-&gt;size; i++) {
            void *element = (char*)array-&gt;data + i * array-&gt;element_size;
            array-&gt;destructor(element);
        }
    }

    array-&gt;size = 0;
    return DYNARRAY_SUCCESS;
}

DynamicArrayError dynamic_array_sort(DynamicArray *array, compare_func compare) {
    if (array == NULL || compare == NULL) return DYNARRAY_ERROR_NULL_POINTER;

    // Simple bubble sort implementation
    for (size_t i = 0; i &lt; array-&gt;size - 1; i++) {
        for (size_t j = 0; j &lt; array-&gt;size - i - 1; j++) {
            void *elem1 = (char*)array-&gt;data + j * array-&gt;element_size;
            void *elem2 = (char*)array-&gt;data + (j + 1) * array-&gt;element_size;

            if (compare(elem1, elem2) &gt; 0) {
                // Swap elements
                char *temp = malloc(array-&gt;element_size);
                if (temp == NULL) return DYNARRAY_ERROR_MEMORY;

                memcpy(temp, elem1, array-&gt;element_size);
                memcpy(elem1, elem2, array-&gt;element_size);
                memcpy(elem2, temp, array-&gt;element_size);

                free(temp);
            }
        }
    }

    return DYNARRAY_SUCCESS;
}
// Example usage
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include "dynamic_array.h"

// Integer destructor
void int_destructor(void *data) {
    // No special cleanup needed for integers
}

// Integer compare function
int compare_ints(const void *a, const void *b) {
    int int_a = *(const int*)a;
    int int_b = *(const int*)b;
    return (int_a &gt; int_b) - (int_a &lt; int_b);
}

int main() {
    DynamicArray *array = dynamic_array_create(sizeof(int), int_destructor);
    if (array == NULL) {
        printf("Failed to create dynamic array\n");
        return 1;
    }

    // Add elements
    for (int i = 10; i &gt;= 1; i--) {
        DynamicArrayError err = dynamic_array_push_back(array, &i);
        if (err != DYNARRAY_SUCCESS) {
            printf("Error adding element: %d\n", err);
            break;
        }
    }

    printf("Array size: %zu, capacity: %zu\n", 
           dynamic_array_size(array), dynamic_array_capacity(array));

    // Print elements
    printf("Before sorting: ");
    for (size_t i = 0; i &lt; dynamic_array_size(array); i++) {
        int value;
        if (dynamic_array_get(array, i, &value) == DYNARRAY_SUCCESS) {
            printf("%d ", value);
        }
    }
    printf("\n");

    // Sort array
    DynamicArrayError err = dynamic_array_sort(array, compare_ints);
    if (err == DYNARRAY_SUCCESS) {
        printf("After sorting: ");
        for (size_t i = 0; i &lt; dynamic_array_size(array); i++) {
            int value;
            if (dynamic_array_get(array, i, &value) == DYNARRAY_SUCCESS) {
                printf("%d ", value);
            }
        }
        printf("\n");
    }

    dynamic_array_destroy(array);
    return 0;
}

