Full Program 2: Simplified wc (Lines, Words, Bytes)
Counts lines, words (whitespace-separated tokens), and bytes — like a small wc:
/* file: mywc.c */
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;ctype.h&gt;
#include &lt;stdbool.h&gt;

struct counts {
    unsigned long lines;
    unsigned long words;
    unsigned long bytes;
};

static int count_stream(FILE *fp, struct counts *c) {
    int ch;
    bool in_word = false;

    c-&gt;lines = c-&gt;words = c-&gt;bytes = 0;

    while ((ch = fgetc(fp)) != EOF) {
        c-&gt;bytes++;

        if (ch == '\n') {
            c-&gt;lines++;
        }

        if (isspace((unsigned char)ch)) {
            in_word = false;
        } else if (!in_word) {
            in_word = true;
            c-&gt;words++;
        }
    }

    if (ferror(fp)) {
        return -1;
    }
    return 0;
}

static void print_counts(const struct counts *c, const char *name) {
    if (name != NULL) {
        printf("%8lu %8lu %8lu %s\n", c-&gt;lines, c-&gt;words, c-&gt;bytes, name);
    } else {
        printf("%8lu %8lu %8lu\n", c-&gt;lines, c-&gt;words, c-&gt;bytes);
    }
}

int main(int argc, char *argv[]) {
    struct counts total = {0, 0, 0};
    int i;
    int status = EXIT_SUCCESS;

    if (argc == 1) {
        struct counts c;
        if (count_stream(stdin, &c) != 0) {
            fprintf(stderr, "read error on stdin\n");
            return EXIT_FAILURE;
        }
        print_counts(&c, NULL);
        return EXIT_SUCCESS;
    }

    for (i = 1; i &lt; argc; i++) {
        FILE *fp = fopen(argv[i], "rb");
        struct counts c;

        if (fp == NULL) {
            perror(argv[i]);
            status = EXIT_FAILURE;
            continue;
        }

        if (count_stream(fp, &c) != 0) {
            fprintf(stderr, "read error: %s\n", argv[i]);
            status = EXIT_FAILURE;
            fclose(fp);
            continue;
        }
        fclose(fp);

        print_counts(&c, argv[i]);
        total.lines += c.lines;
        total.words += c.words;
        total.bytes += c.bytes;
    }

    if (argc &gt; 2) {
        print_counts(&total, "total");
    }

    return status;
}
gcc -std=c17 -Wall -Wextra -o mywc mywc.c
echo -e "hello world\nfoo" &gt; sample.txt
./mywc sample.txt
