Program 6 — Block copy with progress (bcopy.c)
/* file: bcopy.c */
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;
#include &lt;errno.h&gt;

#define BUF_SZ 4096

int main(int argc, char *argv[]) {
    FILE *in, *out;
    unsigned char buf[BUF_SZ];
    size_t n;
    unsigned long long total = 0;

    if (argc != 3) {
        fprintf(stderr, "Usage: %s &lt;src&gt; &lt;dst&gt;\n", argv[0]);
        return EXIT_FAILURE;
    }

    in = fopen(argv[1], "rb");
    if (in == NULL) {
        fprintf(stderr, "open %s: %s\n", argv[1], strerror(errno));
        return EXIT_FAILURE;
    }
    out = fopen(argv[2], "wb");
    if (out == NULL) {
        fprintf(stderr, "open %s: %s\n", argv[2], strerror(errno));
        fclose(in);
        return EXIT_FAILURE;
    }

    while ((n = fread(buf, 1, sizeof buf, in)) &gt; 0) {
        size_t off = 0;
        while (off &lt; n) {
            size_t w = fwrite(buf + off, 1, n - off, out);
            if (w == 0) {
                perror("fwrite");
                fclose(in);
                fclose(out);
                return EXIT_FAILURE;
            }
            off += w;
        }
        total += n;
    }
    if (ferror(in)) {
        perror("fread");
        fclose(in);
        fclose(out);
        return EXIT_FAILURE;
    }

    if (fclose(in) != 0 || fclose(out) != 0) {
        perror("fclose");
        return EXIT_FAILURE;
    }
    fprintf(stderr, "copied %llu bytes\n", total);
    return EXIT_SUCCESS;
}
