Advanced Error Handling with Preprocessor
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;errno.h&gt;
#include &lt;string.h&gt;

// Advanced error handling macros
#define STRINGIFY(x) #x
#define TOSTRING(x) STRINGIFY(x)

// Error checking with automatic cleanup
#define CHECK_ERRNO(call) do { \
    errno = 0; \
    call; \
    if (errno != 0) { \
        fprintf(stderr, "Error in %s at %s:%d: %s\n", \
                #call, __FILE__, __LINE__, strerror(errno)); \
        exit(EXIT_FAILURE); \
    } \
} while(0)

// Resource management with automatic cleanup
#define CLEANUP_VAR(type, name, cleanup_func) \
    type name = NULL; \
    defer_cleanup(cleanup_func, &name)

// Defer mechanism (simplified)
typedef struct defer_node {
    void (*func)(void*);
    void *arg;
    struct defer_node *next;
} defer_node_t;

static defer_node_t *defer_stack = NULL;

void defer_cleanup(void (*func)(void*), void *arg) {
    defer_node_t *node = malloc(sizeof(defer_node_t));
    node-&gt;func = func;
    node-&gt;arg = arg;
    node-&gt;next = defer_stack;
    defer_stack = node;
}

void execute_deferred(void) {
    while (defer_stack) {
        defer_node_t *node = defer_stack;
        defer_stack = node-&gt;next;
        node-&gt;func(node-&gt;arg);
        free(node);
    }
}

#define defer(func, arg) defer_cleanup(func, arg)

// Cleanup functions
void free_ptr(void *ptr) {
    free(*(void**)ptr);
}

void fclose_ptr(void *ptr) {
    if (*(FILE**)ptr) {
        fclose(*(FILE**)ptr);
    }
}

int main() {
    printf("Advanced error handling with preprocessor\n");

    // File operations with automatic error checking
    CLEANUP_VAR(FILE*, fp, fclose_ptr);
    fp = fopen("test.txt", "w");
    if (!fp) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    CHECK_ERRNO(fprintf(fp, "Hello, World!\n"));
    CHECK_ERRNO(fflush(fp));

    // Memory allocation with automatic cleanup
    CLEANUP_VAR(char*, buffer, free_ptr);
    buffer = malloc(100);
    if (!buffer) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    strcpy(buffer, "This is a test buffer");
    printf("Buffer content: %s\n", buffer);

    // Automatic cleanup when scope ends
    execute_deferred();

    return 0;
}

Dynamic Arrays (Vectors)
Dynamic arrays, also known as vectors, are resizable arrays that can grow or shrink during program execution. They provide the benefits of arrays (random access, cache locality) with the flexibility of dynamic sizing.

Basic Dynamic Array Implementation
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;

typedef struct {
    int *data;
    size_t size;
    size_t capacity;
} DynamicArray;

// Initialize dynamic array
DynamicArray* create_array(size_t initial_capacity) {
    DynamicArray *arr = malloc(sizeof(DynamicArray));
    if (arr == NULL) return NULL;

    arr-&gt;data = malloc(initial_capacity * sizeof(int));
    if (arr-&gt;data == NULL) {
        free(arr);
        return NULL;
    }

    arr-&gt;size = 0;
    arr-&gt;capacity = initial_capacity;
    return arr;
}

// Free dynamic array
void free_array(DynamicArray *arr) {
    if (arr != NULL) {
        free(arr-&gt;data);
        free(arr);
    }
}

// Add element to end of array
void push_back(DynamicArray *arr, int value) {
    if (arr-&gt;size &gt;= arr-&gt;capacity) {
        // Double the capacity
        size_t new_capacity = arr-&gt;capacity * 2;
        int *new_data = realloc(arr-&gt;data, new_capacity * sizeof(int));
        if (new_data == NULL) return;  // Handle allocation failure

        arr-&gt;data = new_data;
        arr-&gt;capacity = new_capacity;
    }

    arr-&gt;data[arr-&gt;size] = value;
    arr-&gt;size++;
}

// Remove element from end of array
int pop_back(DynamicArray *arr) {
    if (arr-&gt;size == 0) return 0;  // Handle empty array

    arr-&gt;size--;
    return arr-&gt;data[arr-&gt;size];
}

// Access element at index
int at(DynamicArray *arr, size_t index) {
    if (index &gt;= arr-&gt;size) return 0;  // Handle out of bounds
    return arr-&gt;data[index];
}

// Set element at index
void set(DynamicArray *arr, size_t index, int value) {
    if (index &gt;= arr-&gt;size) return;  // Handle out of bounds
    arr-&gt;data[index] = value;
}

// Insert element at index
void insert(DynamicArray *arr, size_t index, int value) {
    if (index &gt; arr-&gt;size) return;  // Handle invalid index

    if (arr-&gt;size &gt;= arr-&gt;capacity) {
        size_t new_capacity = arr-&gt;capacity * 2;
        int *new_data = realloc(arr-&gt;data, new_capacity * sizeof(int));
        if (new_data == NULL) return;

        arr-&gt;data = new_data;
        arr-&gt;capacity = new_capacity;
    }

    // Shift elements to the right
    for (size_t i = arr-&gt;size; i &gt; index; i--) {
        arr-&gt;data[i] = arr-&gt;data[i - 1];
    }

    arr-&gt;data[index] = value;
    arr-&gt;size++;
}

// Remove element at index
void erase(DynamicArray *arr, size_t index) {
    if (index &gt;= arr-&gt;size) return;  // Handle invalid index

    // Shift elements to the left
    for (size_t i = index; i &lt; arr-&gt;size - 1; i++) {
        arr-&gt;data[i] = arr-&gt;data[i + 1];
    }

    arr-&gt;size--;
}

// Print array contents
void print_array(DynamicArray *arr) {
    printf("Array (size=%zu, capacity=%zu): ", arr-&gt;size, arr-&gt;capacity);
    for (size_t i = 0; i &lt; arr-&gt;size; i++) {
        printf("%d ", arr-&gt;data[i]);
    }
    printf("\n");
}

int main() {
    DynamicArray *arr = create_array(2);
    if (arr == NULL) {
        printf("Failed to create array\n");
        return 1;
    }

    // Test basic operations
    push_back(arr, 10);
    push_back(arr, 20);
    print_array(arr);

    push_back(arr, 30);  // This should trigger a resize
    print_array(arr);

    insert(arr, 1, 15);
    print_array(arr);

    set(arr, 0, 5);
    print_array(arr);

    printf("Element at index 2: %d\n", at(arr, 2));

    erase(arr, 1);
    print_array(arr);

    int popped = pop_back(arr);
    printf("Popped element: %d\n", popped);
    print_array(arr);

    free_array(arr);
    return 0;
}


Generic Dynamic Array
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;

typedef struct {
    void **data;
    size_t size;
    size_t capacity;
    size_t element_size;
} GenericArray;

// Create generic array
GenericArray* create_generic_array(size_t initial_capacity, size_t element_size) {
    GenericArray *arr = malloc(sizeof(GenericArray));
    if (arr == NULL) return NULL;

    arr-&gt;data = malloc(initial_capacity * sizeof(void*));
    if (arr-&gt;data == NULL) {
        free(arr);
        return NULL;
    }

    arr-&gt;size = 0;
    arr-&gt;capacity = initial_capacity;
    arr-&gt;element_size = element_size;
    return arr;
}

// Free generic array
void free_generic_array(GenericArray *arr) {
    if (arr != NULL) {
        for (size_t i = 0; i &lt; arr-&gt;size; i++) {
            free(arr-&gt;data[i]);
        }
        free(arr-&gt;data);
        free(arr);
    }
}

// Add element to generic array
int push_generic(GenericArray *arr, const void *element) {
    if (arr-&gt;size &gt;= arr-&gt;capacity) {
        size_t new_capacity = arr-&gt;capacity * 2;
        void **new_data = realloc(arr-&gt;data, new_capacity * sizeof(void*));
        if (new_data == NULL) return -1;

        arr-&gt;data = new_data;
        arr-&gt;capacity = new_capacity;
    }

    arr-&gt;data[arr-&gt;size] = malloc(arr-&gt;element_size);
    if (arr-&gt;data[arr-&gt;size] == NULL) return -1;

    memcpy(arr-&gt;data[arr-&gt;size], element, arr-&gt;element_size);
    arr-&gt;size++;
    return 0;
}

// Print generic array with custom print function
void print_generic_array(GenericArray *arr, void (*print_func)(const void*)) {
    printf("Generic Array (size=%zu, capacity=%zu): ", arr-&gt;size, arr-&gt;capacity);
    for (size_t i = 0; i &lt; arr-&gt;size; i++) {
        print_func(arr-&gt;data[i]);
        printf(" ");
    }
    printf("\n");
}

// Example with strings
void print_string(const void *str) {
    printf("%s", (const char*)str);
}

int main() {
    // Create array of strings
    GenericArray *str_array = create_generic_array(2, sizeof(char*));
    if (str_array == NULL) {
        printf("Failed to create array\n");
        return 1;
    }

    const char *strings[] = {"Hello", "World", "Generic", "Array"};

    for (int i = 0; i &lt; 4; i++) {
        push_generic(str_array, &strings[i]);
    }

    print_generic_array(str_array, print_string);

    free_generic_array(str_array);
    return 0;
}

Linked Lists
Linked lists are linear data structures where elements are stored in nodes, and each node contains a reference to the next node in the sequence. They provide efficient insertion and deletion operations but have slower access times compared to arrays.

Singly Linked List
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

typedef struct Node {
    int data;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    size_t size;
} LinkedList;

// Create new node
Node* create_node(int data) {
    Node *node = malloc(sizeof(Node));
    if (node == NULL) return NULL;

    node-&gt;data = data;
    node-&gt;next = NULL;
    return node;
}

// Initialize linked list
LinkedList* create_list(void) {
    LinkedList *list = malloc(sizeof(LinkedList));
    if (list == NULL) return NULL;

    list-&gt;head = NULL;
    list-&gt;size = 0;
    return list;
}

// Free linked list
void free_list(LinkedList *list) {
    if (list == NULL) return;

    Node *current = list-&gt;head;
    while (current != NULL) {
        Node *next = current-&gt;next;
        free(current);
        current = next;
    }

    free(list);
}

// Insert at beginning
void push_front(LinkedList *list, int data) {
    Node *new_node = create_node(data);
    if (new_node == NULL) return;

    new_node-&gt;next = list-&gt;head;
    list-&gt;head = new_node;
    list-&gt;size++;
}

// Insert at end
void push_back(LinkedList *list, int data) {
    Node *new_node = create_node(data);
    if (new_node == NULL) return;

    if (list-&gt;head == NULL) {
        list-&gt;head = new_node;
    } else {
        Node *current = list-&gt;head;
        while (current-&gt;next != NULL) {
            current = current-&gt;next;
        }
        current-&gt;next = new_node;
    }
    list-&gt;size++;
}

// Remove from beginning
int pop_front(LinkedList *list) {
    if (list-&gt;head == NULL) return 0;

    Node *temp = list-&gt;head;
    int data = temp-&gt;data;
    list-&gt;head = list-&gt;head-&gt;next;
    free(temp);
    list-&gt;size--;

    return data;
}

// Find element
Node* find(LinkedList *list, int data) {
    Node *current = list-&gt;head;
    while (current != NULL) {
        if (current-&gt;data == data) {
            return current;
        }
        current = current-&gt;next;
    }
    return NULL;
}

// Insert after node
void insert_after(Node *node, int data) {
    if (node == NULL) return;

    Node *new_node = create_node(data);
    if (new_node == NULL) return;

    new_node-&gt;next = node-&gt;next;
    node-&gt;next = new_node;
}

// Delete node with specific data
void delete_node(LinkedList *list, int data) {
    if (list-&gt;head == NULL) return;

    // If head node holds the data
    if (list-&gt;head-&gt;data == data) {
        Node *temp = list-&gt;head;
        list-&gt;head = list-&gt;head-&gt;next;
        free(temp);
        list-&gt;size--;
        return;
    }

    // Search for the node to delete
    Node *current = list-&gt;head;
    while (current-&gt;next != NULL && current-&gt;next-&gt;data != data) {
        current = current-&gt;next;
    }

    // If node was found
    if (current-&gt;next != NULL) {
        Node *temp = current-&gt;next;
        current-&gt;next = current-&gt;next-&gt;next;
        free(temp);
        list-&gt;size--;
    }
}

// Print list
void print_list(LinkedList *list) {
    printf("List (size=%zu): ", list-&gt;size);
    Node *current = list-&gt;head;
    while (current != NULL) {
        printf("%d -&gt; ", current-&gt;data);
        current = current-&gt;next;
    }
    printf("NULL\n");
}

int main() {
    LinkedList *list = create_list();
    if (list == NULL) {
        printf("Failed to create list\n");
        return 1;
    }

    // Test operations
    push_back(list, 10);
    push_back(list, 20);
    push_front(list, 5);
    print_list(list);

    insert_after(list-&gt;head, 7);
    print_list(list);

    Node *found = find(list, 20);
    if (found != NULL) {
        printf("Found node with data: %d\n", found-&gt;data);
    }

    delete_node(list, 7);
    print_list(list);

    int popped = pop_front(list);
    printf("Popped element: %d\n", popped);
    print_list(list);

    free_list(list);
    return 0;
}


Doubly Linked List
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

typedef struct DNode {
    int data;
    struct DNode *next;
    struct DNode *prev;
} DNode;

typedef struct {
    DNode *head;
    DNode *tail;
    size_t size;
} DoublyLinkedList;

// Create new node
DNode* create_dnode(int data) {
    DNode *node = malloc(sizeof(DNode));
    if (node == NULL) return NULL;

    node-&gt;data = data;
    node-&gt;next = NULL;
    node-&gt;prev = NULL;
    return node;
}

// Initialize doubly linked list
DoublyLinkedList* create_dlist(void) {
    DoublyLinkedList *list = malloc(sizeof(DoublyLinkedList));
    if (list == NULL) return NULL;

    list-&gt;head = NULL;
    list-&gt;tail = NULL;
    list-&gt;size = 0;
    return list;
}

// Free doubly linked list
void free_dlist(DoublyLinkedList *list) {
    if (list == NULL) return;

    DNode *current = list-&gt;head;
    while (current != NULL) {
        DNode *next = current-&gt;next;
        free(current);
        current = next;
    }

    free(list);
}

// Insert at beginning
void push_front_dlist(DoublyLinkedList *list, int data) {
    DNode *new_node = create_dnode(data);
    if (new_node == NULL) return;

    if (list-&gt;head == NULL) {
        list-&gt;head = list-&gt;tail = new_node;
    } else {
        new_node-&gt;next = list-&gt;head;
        list-&gt;head-&gt;prev = new_node;
        list-&gt;head = new_node;
    }
    list-&gt;size++;
}

// Insert at end
void push_back_dlist(DoublyLinkedList *list, int data) {
    DNode *new_node = create_dnode(data);
    if (new_node == NULL) return;

    if (list-&gt;tail == NULL) {
        list-&gt;head = list-&gt;tail = new_node;
    } else {
        new_node-&gt;prev = list-&gt;tail;
        list-&gt;tail-&gt;next = new_node;
        list-&gt;tail = new_node;
    }
    list-&gt;size++;
}

// Remove from beginning
int pop_front_dlist(DoublyLinkedList *list) {
    if (list-&gt;head == NULL) return 0;

    DNode *temp = list-&gt;head;
    int data = temp-&gt;data;

    if (list-&gt;head == list-&gt;tail) {
        list-&gt;head = list-&gt;tail = NULL;
    } else {
        list-&gt;head = list-&gt;head-&gt;next;
        list-&gt;head-&gt;prev = NULL;
    }

    free(temp);
    list-&gt;size--;
    return data;
}

// Remove from end
int pop_back_dlist(DoublyLinkedList *list) {
    if (list-&gt;tail == NULL) return 0;

    DNode *temp = list-&gt;tail;
    int data = temp-&gt;data;

    if (list-&gt;head == list-&gt;tail) {
        list-&gt;head = list-&gt;tail = NULL;
    } else {
        list-&gt;tail = list-&gt;tail-&gt;prev;
        list-&gt;tail-&gt;next = NULL;
    }

    free(temp);
    list-&gt;size--;
    return data;
}

// Print list forward
void print_dlist_forward(DoublyLinkedList *list) {
    printf("Forward: ");
    DNode *current = list-&gt;head;
    while (current != NULL) {
        printf("%d ", current-&gt;data);
        current = current-&gt;next;
    }
    printf("\n");
}

// Print list backward
void print_dlist_backward(DoublyLinkedList *list) {
    printf("Backward: ");
    DNode *current = list-&gt;tail;
    while (current != NULL) {
        printf("%d ", current-&gt;data);
        current = current-&gt;prev;
    }
    printf("\n");
}

int main() {
    DoublyLinkedList *list = create_dlist();
    if (list == NULL) {
        printf("Failed to create list\n");
        return 1;
    }

    // Test operations
    push_back_dlist(list, 10);
    push_back_dlist(list, 20);
    push_front_dlist(list, 5);
    push_back_dlist(list, 30);

    print_dlist_forward(list);
    print_dlist_backward(list);

    int front = pop_front_dlist(list);
    printf("Popped from front: %d\n", front);

    int back = pop_back_dlist(list);
    printf("Popped from back: %d\n", back);

    print_dlist_forward(list);

    free_dlist(list);
    return 0;
}

Stacks
A stack is a Last-In-First-Out (LIFO) data structure where elements are added and removed from the same end, called the top.

Array-based Stack
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;stdbool.h&gt;

#define STACK_SIZE 100

typedef struct {
    int data[STACK_SIZE];
    int top;
} ArrayStack;

// Initialize stack
void init_array_stack(ArrayStack *stack) {
    stack-&gt;top = -1;
}

// Check if stack is empty
bool is_empty_array(ArrayStack *stack) {
    return stack-&gt;top == -1;
}

// Check if stack is full
bool is_full_array(ArrayStack *stack) {
    return stack-&gt;top == STACK_SIZE - 1;
}

// Push element onto stack
bool push_array(ArrayStack *stack, int value) {
    if (is_full_array(stack)) {
        return false;  // Stack overflow
    }

    stack-&gt;data[++stack-&gt;top] = value;
    return true;
}

// Pop element from stack
int pop_array(ArrayStack *stack) {
    if (is_empty_array(stack)) {
        return 0;  // Stack underflow
    }

    return stack-&gt;data[stack-&gt;top--];
}

// Peek at top element
int peek_array(ArrayStack *stack) {
    if (is_empty_array(stack)) {
        return 0;  // Stack is empty
    }

    return stack-&gt;data[stack-&gt;top];
}

// Print stack contents
void print_array_stack(ArrayStack *stack) {
    if (is_empty_array(stack)) {
        printf("Stack is empty\n");
        return;
    }

    printf("Stack (top to bottom): ");
    for (int i = stack-&gt;top; i &gt;= 0; i--) {
        printf("%d ", stack-&gt;data[i]);
    }
    printf("\n");
}

int main() {
    ArrayStack stack;
    init_array_stack(&stack);

    // Test stack operations
    push_array(&stack, 10);
    push_array(&stack, 20);
    push_array(&stack, 30);

    print_array_stack(&stack);

    printf("Top element: %d\n", peek_array(&stack));

    int popped = pop_array(&stack);
    printf("Popped element: %d\n", popped);

    print_array_stack(&stack);

    return 0;
}


