// Dequeue (remove) element from queue
int dequeue_linked(LinkedQueue *queue) {
    if (is_empty_linked_queue(queue)) {
        return 0;  // Queue underflow
    }

    QueueNode *temp = queue-&gt;front;
    int data = temp-&gt;data;

    queue-&gt;front = queue-&gt;front-&gt;next;
    if (queue-&gt;front == NULL) {
        queue-&gt;rear = NULL;  // Queue is now empty
    }

    free(temp);
    queue-&gt;size--;

    return data;
}

// Peek at front element
int front_linked_queue(LinkedQueue *queue) {
    if (is_empty_linked_queue(queue)) {
        return 0;  // Queue is empty
    }

    return queue-&gt;front-&gt;data;
}

// Print queue contents
void print_linked_queue(LinkedQueue *queue) {
    if (is_empty_linked_queue(queue)) {
        printf("Queue is empty\n");
        return;
    }

    printf("Queue (front to rear): ");
    QueueNode *current = queue-&gt;front;
    while (current != NULL) {
        printf("%d ", current-&gt;data);
        current = current-&gt;next;
    }
    printf("\n");
}

int main() {
    LinkedQueue *queue = create_linked_queue();
    if (queue == NULL) {
        printf("Failed to create queue\n");
        return 1;
    }

    // Test queue operations
    enqueue_linked(queue, 10);
    enqueue_linked(queue, 20);
    enqueue_linked(queue, 30);

    print_linked_queue(queue);

    printf("Front element: %d\n", front_linked_queue(queue));

    int dequeued = dequeue_linked(queue);
    printf("Dequeued element: %d\n", dequeued);

    print_linked_queue(queue);

    free_linked_queue(queue);
    return 0;
}

Practical Examples

Expression Evaluation Using Stacks
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;stdbool.h&gt;
#include &lt;string.h&gt;
#include &lt;ctype.h&gt;

#define STACK_SIZE 100

typedef struct {
    int data[STACK_SIZE];
    int top;
} Stack;

void init_stack(Stack *stack) {
    stack-&gt;top = -1;
}

bool is_empty(Stack *stack) {
    return stack-&gt;top == -1;
}

bool is_full(Stack *stack) {
    return stack-&gt;top == STACK_SIZE - 1;
}

bool push(Stack *stack, int value) {
    if (is_full(stack)) return false;
    stack-&gt;data[++stack-&gt;top] = value;
    return true;
}

int pop(Stack *stack) {
    if (is_empty(stack)) return 0;
    return stack-&gt;data[stack-&gt;top--];
}

int peek(Stack *stack) {
    if (is_empty(stack)) return 0;
    return stack-&gt;data[stack-&gt;top];
}

// Check if character is operator
bool is_operator(char c) {
    return (c == '+' || c == '-' || c == '*' || c == '/');
}

// Get precedence of operator
int precedence(char op) {
    switch (op) {
        case '+':
        case '-':
            return 1;
        case '*':
        case '/':
            return 2;
        default:
            return 0;
    }
}

// Convert infix to postfix
void infix_to_postfix(const char *infix, char *postfix) {
    Stack stack;
    init_stack(&stack);

    int i, j = 0;
    for (i = 0; infix[i] != '\0'; i++) {
        char c = infix[i];

        if (isdigit(c)) {
            postfix[j++] = c;
        } else if (c == '(') {
            push(&stack, c);
        } else if (c == ')') {
            while (!is_empty(&stack) && peek(&stack) != '(') {
                postfix[j++] = pop(&stack);
            }
            pop(&stack);  // Pop '('
        } else if (is_operator(c)) {
            while (!is_empty(&stack) && precedence(peek(&stack)) &gt;= precedence(c)) {
                postfix[j++] = pop(&stack);
            }
            push(&stack, c);
        }
    }

    while (!is_empty(&stack)) {
        postfix[j++] = pop(&stack);
    }

    postfix[j] = '\0';
}

// Evaluate postfix expression
int evaluate_postfix(const char *postfix) {
    Stack stack;
    init_stack(&stack);

    for (int i = 0; postfix[i] != '\0'; i++) {
        char c = postfix[i];

        if (isdigit(c)) {
            push(&stack, c - '0');
        } else if (is_operator(c)) {
            int b = pop(&stack);
            int a = pop(&stack);

            switch (c) {
                case '+':
                    push(&stack, a + b);
                    break;
                case '-':
                    push(&stack, a - b);
                    break;
                case '*':
                    push(&stack, a * b);
                    break;
                case '/':
                    push(&stack, a / b);
                    break;
            }
        }
    }

    return pop(&stack);
}

int main() {
    char infix[] = "3+4*2/(1-5)";
    char postfix[100];

    printf("Infix expression: %s\n", infix);

    infix_to_postfix(infix, postfix);
    printf("Postfix expression: %s\n", postfix);

    int result = evaluate_postfix(postfix);
    printf("Result: %d\n", result);

    return 0;
}

Binary Trees
A binary tree is a tree data structure where each node has at most two children, referred to as the left child and the right child.

Basic Binary Tree Implementation
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;stdbool.h&gt;

typedef struct TreeNode {
    int data;
    struct TreeNode *left;
    struct TreeNode *right;
} TreeNode;

// Create new tree node
TreeNode* create_node(int data) {
    TreeNode *node = malloc(sizeof(TreeNode));
    if (node == NULL) return NULL;

    node-&gt;data = data;
    node-&gt;left = NULL;
    node-&gt;right = NULL;
    return node;
}

// Free entire tree
void free_tree(TreeNode *root) {
    if (root == NULL) return;

    free_tree(root-&gt;left);
    free_tree(root-&gt;right);
    free(root);
}

// Insert node in binary tree (level-order insertion)
TreeNode* insert_level_order(TreeNode *root, int data) {
    TreeNode *new_node = create_node(data);
    if (new_node == NULL) return root;

    if (root == NULL) {
        return new_node;
    }

    // Use queue for level-order insertion
    TreeNode *queue[100];
    int front = 0, rear = 0;
    queue[rear++] = root;

    while (front &lt; rear) {
        TreeNode *current = queue[front++];

        if (current-&gt;left == NULL) {
            current-&gt;left = new_node;
            return root;
        } else {
            queue[rear++] = current-&gt;left;
        }

        if (current-&gt;right == NULL) {
            current-&gt;right = new_node;
            return root;
        } else {
            queue[rear++] = current-&gt;right;
        }
    }

    return root;
}

// Tree traversals
void inorder_traversal(TreeNode *root) {
    if (root == NULL) return;

    inorder_traversal(root-&gt;left);
    printf("%d ", root-&gt;data);
    inorder_traversal(root-&gt;right);
}

void preorder_traversal(TreeNode *root) {
    if (root == NULL) return;

    printf("%d ", root-&gt;data);
    preorder_traversal(root-&gt;left);
    preorder_traversal(root-&gt;right);
}

void postorder_traversal(TreeNode *root) {
    if (root == NULL) return;

    postorder_traversal(root-&gt;left);
    postorder_traversal(root-&gt;right);
    printf("%d ", root-&gt;data);
}

// Level-order traversal (breadth-first)
void level_order_traversal(TreeNode *root) {
    if (root == NULL) return;

    TreeNode *queue[100];
    int front = 0, rear = 0;
    queue[rear++] = root;

    while (front &lt; rear) {
        TreeNode *current = queue[front++];
        printf("%d ", current-&gt;data);

        if (current-&gt;left != NULL) {
            queue[rear++] = current-&gt;left;
        }

        if (current-&gt;right != NULL) {
            queue[rear++] = current-&gt;right;
        }
    }
}

// Tree height
int tree_height(TreeNode *root) {
    if (root == NULL) return 0;

    int left_height = tree_height(root-&gt;left);
    int right_height = tree_height(root-&gt;right);

    return 1 + (left_height &gt; right_height ? left_height : right_height);
}

// Node count
int node_count(TreeNode *root) {
    if (root == NULL) return 0;

    return 1 + node_count(root-&gt;left) + node_count(root-&gt;right);
}

// Leaf count
int leaf_count(TreeNode *root) {
    if (root == NULL) return 0;

    if (root-&gt;left == NULL && root-&gt;right == NULL) {
        return 1;
    }

    return leaf_count(root-&gt;left) + leaf_count(root-&gt;right);
}

int main() {
    TreeNode *root = NULL;

    // Build tree: 1, 2, 3, 4, 5, 6, 7
    for (int i = 1; i &lt;= 7; i++) {
        root = insert_level_order(root, i);
    }

    printf("Inorder traversal: ");
    inorder_traversal(root);
    printf("\n");

    printf("Preorder traversal: ");
    preorder_traversal(root);
    printf("\n");

    printf("Postorder traversal: ");
    postorder_traversal(root);
    printf("\n");

    printf("Level-order traversal: ");
    level_order_traversal(root);
    printf("\n");

    printf("Tree height: %d\n", tree_height(root));
    printf("Node count: %d\n", node_count(root));
    printf("Leaf count: %d\n", leaf_count(root));

    free_tree(root);
    return 0;
}

Binary Search Trees (BST)
A binary search tree is a binary tree where each node follows the property that all values in the left subtree are less than the node’s value, and all values in the right subtree are greater than the node’s value.

BST Implementation
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;stdbool.h&gt;

typedef struct BSTNode {
    int data;
    struct BSTNode *left;
    struct BSTNode *right;
} BSTNode;

// Create new BST node
BSTNode* create_bst_node(int data) {
    BSTNode *node = malloc(sizeof(BSTNode));
    if (node == NULL) return NULL;

    node-&gt;data = data;
    node-&gt;left = NULL;
    node-&gt;right = NULL;
    return node;
}

// Free BST
void free_bst(BSTNode *root) {
    if (root == NULL) return;

    free_bst(root-&gt;left);
    free_bst(root-&gt;right);
    free(root);
}

// Insert node in BST
BSTNode* insert_bst(BSTNode *root, int data) {
    if (root == NULL) {
        return create_bst_node(data);
    }

    if (data &lt; root-&gt;data) {
        root-&gt;left = insert_bst(root-&gt;left, data);
    } else if (data &gt; root-&gt;data) {
        root-&gt;right = insert_bst(root-&gt;right, data);
    }
    // If data == root-&gt;data, we don't insert duplicates

    return root;
}

// Search in BST
BSTNode* search_bst(BSTNode *root, int data) {
    if (root == NULL || root-&gt;data == data) {
        return root;
    }

    if (data &lt; root-&gt;data) {
        return search_bst(root-&gt;left, data);
    } else {
        return search_bst(root-&gt;right, data);
    }
}

// Find minimum value node
BSTNode* find_min(BSTNode *root) {
    if (root == NULL) return NULL;

    while (root-&gt;left != NULL) {
        root = root-&gt;left;
    }

    return root;
}

// Find maximum value node
BSTNode* find_max(BSTNode *root) {
    if (root == NULL) return NULL;

    while (root-&gt;right != NULL) {
        root = root-&gt;right;
    }

    return root;
}

// Delete node from BST
BSTNode* delete_bst(BSTNode *root, int data) {
    if (root == NULL) return root;

    if (data &lt; root-&gt;data) {
        root-&gt;left = delete_bst(root-&gt;left, data);
    } else if (data &gt; root-&gt;data) {
        root-&gt;right = delete_bst(root-&gt;right, data);
    } else {
        // Node to be deleted found

        // Case 1: Node has no children
        if (root-&gt;left == NULL && root-&gt;right == NULL) {
            free(root);
            return NULL;
        }

        // Case 2: Node has one child
        if (root-&gt;left == NULL) {
            BSTNode *temp = root-&gt;right;
            free(root);
            return temp;
        }

        if (root-&gt;right == NULL) {
            BSTNode *temp = root-&gt;left;
            free(root);
            return temp;
        }

        // Case 3: Node has two children
        BSTNode *temp = find_min(root-&gt;right);
        root-&gt;data = temp-&gt;data;
        root-&gt;right = delete_bst(root-&gt;right, temp-&gt;data);
    }

    return root;
}

// Inorder traversal (gives sorted order for BST)
void inorder_bst(BSTNode *root) {
    if (root == NULL) return;

    inorder_bst(root-&gt;left);
    printf("%d ", root-&gt;data);
    inorder_bst(root-&gt;right);
}

// Check if tree is valid BST
bool is_valid_bst(BSTNode *root, long min_val, long max_val) {
    if (root == NULL) return true;

    if (root-&gt;data &lt;= min_val || root-&gt;data &gt;= max_val) {
        return false;
    }

    return is_valid_bst(root-&gt;left, min_val, root-&gt;data) &&
           is_valid_bst(root-&gt;right, root-&gt;data, max_val);
}

bool validate_bst(BSTNode *root) {
    return is_valid_bst(root, LONG_MIN, LONG_MAX);
}

int main() {
    BSTNode *root = NULL;

    // Insert nodes
    int values[] = {50, 30, 70, 20, 40, 60, 80, 10, 25, 35, 45};
    int n = sizeof(values) / sizeof(values[0]);

    for (int i = 0; i &lt; n; i++) {
        root = insert_bst(root, values[i]);
    }

    printf("BST inorder traversal (sorted): ");
    inorder_bst(root);
    printf("\n");

    printf("Is valid BST: %s\n", validate_bst(root) ? "Yes" : "No");

    // Search operations
    int search_values[] = {25, 35, 90};
    for (int i = 0; i &lt; 3; i++) {
        BSTNode *found = search_bst(root, search_values[i]);
        printf("Search %d: %s\n", search_values[i], 
               found ? "Found" : "Not found");
    }

    // Find min and max
    BSTNode *min_node = find_min(root);
    BSTNode *max_node = find_max(root);
    printf("Minimum value: %d\n", min_node ? min_node-&gt;data : -1);
    printf("Maximum value: %d\n", max_node ? max_node-&gt;data : -1);

    // Delete operations
    printf("Deleting 20...\n");
    root = delete_bst(root, 20);
    printf("BST after deletion: ");
    inorder_bst(root);
    printf("\n");

    printf("Deleting 30...\n");
    root = delete_bst(root, 30);
    printf("BST after deletion: ");
    inorder_bst(root);
    printf("\n");

    printf("Deleting 50...\n");
    root = delete_bst(root, 50);
    printf("BST after deletion: ");
    inorder_bst(root);
    printf("\n");

    free_bst(root);
    return 0;
}

AVL Trees
AVL trees are self-balancing binary search trees where the heights of the two child subtrees of any node differ by at most one. This ensures O(log n) time complexity for search, insert, and delete operations.

AVL Tree Implementation
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;stdbool.h&gt;
#include &lt;math.h&gt;

typedef struct AVLNode {
    int data;
    struct AVLNode *left;
    struct AVLNode *right;
    int height;
} AVLNode;

// Get height of node
int get_height(AVLNode *node) {
    return node ? node-&gt;height : 0;
}

// Get balance factor
int get_balance(AVLNode *node) {
    return node ? get_height(node-&gt;left) - get_height(node-&gt;right) : 0;
}

// Create new AVL node
AVLNode* create_avl_node(int data) {
    AVLNode *node = malloc(sizeof(AVLNode));
    if (node == NULL) return NULL;

    node-&gt;data = data;
    node-&gt;left = NULL;
    node-&gt;right = NULL;
    node-&gt;height = 1;  // New node is initially at leaf level
    return node;
}

// Free AVL tree
void free_avl(AVLNode *root) {
    if (root == NULL) return;

    free_avl(root-&gt;left);
    free_avl(root-&gt;right);
    free(root);
}

// Update height of node
void update_height(AVLNode *node) {
    if (node != NULL) {
        node-&gt;height = 1 + fmax(get_height(node-&gt;left), get_height(node-&gt;right));
    }
}

// Right rotate
AVLNode* right_rotate(AVLNode *y) {
    AVLNode *x = y-&gt;left;
    AVLNode *T2 = x-&gt;right;

    // Perform rotation
    x-&gt;right = y;
    y-&gt;left = T2;

    // Update heights
    update_height(y);
    update_height(x);

    // Return new root
    return x;
}

// Left rotate
AVLNode* left_rotate(AVLNode *x) {
    AVLNode *y = x-&gt;right;
    AVLNode *T2 = y-&gt;left;

    // Perform rotation
    y-&gt;left = x;
    x-&gt;right = T2;

    // Update heights
    update_height(x);
    update_height(y);

    // Return new root
    return y;
}

// Insert node in AVL tree
AVLNode* insert_avl(AVLNode *root, int data) {
    // 1. Perform normal BST insertion
    if (root == NULL) {
        return create_avl_node(data);
    }

    if (data &lt; root-&gt;data) {
        root-&gt;left = insert_avl(root-&gt;left, data);
    } else if (data &gt; root-&gt;data) {
        root-&gt;right = insert_avl(root-&gt;right, data);
    } else {
        // Equal keys not allowed
        return root;
    }

    // 2. Update height of this ancestor node
    update_height(root);

    // 3. Get balance factor
    int balance = get_balance(root);

    // 4. If unbalanced, perform rotations

    // Left Left Case
    if (balance &gt; 1 && data &lt; root-&gt;left-&gt;data) {
        return right_rotate(root);
    }

    // Right Right Case
    if (balance &lt; -1 && data &gt; root-&gt;right-&gt;data) {
        return left_rotate(root);
    }

    // Left Right Case
    if (balance &gt; 1 && data &gt; root-&gt;left-&gt;data) {
        root-&gt;left = left_rotate(root-&gt;left);
        return right_rotate(root);
    }

    // Right Left Case
    if (balance &lt; -1 && data &lt; root-&gt;right-&gt;data) {
        root-&gt;right = right_rotate(root-&gt;right);
        return left_rotate(root);
    }

    // Return unchanged node pointer
    return root;
}

// Find node with minimum value
AVLNode* find_min_avl(AVLNode *root) {
    if (root == NULL) return NULL;

    while (root-&gt;left != NULL) {
        root = root-&gt;left;
    }

    return root;
}

// Delete node from AVL tree
AVLNode* delete_avl(AVLNode *root, int data) {
    // 1. Perform standard BST deletion
    if (root == NULL) return root;

    if (data &lt; root-&gt;data) {
        root-&gt;left = delete_avl(root-&gt;left, data);
    } else if (data &gt; root-&gt;data) {
        root-&gt;right = delete_avl(root-&gt;right, data);
    } else {
        // Node to be deleted found
        if (root-&gt;left == NULL || root-&gt;right == NULL) {
            AVLNode *temp = root-&gt;left ? root-&gt;left : root-&gt;right;

            if (temp == NULL) {
                temp = root;
                root = NULL;
            } else {
                *root = *temp;
            }

            free(temp);
        } else {
            AVLNode *temp = find_min_avl(root-&gt;right);
            root-&gt;data = temp-&gt;data;
            root-&gt;right = delete_avl(root-&gt;right, temp-&gt;data);
        }
    }

    if (root == NULL) return root;

    // 2. Update height of current node
    update_height(root);

    // 3. Get balance factor
    int balance = get_balance(root);

    // 4. If unbalanced, perform rotations

    // Left Left Case
    if (balance &gt; 1 && get_balance(root-&gt;left) &gt;= 0) {
        return right_rotate(root);
    }

    // Left Right Case
    if (balance &gt; 1 && get_balance(root-&gt;left) &lt; 0) {
        root-&gt;left = left_rotate(root-&gt;left);
        return right_rotate(root);
    }

    // Right Right Case
    if (balance &lt; -1 && get_balance(root-&gt;right) &lt;= 0) {
        return left_rotate(root);
    }

    // Right Left Case
    if (balance &lt; -1 && get_balance(root-&gt;right) &gt; 0) {
        root-&gt;right = right_rotate(root-&gt;right);
        return left_rotate(root);
    }

    return root;
}

// Search in AVL tree
AVLNode* search_avl(AVLNode *root, int data) {
    if (root == NULL || root-&gt;data == data) {
        return root;
    }

    if (data &lt; root-&gt;data) {
        return search_avl(root-&gt;left, data);
    } else {
        return search_avl(root-&gt;right, data);
    }
}

// Inorder traversal
void inorder_avl(AVLNode *root) {
    if (root == NULL) return;

    inorder_avl(root-&gt;left);
    printf("%d ", root-&gt;data);
    inorder_avl(root-&gt;right);
}

// Check if tree is balanced
bool is_balanced(AVLNode *root) {
    if (root == NULL) return true;

    int balance = get_balance(root);
    if (abs(balance) &gt; 1) return false;

    return is_balanced(root-&gt;left) && is_balanced(root-&gt;right);
}

int main() {
    AVLNode *root = NULL;

    // Insert nodes
    int values[] = {10, 20, 30, 40, 50, 25};
    int n = sizeof(values) / sizeof(values[0]);

    printf("Inserting values: ");
    for (int i = 0; i &lt; n; i++) {
        printf("%d ", values[i]);
        root = insert_avl(root, values[i]);
    }
    printf("\n");

    printf("AVL tree inorder traversal: ");
    inorder_avl(root);
    printf("\n");

    printf("Is tree balanced: %s\n", is_balanced(root) ? "Yes" : "No");
    printf("Root height: %d\n", get_height(root));

    // Search operations
    int search_values[] = {25, 35, 60};
    for (int i = 0; i &lt; 3; i++) {
        AVLNode *found = search_avl(root, search_values[i]);
        printf("Search %d: %s\n", search_values[i], 
               found ? "Found" : "Not found");
    }

    // Delete operations
    printf("Deleting 30...\n");
    root = delete_avl(root, 30);
    printf("AVL tree after deletion: ");
    inorder_avl(root);
    printf("\n");

    printf("Is tree balanced: %s\n", is_balanced(root) ? "Yes" : "No");
    printf("Root height: %d\n", get_height(root));

    free_avl(root);
    return 0;
}

Red-Black Trees
Red-black trees are another type of self-balancing binary search tree with additional properties that ensure the tree remains approximately balanced during insertions and deletions.

Red-Black Tree Properties

Every node is either red or black
The root is black
All leaves (NIL nodes) are black
If a node is red, both its children are black
Every path from a node to its descendant leaves contains the same number of black nodes

#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;stdbool.h&gt;

typedef enum { RED, BLACK } Color;

typedef struct RBNode {
    int data;
    Color color;
    struct RBNode *left;
    struct RBNode *right;
    struct RBNode *parent;
} RBNode;

// Global NIL node (sentinel)
RBNode *NIL;

// Initialize NIL node
void init_nil(void) {
    NIL = malloc(sizeof(RBNode));
    NIL-&gt;color = BLACK;
    NIL-&gt;left = NIL-&gt;right = NIL-&gt;parent = NULL;
}

// Create new red-black node
RBNode* create_rb_node(int data) {
    RBNode *node = malloc(sizeof(RBNode));
    if (node == NULL) return NULL;

    node-&gt;data = data;
    node-&gt;color = RED;  // New nodes are red by default
    node-&gt;left = node-&gt;right = node-&gt;parent = NIL;
    return node;
}

// Free red-black tree
void free_rb_tree(RBNode *root) {
    if (root == NULL || root == NIL) return;

    free_rb_tree(root-&gt;left);
    free_rb_tree(root-&gt;right);
    free(root);
}

// Left rotate
void left_rotate(RBNode **root, RBNode *x) {
    RBNode *y = x-&gt;right;

    // Turn y's left subtree into x's right subtree
    x-&gt;right = y-&gt;left;
    if (y-&gt;left != NIL) {
        y-&gt;left-&gt;parent = x;
    }

    // Link x's parent to y
    y-&gt;parent = x-&gt;parent;
    if (x-&gt;parent == NIL) {
        *root = y;
    } else if (x == x-&gt;parent-&gt;left) {
        x-&gt;parent-&gt;left = y;
    } else {
        x-&gt;parent-&gt;right = y;
    }

    // Put x on y's left
    y-&gt;left = x;
    x-&gt;parent = y;
}

// Right rotate
void right_rotate(RBNode **root, RBNode *y) {
    RBNode *x = y-&gt;left;

    // Turn x's right subtree into y's left subtree
    y-&gt;left = x-&gt;right;
    if (x-&gt;right != NIL) {
        x-&gt;right-&gt;parent = y;
    }

    // Link y's parent to x
    x-&gt;parent = y-&gt;parent;
    if (y-&gt;parent == NIL) {
        *root = x;
    } else if (y == y-&gt;parent-&gt;right) {
        y-&gt;parent-&gt;right = x;
    } else {
        y-&gt;parent-&gt;left = x;
    }

    // Put y on x's right
    x-&gt;right = y;
    y-&gt;parent = x;
}

// Fixup after insertion
void insert_fixup(RBNode **root, RBNode *z) {
    while (z-&gt;parent-&gt;color == RED) {
        if (z-&gt;parent == z-&gt;parent-&gt;parent-&gt;left) {
            RBNode *y = z-&gt;parent-&gt;parent-&gt;right;

            if (y-&gt;color == RED) {
                // Case 1: Uncle is red
                z-&gt;parent-&gt;color = BLACK;
                y-&gt;color = BLACK;
                z-&gt;parent-&gt;parent-&gt;color = RED;
                z = z-&gt;parent-&gt;parent;
            } else {
                if (z == z-&gt;parent-&gt;right) {
                    // Case 2: Uncle is black and z is right child
                    z = z-&gt;parent;
                    left_rotate(root, z);
                }
                // Case 3: Uncle is black and z is left child
                z-&gt;parent-&gt;color = BLACK;
                z-&gt;parent-&gt;parent-&gt;color = RED;
                right_rotate(root, z-&gt;parent-&gt;parent);
            }
        } else {
            RBNode *y = z-&gt;parent-&gt;parent-&gt;left;

            if (y-&gt;color == RED) {
                // Case 1: Uncle is red
                z-&gt;parent-&gt;color = BLACK;
                y-&gt;color = BLACK;
                z-&gt;parent-&gt;parent-&gt;color = RED;
                z = z-&gt;parent-&gt;parent;
            } else {
                if (z == z-&gt;parent-&gt;left) {
                    // Case 2: Uncle is black and z is left child
                    z = z-&gt;parent;
                    right_rotate(root, z);
                }
                // Case 3: Uncle is black and z is right child
                z-&gt;parent-&gt;color = BLACK;
                z-&gt;parent-&gt;parent-&gt;color = RED;
                left_rotate(root, z-&gt;parent-&gt;parent);
            }
        }
    }
    (*root)-&gt;color = BLACK;
}

// Insert node in red-black tree
RBNode* insert_rb(RBNode **root, int data) {
    RBNode *z = create_rb_node(data);
    if (z == NULL) return NULL;

    RBNode *y = NIL;
    RBNode *x = *root;

    // Find insertion point
    while (x != NIL) {
        y = x;
        if (z-&gt;data &lt; x-&gt;data) {
            x = x-&gt;left;
        } else {
            x = x-&gt;right;
        }
    }

    z-&gt;parent = y;
    if (y == NIL) {
        *root = z;
    } else if (z-&gt;data &lt; y-&gt;data) {
        y-&gt;left = z;
    } else {
        y-&gt;right = z;
    }

    // Fix red-black properties
    insert_fixup(root, z);

    return z;
}

// Inorder traversal
void inorder_rb(RBNode *root) {
    if (root == NULL || root == NIL) return;

    inorder_rb(root-&gt;left);
    printf("%d(%s) ", root-&gt;data, root-&gt;color == RED ? "R" : "B");
    inorder_rb(root-&gt;right);
}

int main() {
    init_nil();

    RBNode *root = NIL;

    // Insert nodes
    int values[] = {7, 3, 18, 10, 22, 8, 11, 26};
    int n = sizeof(values) / sizeof(values[0]);

    printf("Inserting values into red-black tree: ");
    for (int i = 0; i &lt; n; i++) {
        printf("%d ", values[i]);
        insert_rb(&root, values[i]);
    }
    printf("\n");

    printf("Red-black tree inorder traversal: ");
    inorder_rb(root);
    printf("\n");

    free_rb_tree(root);
    free(NIL);
    return 0;
}

B-Trees
B-trees are balanced tree data structures that maintain sorted data and allow for efficient insertion, deletion, and search operations. They are commonly used in databases and file systems.

B-Tree Implementation (Simplified)
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;stdbool.h&gt;

#define T 3  // Minimum degree

typedef struct BTreeNode {
    int n;                    // Number of keys
    int keys[2 * T - 1];      // Array of keys
    struct BTreeNode *children[2 * T];  // Array of child pointers
    bool leaf;                // True if node is leaf
} BTreeNode;

// Create new B-tree node
BTreeNode* create_btree_node(bool leaf) {
    BTreeNode *node = malloc(sizeof(BTreeNode));
    if (node == NULL) return NULL;

    node-&gt;n = 0;
    node-&gt;leaf = leaf;

    for (int i = 0; i &lt; 2 * T; i++) {
        node-&gt;children[i] = NULL;
    }

    return node;
}

// Search for key in B-tree
BTreeNode* search_btree(BTreeNode *root, int key) {
    int i = 0;
    while (i &lt; root-&gt;n && key &gt; root-&gt;keys[i]) {
        i++;
    }

    if (i &lt; root-&gt;n && key == root-&gt;keys[i]) {
        return root;
    }

    if (root-&gt;leaf) {
        return NULL;
    }

    return search_btree(root-&gt;children[i], key);
}

// Split child node
void split_child(BTreeNode *parent, int i, BTreeNode *child) {
    BTreeNode *z = create_btree_node(child-&gt;leaf);
    z-&gt;n = T - 1;

    // Copy the last T-1 keys of child to z
    for (int j = 0; j &lt; T - 1; j++) {
        z-&gt;keys[j] = child-&gt;keys[j + T];
    }

    // Copy the last T children of child to z
    if (!child-&gt;leaf) {
        for (int j = 0; j &lt; T; j++) {
            z-&gt;children[j] = child-&gt;children[j + T];
        }
    }

    child-&gt;n = T - 1;

    // Shift parent's children to make space for z
    for (int j = parent-&gt;n; j &gt;= i + 1; j--) {
        parent-&gt;children[j + 1] = parent-&gt;children[j];
    }

    parent-&gt;children[i + 1] = z;

    // Shift parent's keys to make space
    for (int j = parent-&gt;n - 1; j &gt;= i; j--) {
        parent-&gt;keys[j + 1] = parent-&gt;keys[j];
    }

    parent-&gt;keys[i] = child-&gt;keys[T - 1];
    parent-&gt;n++;
}

// Insert non-full node
void insert_non_full(BTreeNode *node, int key) {
    int i = node-&gt;n - 1;

    if (node-&gt;leaf) {
        // Find location to insert key and shift keys
        while (i &gt;= 0 && node-&gt;keys[i] &gt; key) {
            node-&gt;keys[i + 1] = node-&gt;keys[i];
            i--;
        }

        node-&gt;keys[i + 1] = key;
        node-&gt;n++;
    } else {
        // Find child to recurse on
        while (i &gt;= 0 && node-&gt;keys[i] &gt; key) {
            i--;
        }
        i++;

        // Split child if it's full
        if (node-&gt;children[i]-&gt;n == 2 * T - 1) {
            split_child(node, i, node-&gt;children[i]);

            if (node-&gt;keys[i] &lt; key) {
                i++;
            }
        }

        insert_non_full(node-&gt;children[i], key);
    }
}

// Insert key in B-tree
BTreeNode* insert_btree(BTreeNode *root, int key) {
    if (root == NULL) {
        root = create_btree_node(true);
        root-&gt;keys[0] = key;
        root-&gt;n = 1;
        return root;
    }

    // If root is full, split it
    if (root-&gt;n == 2 * T - 1) {
        BTreeNode *new_root = create_btree_node(false);
        new_root-&gt;children[0] = root;
        split_child(new_root, 0, root);

        int i = 0;
        if (new_root-&gt;keys[0] &lt; key) {
            i++;
        }

        insert_non_full(new_root-&gt;children[i], key);
        return new_root;
    } else {
        insert_non_full(root, key);
        return root;
    }
}

// Print B-tree
void print_btree(BTreeNode *root, int level) {
    if (root == NULL) return;

    for (int i = 0; i &lt; level; i++) {
        printf("  ");
    }

    printf("Level %d: [", level);
    for (int i = 0; i &lt; root-&gt;n; i++) {
        printf("%d ", root-&gt;keys[i]);
    }
    printf("]\n");

    if (!root-&gt;leaf) {
        for (int i = 0; i &lt;= root-&gt;n; i++) {
            print_btree(root-&gt;children[i], level + 1);
        }
    }
}

int main() {
    BTreeNode *root = NULL;

    // Insert nodes
    int values[] = {10, 20, 5, 6, 12, 30, 7, 17};
    int n = sizeof(values) / sizeof(values[0]);

    printf("Inserting values into B-tree: ");
    for (int i = 0; i &lt; n; i++) {
        printf("%d ", values[i]);
        root = insert_btree(root, values[i]);
    }
    printf("\n\n");

    printf("B-tree structure:\n");
    print_btree(root, 0);

    // Search operations
    int search_values[] = {6, 15, 17};
    for (int i = 0; i &lt; 3; i++) {
        BTreeNode *found = search_btree(root, search_values[i]);
        printf("Search %d: %s\n", search_values[i], 
               found ? "Found" : "Not found");
    }

    return 0;
}

Practical Examples

File System Directory Tree
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;
#include &lt;stdbool.h&gt;

typedef struct DirectoryNode {
    char name[100];
    bool is_directory;
    long size;  // For files
    struct DirectoryNode *first_child;
    struct DirectoryNode *next_sibling;
} DirectoryNode;

// Create new directory node
DirectoryNode* create_directory_node(const char *name, bool is_dir, long size) {
    DirectoryNode *node = malloc(sizeof(DirectoryNode));
    if (node == NULL) return NULL;

    strncpy(node-&gt;name, name, sizeof(node-&gt;name) - 1);
    node-&gt;name[sizeof(node-&gt;name) - 1] = '\0';
    node-&gt;is_directory = is_dir;
    node-&gt;size = size;
    node-&gt;first_child = NULL;
    node-&gt;next_sibling = NULL;

    return node;
}

// Add child to directory
void add_child(DirectoryNode *parent, DirectoryNode *child) {
    if (parent-&gt;first_child == NULL) {
        parent-&gt;first_child = child;
    } else {
        DirectoryNode *current = parent-&gt;first_child;
        while (current-&gt;next_sibling != NULL) {
            current = current-&gt;next_sibling;
        }
        current-&gt;next_sibling = child;
    }
}

// Print directory tree
void print_directory_tree(DirectoryNode *root, int level) {
    if (root == NULL) return;

    for (int i = 0; i &lt; level; i++) {
        printf("  ");
    }

    if (root-&gt;is_directory) {
        printf("[%s]\n", root-&gt;name);
    } else {
        printf("%s (%ld bytes)\n", root-&gt;name, root-&gt;size);
    }

    // Print children
    DirectoryNode *child = root-&gt;first_child;
    while (child != NULL) {
        print_directory_tree(child, level + 1);
        child = child-&gt;next_sibling;
    }
}

// Calculate directory size
long calculate_directory_size(DirectoryNode *root) {
    if (root == NULL) return 0;

    if (!root-&gt;is_directory) {
        return root-&gt;size;
    }

    long total_size = 0;
    DirectoryNode *child = root-&gt;first_child;
    while (child != NULL) {
        total_size += calculate_directory_size(child);
        child = child-&gt;next_sibling;
    }

    return total_size;
}

// Find file by name
DirectoryNode* find_file(DirectoryNode *root, const char *name) {
    if (root == NULL) return NULL;

    if (strcmp(root-&gt;name, name) == 0) {
        return root;
    }

    // Search in children
    DirectoryNode *child = root-&gt;first_child;
    while (child != NULL) {
        DirectoryNode *found = find_file(child, name);
        if (found != NULL) {
            return found;
        }
        child = child-&gt;next_sibling;
    }

    return NULL;
}

int main() {
    // Create file system structure
    DirectoryNode *root = create_directory_node("root", true, 0);

    // Create directories
    DirectoryNode *home = create_directory_node("home", true, 0);
    DirectoryNode *usr = create_directory_node("usr", true, 0);
    DirectoryNode *john = create_directory_node("john", true, 0);
    DirectoryNode *documents = create_directory_node("documents", true, 0);
    DirectoryNode *pictures = create_directory_node("pictures", true, 0);

    // Create files
    DirectoryNode *file1 = create_directory_node("readme.txt", false, 1024);
    DirectoryNode *file2 = create_directory_node("report.pdf", false, 204800);
    DirectoryNode *file3 = create_directory_node("photo.jpg", false, 512000);
    DirectoryNode *file4 = create_directory_node("vacation.png", false, 1024000);

    // Build tree structure
    add_child(root, home);
    add_child(root, usr);
    add_child(home, john);
    add_child(john, documents);
    add_child(john, pictures);
    add_child(documents, file1);
    add_child(documents, file2);
    add_child(pictures, file3);
    add_child(pictures, file4);

    // Print directory tree
    printf("File System Directory Tree:\n");
    print_directory_tree(root, 0);

    // Calculate sizes
    printf("\nDirectory Sizes:\n");
    printf("Root directory size: %ld bytes\n", calculate_directory_size(root));
    printf("John's directory size: %ld bytes\n", calculate_directory_size(john));
    printf("Documents directory size: %ld bytes\n", calculate_directory_size(documents));

    // Find files
    printf("\nFile Search:\n");
    DirectoryNode *found = find_file(root, "photo.jpg");
    if (found) {
        printf("Found file: %s (%ld bytes)\n", found-&gt;name, found-&gt;size);
    } else {
        printf("File not found\n");
    }

    return 0;
}

Hash Function Design
A good hash function is crucial for the performance of a hash table. It should distribute keys uniformly across the hash table to minimize collisions and ensure efficient operations.

Basic Hash Functions
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;
#include &lt;stdbool.h&gt;

// Simple hash function for integers
unsigned int hash_int(int key, int table_size) {
    return key % table_size;
}

// Simple hash function for strings (djb2 algorithm)
unsigned int hash_string(const char *str, int table_size) {
    unsigned long hash = 5381;
    int c;

    while ((c = *str++)) {
        hash = ((hash &lt;&lt; 5) + hash) + c;  // hash * 33 + c
    }

    return hash % table_size;
}

// Simple hash function for strings (sdbm algorithm)
unsigned int hash_string_sdbm(const char *str, int table_size) {
    unsigned long hash = 0;
    int c;

    while ((c = *str++)) {
        hash = c + (hash &lt;&lt; 6) + (hash &lt;&lt; 16) - hash;
    }

    return hash % table_size;
}

// Universal hash function
unsigned int hash_universal(unsigned int key, int table_size, 
                           unsigned int a, unsigned int b, unsigned int p) {
    // Universal hashing: h(key) = ((a * key + b) mod p) mod table_size
    // where p is a prime number &gt;= table_size
    return ((a * key + b) % p) % table_size;
}

int main() {
    int table_size = 100;

    // Test integer hash function
    printf("Hash values for integers:\n");
    for (int i = 1; i &lt;= 10; i++) {
        printf("Key %d -&gt; Hash %u\n", i, hash_int(i, table_size));
    }

    printf("\nHash values for strings (djb2):\n");
    const char *strings[] = {"hello", "world", "hash", "table", "example"};
    for (int i = 0; i &lt; 5; i++) {
        printf("Key '%s' -&gt; Hash %u\n", strings[i], hash_string(strings[i], table_size));
    }

    printf("\nHash values for strings (sdbm):\n");
    for (int i = 0; i &lt; 5; i++) {
        printf("Key '%s' -&gt; Hash %u\n", strings[i], hash_string_sdbm(strings[i], table_size));
    }

    return 0;
}

Collision Resolution Strategies
When two keys hash to the same index, a collision occurs. There are several strategies to handle collisions:

Chaining
In chaining, each bucket contains a linked list of elements that hash to the same index.
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;
#include &lt;stdbool.h&gt;

#define TABLE_SIZE 10

typedef struct HashNode {
    char key[100];
    int value;
    struct HashNode *next;
} HashNode;

typedef struct {
    HashNode *buckets[TABLE_SIZE];
    int size;
} HashTable;

// Create new hash node
HashNode* create_hash_node(const char *key, int value) {
    HashNode *node = malloc(sizeof(HashNode));
    if (node == NULL) return NULL;

    strncpy(node-&gt;key, key, sizeof(node-&gt;key) - 1);
    node-&gt;key[sizeof(node-&gt;key) - 1] = '\0';
    node-&gt;value = value;
    node-&gt;next = NULL;

    return node;
}

// Initialize hash table
HashTable* create_hash_table(void) {
    HashTable *table = malloc(sizeof(HashTable));
    if (table == NULL) return NULL;

    for (int i = 0; i &lt; TABLE_SIZE; i++) {
        table-&gt;buckets[i] = NULL;
    }

    table-&gt;size = 0;
    return table;
}

// Free hash table
void free_hash_table(HashTable *table) {
    if (table == NULL) return;

    for (int i = 0; i &lt; TABLE_SIZE; i++) {
        HashNode *current = table-&gt;buckets[i];
        while (current != NULL) {
            HashNode *next = current-&gt;next;
            free(current);
            current = next;
        }
    }

    free(table);
}

// Hash function for strings
unsigned int hash(const char *key) {
    unsigned long hash = 5381;
    int c;

    while ((c = *key++)) {
        hash = ((hash &lt;&lt; 5) + hash) + c;
    }

    return hash % TABLE_SIZE;
}

// Insert key-value pair
bool hash_table_insert(HashTable *table, const char *key, int value) {
    if (table == NULL || key == NULL) return false;

    unsigned int index = hash(key);

    // Check if key already exists
    HashNode *current = table-&gt;buckets[index];
    while (current != NULL) {
        if (strcmp(current-&gt;key, key) == 0) {
            current-&gt;value = value;  // Update existing value
            return true;
        }
        current = current-&gt;next;
    }

    // Create new node and insert at beginning of chain
    HashNode *new_node = create_hash_node(key, value);
    if (new_node == NULL) return false;

    new_node-&gt;next = table-&gt;buckets[index];
    table-&gt;buckets[index] = new_node;
    table-&gt;size++;

    return true;
}

// Search for key
bool hash_table_search(HashTable *table, const char *key, int *value) {
    if (table == NULL || key == NULL) return false;

    unsigned int index = hash(key);

    HashNode *current = table-&gt;buckets[index];
    while (current != NULL) {
        if (strcmp(current-&gt;key, key) == 0) {
            if (value != NULL) {
                *value = current-&gt;value;
            }
            return true;
        }
        current = current-&gt;next;
    }

    return false;
}

// Delete key
bool hash_table_delete(HashTable *table, const char *key) {
    if (table == NULL || key == NULL) return false;

    unsigned int index = hash(key);

    HashNode *current = table-&gt;buckets[index];
    HashNode *prev = NULL;

    while (current != NULL) {
        if (strcmp(current-&gt;key, key) == 0) {
            if (prev == NULL) {
                // First node in chain
                table-&gt;buckets[index] = current-&gt;next;
            } else {
                prev-&gt;next = current-&gt;next;
            }

            free(current);
            table-&gt;size--;
            return true;
        }

        prev = current;
        current = current-&gt;next;
    }

    return false;
}

// Print hash table
void print_hash_table(HashTable *table) {
    if (table == NULL) return;

    printf("Hash Table (size: %d):\n", table-&gt;size);
    for (int i = 0; i &lt; TABLE_SIZE; i++) {
        printf("Bucket %d: ", i);

        HashNode *current = table-&gt;buckets[i];
        if (current == NULL) {
            printf("empty\n");
        } else {
            while (current != NULL) {
                printf("(%s: %d) -&gt; ", current-&gt;key, current-&gt;value);
                current = current-&gt;next;
            }
            printf("NULL\n");
        }
    }
}

int main() {
    HashTable *table = create_hash_table();
    if (table == NULL) {
        printf("Failed to create hash table\n");
        return 1;
    }

    // Insert key-value pairs
    hash_table_insert(table, "apple", 5);
    hash_table_insert(table, "banana", 3);
    hash_table_insert(table, "orange", 8);
    hash_table_insert(table, "grape", 12);
    hash_table_insert(table, "kiwi", 7);

    print_hash_table(table);

    // Search for keys
    int value;
    if (hash_table_search(table, "apple", &value)) {
        printf("Found 'apple': %d\n", value);
    }

    if (hash_table_search(table, "mango", &value)) {
        printf("Found 'mango': %d\n", value);
    } else {
        printf("'mango' not found\n");
    }

    // Update existing key
    hash_table_insert(table, "apple", 10);
    printf("After updating 'apple':\n");
    if (hash_table_search(table, "apple", &value)) {
        printf("Found 'apple': %d\n", value);
    }

    // Delete key
    if (hash_table_delete(table, "banana")) {
        printf("Deleted 'banana'\n");
    }

    print_hash_table(table);

    free_hash_table(table);
    return 0;
}


Open Addressing
In open addressing, all elements are stored in the hash table itself. When a collision occurs, alternative slots are probed until an empty slot is found.
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;
#include &lt;stdbool.h&gt;

#define TABLE_SIZE 13
#define EMPTY_CELL -1
#define DELETED_CELL -2

typedef struct {
    char key[100];
    int value;
    int status;  // EMPTY_CELL, DELETED_CELL, or occupied
} HashEntry;

typedef struct {
    HashEntry entries[TABLE_SIZE];
    int size;
} OpenHashTable;

// Initialize open hash table
OpenHashTable* create_open_hash_table(void) {
    OpenHashTable *table = malloc(sizeof(OpenHashTable));
    if (table == NULL) return NULL;

    for (int i = 0; i &lt; TABLE_SIZE; i++) {
        table-&gt;entries[i].status = EMPTY_CELL;
    }

    table-&gt;size = 0;
    return table;
}

// Free open hash table
void free_open_hash_table(OpenHashTable *table) {
    free(table);
}

// Hash function
unsigned int hash_open(const char *key) {
    unsigned long hash = 5381;
    int c;

    while ((c = *key++)) {
        hash = ((hash &lt;&lt; 5) + hash) + c;
    }

    return hash % TABLE_SIZE;
}

// Linear probing hash function
unsigned int hash_linear_probe(const char *key, int attempt) {
    return (hash_open(key) + attempt) % TABLE_SIZE;
}

// Quadratic probing hash function
unsigned int hash_quadratic_probe(const char *key, int attempt) {
    return (hash_open(key) + attempt * attempt) % TABLE_SIZE;
}

// Double hashing
unsigned int hash_double(const char *key, int attempt) {
    unsigned int hash1 = hash_open(key);
    unsigned int hash2 = 7 - (hash_open(key) % 7);  // Second hash function
    return (hash1 + attempt * hash2) % TABLE_SIZE;
}

// Insert with linear probing
bool open_hash_table_insert(OpenHashTable *table, const char *key, int value) {
    if (table == NULL || key == NULL) return false;

    int attempt = 0;
    unsigned int index;

    do {
        index = hash_linear_probe(key, attempt);

        if (table-&gt;entries[index].status == EMPTY_CELL || 
            table-&gt;entries[index].status == DELETED_CELL) {
            // Found empty or deleted slot
            strncpy(table-&gt;entries[index].key, key, sizeof(table-&gt;entries[index].key) - 1);
            table-&gt;entries[index].key[sizeof(table-&gt;entries[index].key) - 1] = '\0';
            table-&gt;entries[index].value = value;
            table-&gt;entries[index].status = 0;  // Occupied
            table-&gt;size++;
            return true;
        } else if (strcmp(table-&gt;entries[index].key, key) == 0) {
            // Key already exists, update value
            table-&gt;entries[index].value = value;
            return true;
        }

        attempt++;
    } while (attempt &lt; TABLE_SIZE);

    // Hash table is full
    return false;
}

// Search with linear probing
bool open_hash_table_search(OpenHashTable *table, const char *key, int *value) {
    if (table == NULL || key == NULL) return false;

    int attempt = 0;
    unsigned int index;

    do {
        index = hash_linear_probe(key, attempt);

        if (table-&gt;entries[index].status == EMPTY_CELL) {
            // Key not found
            return false;
        } else if (table-&gt;entries[index].status != DELETED_CELL && 
                   strcmp(table-&gt;entries[index].key, key) == 0) {
            // Key found
            if (value != NULL) {
                *value = table-&gt;entries[index].value;
            }
            return true;
        }

        attempt++;
    } while (attempt &lt; TABLE_SIZE);

    // Key not found
    return false;
}

// Delete with linear probing
bool open_hash_table_delete(OpenHashTable *table, const char *key) {
    if (table == NULL || key == NULL) return false;

    int attempt = 0;
    unsigned int index;

    do {
        index = hash_linear_probe(key, attempt);

        if (table-&gt;entries[index].status == EMPTY_CELL) {
            // Key not found
            return false;
        } else if (table-&gt;entries[index].status != DELETED_CELL && 
                   strcmp(table-&gt;entries[index].key, key) == 0) {
            // Key found, mark as deleted
            table-&gt;entries[index].status = DELETED_CELL;
            table-&gt;size--;
            return true;
        }

        attempt++;
    } while (attempt &lt; TABLE_SIZE);

    // Key not found
    return false;
}

// Print open hash table
void print_open_hash_table(OpenHashTable *table) {
    if (table == NULL) return;

    printf("Open Hash Table (size: %d):\n", table-&gt;size);
    for (int i = 0; i &lt; TABLE_SIZE; i++) {
        printf("Index %d: ", i);
        if (table-&gt;entries[i].status == EMPTY_CELL) {
            printf("EMPTY\n");
        } else if (table-&gt;entries[i].status == DELETED_CELL) {
            printf("DELETED\n");
        } else {
            printf("(%s: %d)\n", table-&gt;entries[i].key, table-&gt;entries[i].value);
        }
    }
}

int main() {
    OpenHashTable *table = create_open_hash_table();
    if (table == NULL) {
        printf("Failed to create hash table\n");
        return 1;
    }

    // Insert key-value pairs
    open_hash_table_insert(table, "apple", 5);
    open_hash_table_insert(table, "banana", 3);
    open_hash_table_insert(table, "orange", 8);
    open_hash_table_insert(table, "grape", 12);
    open_hash_table_insert(table, "kiwi", 7);

    print_open_hash_table(table);

    // Search for keys
    int value;
    if (open_hash_table_search(table, "apple", &value)) {
        printf("Found 'apple': %d\n", value);
    }

    if (open_hash_table_search(table, "mango", &value)) {
        printf("Found 'mango': %d\n", value);
    } else {
        printf("'mango' not found\n");
    }

    // Update existing key
    open_hash_table_insert(table, "apple", 10);
    printf("After updating 'apple':\n");
    if (open_hash_table_search(table, "apple", &value)) {
        printf("Found 'apple': %d\n", value);
    }

    // Delete key
    if (open_hash_table_delete(table, "banana")) {
        printf("Deleted 'banana'\n");
    }

    print_open_hash_table(table);

    free_open_hash_table(table);
    return 0;
}

Dynamic Hash Tables
Dynamic hash tables can resize themselves when the load factor becomes too high, ensuring efficient performance.

Resizable Hash Table with Chaining
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;
#include &lt;stdbool.h&gt;

#define INITIAL_SIZE 8
#define LOAD_FACTOR_THRESHOLD 0.75

typedef struct DynamicHashNode {
    char key[100];
    int value;
    struct DynamicHashNode *next;
} DynamicHashNode;

typedef struct {
    DynamicHashNode **buckets;
    int size;
    int capacity;
} DynamicHashTable;

// Create new hash node
DynamicHashNode* create_dynamic_hash_node(const char *key, int value) {
    DynamicHashNode *node = malloc(sizeof(DynamicHashNode));
    if (node == NULL) return NULL;

    strncpy(node-&gt;key, key, sizeof(node-&gt;key) - 1);
    node-&gt;key[sizeof(node-&gt;key) - 1] = '\0';
    node-&gt;value = value;
    node-&gt;next = NULL;

    return node;
}

// Initialize dynamic hash table
DynamicHashTable* create_dynamic_hash_table(void) {
    DynamicHashTable *table = malloc(sizeof(DynamicHashTable));
    if (table == NULL) return NULL;

    table-&gt;buckets = calloc(INITIAL_SIZE, sizeof(DynamicHashNode*));
    if (table-&gt;buckets == NULL) {
        free(table);
        return NULL;
    }

    table-&gt;size = 0;
    table-&gt;capacity = INITIAL_SIZE;
    return table;
}

// Free dynamic hash table
void free_dynamic_hash_table(DynamicHashTable *table) {
    if (table == NULL) return;

    for (int i = 0; i &lt; table-&gt;capacity; i++) {
        DynamicHashNode *current = table-&gt;buckets[i];
        while (current != NULL) {
            DynamicHashNode *next = current-&gt;next;
            free(current);
            current = next;
        }
    }

    free(table-&gt;buckets);
    free(table);
}

// Hash function
unsigned int dynamic_hash(const char *key, int capacity) {
    unsigned long hash = 5381;
    int c;

    while ((c = *key++)) {
        hash = ((hash &lt;&lt; 5) + hash) + c;
    }

    return hash % capacity;
}

// Resize hash table
bool resize_hash_table(DynamicHashTable *table) {
    int old_capacity = table-&gt;capacity;
    int new_capacity = old_capacity * 2;

    DynamicHashNode **old_buckets = table-&gt;buckets;
    DynamicHashNode **new_buckets = calloc(new_capacity, sizeof(DynamicHashNode*));
    if (new_buckets == NULL) return false;

    table-&gt;buckets = new_buckets;
    table-&gt;capacity = new_capacity;

    // Rehash all elements
    for (int i = 0; i &lt; old_capacity; i++) {
        DynamicHashNode *current = old_buckets[i];
        while (current != NULL) {
            DynamicHashNode *next = current-&gt;next;

            unsigned int new_index = dynamic_hash(current-&gt;key, new_capacity);
            current-&gt;next = table-&gt;buckets[new_index];
            table-&gt;buckets[new_index] = current;

            current = next;
        }
    }

    free(old_buckets);
    return true;
}

// Insert key-value pair
bool dynamic_hash_table_insert(DynamicHashTable *table, const char *key, int value) {
    if (table == NULL || key == NULL) return false;

    // Check if resize is needed
    double load_factor = (double)table-&gt;size / table-&gt;capacity;
    if (load_factor &gt; LOAD_FACTOR_THRESHOLD) {
        if (!resize_hash_table(table)) {
            return false;
        }
    }

    unsigned int index = dynamic_hash(key, table-&gt;capacity);

    // Check if key already exists
    DynamicHashNode *current = table-&gt;buckets[index];
    while (current != NULL) {
        if (strcmp(current-&gt;key, key) == 0) {
            current-&gt;value = value;  // Update existing value
            return true;
        }
        current = current-&gt;next;
    }

    // Create new node and insert at beginning of chain
    DynamicHashNode *new_node = create_dynamic_hash_node(key, value);
    if (new_node == NULL) return false;

    new_node-&gt;next = table-&gt;buckets[index];
    table-&gt;buckets[index] = new_node;
    table-&gt;size++;

    return true;
}

// Search for key
bool dynamic_hash_table_search(DynamicHashTable *table, const char *key, int *value) {
    if (table == NULL || key == NULL) return false;

    unsigned int index = dynamic_hash(key, table-&gt;capacity);

    DynamicHashNode *current = table-&gt;buckets[index];
    while (current != NULL) {
        if (strcmp(current-&gt;key, key) == 0) {
            if (value != NULL) {
                *value = current-&gt;value;
            }
            return true;
        }
        current = current-&gt;next;
    }

    return false;
}

// Delete key
bool dynamic_hash_table_delete(DynamicHashTable *table, const char *key) {
    if (table == NULL || key == NULL) return false;

    unsigned int index = dynamic_hash(key, table-&gt;capacity);

    DynamicHashNode *current = table-&gt;buckets[index];
    DynamicHashNode *prev = NULL;

    while (current != NULL) {
        if (strcmp(current-&gt;key, key) == 0) {
            if (prev == NULL) {
                // First node in chain
                table-&gt;buckets[index] = current-&gt;next;
            } else {
                prev-&gt;next = current-&gt;next;
            }

            free(current);
            table-&gt;size--;
            return true;
        }

        prev = current;
        current = current-&gt;next;
    }

    return false;
}

// Print dynamic hash table
void print_dynamic_hash_table(DynamicHashTable *table) {
    if (table == NULL) return;

    printf("Dynamic Hash Table (size: %d, capacity: %d, load factor: %.2f):\n", 
           table-&gt;size, table-&gt;capacity, (double)table-&gt;size / table-&gt;capacity);

    for (int i = 0; i &lt; table-&gt;capacity; i++) {
        printf("Bucket %d: ", i);

        DynamicHashNode *current = table-&gt;buckets[i];
        if (current == NULL) {
            printf("empty\n");
        } else {
            while (current != NULL) {
                printf("(%s: %d) -&gt; ", current-&gt;key, current-&gt;value);
                current = current-&gt;next;
            }
            printf("NULL\n");
        }
    }
}

int main() {
    DynamicHashTable *table = create_dynamic_hash_table();
    if (table == NULL) {
        printf("Failed to create hash table\n");
        return 1;
    }

    // Insert many key-value pairs to trigger resizing
    char key[20];
    for (int i = 0; i &lt; 20; i++) {
        sprintf(key, "key%d", i);
        dynamic_hash_table_insert(table, key, i * 10);

        // Print status periodically
        if (i % 5 == 4) {
            printf("After inserting %d elements:\n", i + 1);
            print_dynamic_hash_table(table);
            printf("\n");
        }
    }

    // Search for some keys
    int value;
    if (dynamic_hash_table_search(table, "key5", &value)) {
        printf("Found 'key5': %d\n", value);
    }

    if (dynamic_hash_table_search(table, "key15", &value)) {
        printf("Found 'key15': %d\n", value);
    }

    // Delete some keys
    if (dynamic_hash_table_delete(table, "key10")) {
        printf("Deleted 'key10'\n");
    }

    printf("Final hash table:\n");
    print_dynamic_hash_table(table);

    free_dynamic_hash_table(table);
    return 0;
}

Hash Table Performance Analysis

Load Factor and Performance
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;
#include &lt;time.h&gt;

#define TABLE_SIZE 1000

typedef struct PerfNode {
    int key;
    int value;
    struct PerfNode *next;
} PerfNode;

typedef struct {
    PerfNode *buckets[TABLE_SIZE];
    int size;
} PerfHashTable;

// Create performance hash table
PerfHashTable* create_perf_hash_table(void) {
    PerfHashTable *table = malloc(sizeof(PerfHashTable));
    if (table == NULL) return NULL;

    for (int i = 0; i &lt; TABLE_SIZE; i++) {
        table-&gt;buckets[i] = NULL;
    }

    table-&gt;size = 0;
    return table;
}

// Free performance hash table
void free_perf_hash_table(PerfHashTable *table) {
    if (table == NULL) return;

    for (int i = 0; i &lt; TABLE_SIZE; i++) {
        PerfNode *current = table-&gt;buckets[i];
        while (current != NULL) {
            PerfNode *next = current-&gt;next;
            free(current);
            current = next;
        }
    }

    free(table);
}

// Hash function
unsigned int perf_hash(int key) {
    return key % TABLE_SIZE;
}

// Insert with performance measurement
bool perf_hash_table_insert(PerfHashTable *table, int key, int value) {
    if (table == NULL) return false;

    unsigned int index = perf_hash(key);

    PerfNode *new_node = malloc(sizeof(PerfNode));
    if (new_node == NULL) return false;

    new_node-&gt;key = key;
    new_node-&gt;value = value;
    new_node-&gt;next = table-&gt;buckets[index];
    table-&gt;buckets[index] = new_node;
    table-&gt;size++;

    return true;
}

// Calculate average chain length
double calculate_average_chain_length(PerfHashTable *table) {
    if (table == NULL) return 0.0;

    int total_length = 0;
    int non_empty_buckets = 0;

    for (int i = 0; i &lt; TABLE_SIZE; i++) {
        if (table-&gt;buckets[i] != NULL) {
            non_empty_buckets++;
            int length = 0;
            PerfNode *current = table-&gt;buckets[i];
            while (current != NULL) {
                length++;
                current = current-&gt;next;
            }
            total_length += length;
        }
    }

    return non_empty_buckets &gt; 0 ? (double)total_length / non_empty_buckets : 0.0;
}

// Calculate load factor
double calculate_load_factor(PerfHashTable *table) {
    if (table == NULL) return 0.0;
    return (double)table-&gt;size / TABLE_SIZE;
}

// Find maximum chain length
int find_max_chain_length(PerfHashTable *table) {
    if (table == NULL) return 0;

    int max_length = 0;

    for (int i = 0; i &lt; TABLE_SIZE; i++) {
        int length = 0;
        PerfNode *current = table-&gt;buckets[i];
        while (current != NULL) {
            length++;
            current = current-&gt;next;
        }
        if (length &gt; max_length) {
            max_length = length;
        }
    }

    return max_length;
}

int main() {
    PerfHashTable *table = create_perf_hash_table();
    if (table == NULL) {
        printf("Failed to create hash table\n");
        return 1;
    }

    // Insert elements with different patterns
    printf("Performance Analysis of Hash Table:\n");
    printf("====================================\n\n");

    // Pattern 1: Sequential keys
    printf("Inserting 500 sequential keys (0-499):\n");
    clock_t start = clock();
    for (int i = 0; i &lt; 500; i++) {
        perf_hash_table_insert(table, i, i * 2);
    }
    clock_t end = clock();

    printf("Time taken: %f seconds\n", ((double)(end - start)) / CLOCKS_PER_SEC);
    printf("Load factor: %.2f\n", calculate_load_factor(table));
    printf("Average chain length: %.2f\n", calculate_average_chain_length(table));
    printf("Maximum chain length: %d\n\n", find_max_chain_length(table));

    // Pattern 2: Random keys
    printf("Inserting 500 random keys:\n");
    srand(42);  // Fixed seed for reproducibility
    start = clock();
    for (int i = 0; i &lt; 500; i++) {
        int random_key = rand() % 10000;
        perf_hash_table_insert(table, random_key, random_key * 2);
    }
    end = clock();

    printf("Time taken: %f seconds\n", ((double)(end - start)) / CLOCKS_PER_SEC);
    printf("Load factor: %.2f\n", calculate_load_factor(table));
    printf("Average chain length: %.2f\n", calculate_average_chain_length(table));
    printf("Maximum chain length: %d\n\n", find_max_chain_length(table));

    free_perf_hash_table(table);
    return 0;
}

Practical Examples

Symbol Table Implementation
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;
#include &lt;stdbool.h&gt;

#define SYMBOL_TABLE_SIZE 101

typedef enum {
    TYPE_INT,
    TYPE_FLOAT,
    TYPE_STRING,
    TYPE_FUNCTION
} SymbolType;

typedef struct Symbol {
    char name[100];
    SymbolType type;
    union {
        int int_val;
        float float_val;
        char *string_val;
        void (*func_ptr)(void);
    } value;
    struct Symbol *next;
} Symbol;

typedef struct {
    Symbol *buckets[SYMBOL_TABLE_SIZE];
} SymbolTable;

// Create symbol table
SymbolTable* create_symbol_table(void) {
    SymbolTable *table = malloc(sizeof(SymbolTable));
    if (table == NULL) return NULL;

    for (int i = 0; i &lt; SYMBOL_TABLE_SIZE; i++) {
        table-&gt;buckets[i] = NULL;
    }

    return table;
}

// Free symbol table
void free_symbol_table(SymbolTable *table) {
    if (table == NULL) return;

    for (int i = 0; i &lt; SYMBOL_TABLE_SIZE; i++) {
        Symbol *current = table-&gt;buckets[i];
        while (current != NULL) {
            Symbol *next = current-&gt;next;
            if (current-&gt;type == TYPE_STRING) {
                free(current-&gt;value.string_val);
            }
            free(current);
            current = next;
        }
    }

    free(table);
}

// Hash function for symbol names
unsigned int symbol_hash(const char *name) {
    unsigned long hash = 5381;
    int c;

    while ((c = *name++)) {
        hash = ((hash &lt;&lt; 5) + hash) + c;
    }

    return hash % SYMBOL_TABLE_SIZE;
}

// Add integer symbol
bool add_integer_symbol(SymbolTable *table, const char *name, int value) {
    if (table == NULL || name == NULL) return false;

    unsigned int index = symbol_hash(name);

    Symbol *new_symbol = malloc(sizeof(Symbol));
    if (new_symbol == NULL) return false;

    strncpy(new_symbol-&gt;name, name, sizeof(new_symbol-&gt;name) - 1);
    new_symbol-&gt;name[sizeof(new_symbol-&gt;name) - 1] = '\0';
    new_symbol-&gt;type = TYPE_INT;
    new_symbol-&gt;value.int_val = value;
    new_symbol-&gt;next = table-&gt;buckets[index];
    table-&gt;buckets[index] = new_symbol;

    return true;
}

// Add float symbol
bool add_float_symbol(SymbolTable *table, const char *name, float value) {
    if (table == NULL || name == NULL) return false;

    unsigned int index = symbol_hash(name);

    Symbol *new_symbol = malloc(sizeof(Symbol));
    if (new_symbol == NULL) return false;

    strncpy(new_symbol-&gt;name, name, sizeof(new_symbol-&gt;name) - 1);
    new_symbol-&gt;name[sizeof(new_symbol-&gt;name) - 1] = '\0';
    new_symbol-&gt;type = TYPE_FLOAT;
    new_symbol-&gt;value.float_val = value;
    new_symbol-&gt;next = table-&gt;buckets[index];
    table-&gt;buckets[index] = new_symbol;

    return true;
}

// Add string symbol
bool add_string_symbol(SymbolTable *table, const char *name, const char *value) {
    if (table == NULL || name == NULL || value == NULL) return false;

    unsigned int index = symbol_hash(name);

    Symbol *new_symbol = malloc(sizeof(Symbol));
    if (new_symbol == NULL) return false;

    strncpy(new_symbol-&gt;name, name, sizeof(new_symbol-&gt;name) - 1);
    new_symbol-&gt;name[sizeof(new_symbol-&gt;name) - 1] = '\0';
    new_symbol-&gt;type = TYPE_STRING;
    new_symbol-&gt;value.string_val = malloc(strlen(value) + 1);
    if (new_symbol-&gt;value.string_val == NULL) {
        free(new_symbol);
        return false;
    }
    strcpy(new_symbol-&gt;value.string_val, value);
    new_symbol-&gt;next = table-&gt;buckets[index];
    table-&gt;buckets[index] = new_symbol;

    return true;
}

// Lookup symbol
Symbol* lookup_symbol(SymbolTable *table, const char *name) {
    if (table == NULL || name == NULL) return NULL;

    unsigned int index = symbol_hash(name);

    Symbol *current = table-&gt;buckets[index];
    while (current != NULL) {
        if (strcmp(current-&gt;name, name) == 0) {
            return current;
        }
        current = current-&gt;next;
    }

    return NULL;
}

// Print symbol table
void print_symbol_table(SymbolTable *table) {
    if (table == NULL) return;

    printf("Symbol Table:\n");
    printf("=============\n");

    for (int i = 0; i &lt; SYMBOL_TABLE_SIZE; i++) {
        Symbol *current = table-&gt;buckets[i];
        while (current != NULL) {
            printf("Name: %-15s Type: ", current-&gt;name);

            switch (current-&gt;type) {
                case TYPE_INT:
                    printf("int     Value: %d\n", current-&gt;value.int_val);
                    break;
                case TYPE_FLOAT:
                    printf("float   Value: %.2f\n", current-&gt;value.float_val);
                    break;
                case TYPE_STRING:
                    printf("string  Value: %s\n", current-&gt;value.string_val);
                    break;
                case TYPE_FUNCTION:
                    printf("function\n");
                    break;
            }

            current = current-&gt;next;
        }
    }
}

int main() {
    SymbolTable *table = create_symbol_table();
    if (table == NULL) {
        printf("Failed to create symbol table\n");
        return 1;
    }

    // Add various symbols
    add_integer_symbol(table, "count", 42);
    add_integer_symbol(table, "max_size", 1000);
    add_float_symbol(table, "pi", 3.14159f);
    add_float_symbol(table, "e", 2.71828f);
    add_string_symbol(table, "name", "John Doe");
