Cache Implementation
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;
#include &lt;stdbool.h&gt;
#include &lt;time.h&gt;

#define CACHE_SIZE 16
#define MAX_KEY_LENGTH 100
#define MAX_VALUE_LENGTH 1000

typedef struct CacheNode {
    char key[MAX_KEY_LENGTH];
    char value[MAX_VALUE_LENGTH];
    time_t timestamp;
    int access_count;
    struct CacheNode *next;
} CacheNode;

typedef struct {
    CacheNode *buckets[CACHE_SIZE];
    int size;
    int max_size;
} LRUCache;

// Create LRU cache
LRUCache* create_lru_cache(int max_size) {
    LRUCache *cache = malloc(sizeof(LRUCache));
    if (cache == NULL) return NULL;

    for (int i = 0; i &lt; CACHE_SIZE; i++) {
        cache-&gt;buckets[i] = NULL;
    }

    cache-&gt;size = 0;
    cache-&gt;max_size = max_size;
    return cache;
}

// Free LRU cache
void free_lru_cache(LRUCache *cache) {
    if (cache == NULL) return;

    for (int i = 0; i &lt; CACHE_SIZE; i++) {
        CacheNode *current = cache-&gt;buckets[i];
        while (current != NULL) {
            CacheNode *next = current-&gt;next;
            free(current);
            current = next;
        }
    }

    free(cache);
}

// Hash function
unsigned int cache_hash(const char *key) {
    unsigned long hash = 5381;
    int c;

    while ((c = *key++)) {
        hash = ((hash &lt;&lt; 5) + hash) + c;
    }

    return hash % CACHE_SIZE;
}

// Remove least recently used item
void remove_lru_item(LRUCache *cache) {
    if (cache == NULL || cache-&gt;size == 0) return;

    time_t oldest_time = time(NULL);
    CacheNode *oldest_node = NULL;
    int oldest_bucket = -1;
    CacheNode *oldest_prev = NULL;

    // Find the oldest accessed item
    for (int i = 0; i &lt; CACHE_SIZE; i++) {
        CacheNode *current = cache-&gt;buckets[i];
        CacheNode *prev = NULL;

        while (current != NULL) {
            if (current-&gt;timestamp &lt; oldest_time) {
                oldest_time = current-&gt;timestamp;
                oldest_node = current;
                oldest_bucket = i;
                oldest_prev = prev;
            }
            prev = current;
            current = current-&gt;next;
        }
    }

    // Remove the oldest item
    if (oldest_node != NULL) {
        if (oldest_prev == NULL) {
            cache-&gt;buckets[oldest_bucket] = oldest_node-&gt;next;
        } else {
            oldest_prev-&gt;next = oldest_node-&gt;next;
        }
        free(oldest_node);
        cache-&gt;size--;
    }
}

// Put item in cache
bool cache_put(LRUCache *cache, const char *key, const char *value) {
    if (cache == NULL || key == NULL || value == NULL) return false;

    // Check if key already exists
    unsigned int index = cache_hash(key);
    CacheNode *current = cache-&gt;buckets[index];
    CacheNode *prev = NULL;

    while (current != NULL) {
        if (strcmp(current-&gt;key, key) == 0) {
            // Update existing item
            strncpy(current-&gt;value, value, MAX_VALUE_LENGTH - 1);
            current-&gt;value[MAX_VALUE_LENGTH - 1] = '\0';
            current-&gt;timestamp = time(NULL);
            current-&gt;access_count++;
            return true;
        }
        prev = current;
        current = current-&gt;next;
    }

    // Check if cache is full
    if (cache-&gt;size &gt;= cache-&gt;max_size) {
        remove_lru_item(cache);
    }

    // Create new cache node
    CacheNode *new_node = malloc(sizeof(CacheNode));
    if (new_node == NULL) return false;

    strncpy(new_node-&gt;key, key, MAX_KEY_LENGTH - 1);
    new_node-&gt;key[MAX_KEY_LENGTH - 1] = '\0';
    strncpy(new_node-&gt;value, value, MAX_VALUE_LENGTH - 1);
    new_node-&gt;value[MAX_VALUE_LENGTH - 1] = '\0';
    new_node-&gt;timestamp = time(NULL);
    new_node-&gt;access_count = 1;
    new_node-&gt;next = cache-&gt;buckets[index];
    cache-&gt;buckets[index] = new_node;
    cache-&gt;size++;

    return true;
}

// Get item from cache
bool cache_get(LRUCache *cache, const char *key, char *value, size_t value_size) {
    if (cache == NULL || key == NULL || value == NULL) return false;

    unsigned int index = cache_hash(key);
    CacheNode *current = cache-&gt;buckets[index];

    while (current != NULL) {
        if (strcmp(current-&gt;key, key) == 0) {
            // Found item, update timestamp and access count
            strncpy(value, current-&gt;value, value_size - 1);
            value[value_size - 1] = '\0';
            current-&gt;timestamp = time(NULL);
            current-&gt;access_count++;
            return true;
        }
        current = current-&gt;next;
    }

    return false;
}

// Print cache statistics
void print_cache_stats(LRUCache *cache) {
    if (cache == NULL) return;

    printf("Cache Statistics:\n");
    printf("  Size: %d/%d\n", cache-&gt;size, cache-&gt;max_size);
    printf("  Buckets:\n");

    for (int i = 0; i &lt; CACHE_SIZE; i++) {
        CacheNode *current = cache-&gt;buckets[i];
        if (current != NULL) {
            printf("    Bucket %d:\n", i);
            while (current != NULL) {
                printf("      Key: %-15s Value: %-20s Accesses: %d\n", 
                       current-&gt;key, current-&gt;value, current-&gt;access_count);
                current = current-&gt;next;
            }
        }
    }
}

int main() {
    LRUCache *cache = create_lru_cache(5);
    if (cache == NULL) {
        printf("Failed to create cache\n");
        return 1;
    }

    // Add items to cache
    cache_put(cache, "user1", "John Doe");
    cache_put(cache, "user2", "Jane Smith");
    cache_put(cache, "config", "debug=true");
    cache_put(cache, "version", "1.2.3");
    cache_put(cache, "theme", "dark");

    printf("Initial cache state:\n");
    print_cache_stats(cache);

    // Access some items
    char value[100];
    if (cache_get(cache, "user1", value, sizeof(value))) {
        printf("\nRetrieved 'user1': %s\n", value);
    }

    if (cache_get(cache, "config", value, sizeof(value))) {
        printf("Retrieved 'config': %s\n", value);
    }

    // Add more items to trigger LRU eviction
    cache_put(cache, "new_item1", "value1");
    cache_put(cache, "new_item2", "value2");

    printf("\nCache after adding new items:\n");
    print_cache_stats(cache);

    // Try to access evicted item
    if (cache_get(cache, "user2", value, sizeof(value))) {
        printf("\nRetrieved 'user2': %s\n", value);
    } else {
        printf("\n'user2' was evicted from cache\n");
    }

    free_lru_cache(cache);
    return 0;
}

Graph Representations
Graphs can be represented in several ways, each with its own advantages and disadvantages.

Adjacency Matrix
An adjacency matrix is a 2D array where the cell at position (i, j) indicates whether there is an edge from vertex i to vertex j.
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;stdbool.h&gt;
#include &lt;limits.h&gt;

#define MAX_VERTICES 100

typedef struct {
    int vertices;
    int matrix[MAX_VERTICES][MAX_VERTICES];
} AdjMatrixGraph;

// Create adjacency matrix graph
AdjMatrixGraph* create_adj_matrix_graph(int vertices) {
    AdjMatrixGraph *graph = malloc(sizeof(AdjMatrixGraph));
    if (graph == NULL) return NULL;

    graph-&gt;vertices = vertices;

    // Initialize matrix with 0s (no edges)
    for (int i = 0; i &lt; vertices; i++) {
        for (int j = 0; j &lt; vertices; j++) {
            graph-&gt;matrix[i][j] = 0;
        }
    }

    return graph;
}

// Add edge to adjacency matrix graph
void add_edge_matrix(AdjMatrixGraph *graph, int src, int dest, int weight) {
    if (graph == NULL || src &lt; 0 || src &gt;= graph-&gt;vertices || 
        dest &lt; 0 || dest &gt;= graph-&gt;vertices) {
        return;
    }

    graph-&gt;matrix[src][dest] = weight;
    // For undirected graph, also add reverse edge
    graph-&gt;matrix[dest][src] = weight;
}

// Remove edge from adjacency matrix graph
void remove_edge_matrix(AdjMatrixGraph *graph, int src, int dest) {
    if (graph == NULL || src &lt; 0 || src &gt;= graph-&gt;vertices || 
        dest &lt; 0 || dest &gt;= graph-&gt;vertices) {
        return;
    }

    graph-&gt;matrix[src][dest] = 0;
    graph-&gt;matrix[dest][src] = 0;
}

// Check if edge exists
bool has_edge_matrix(AdjMatrixGraph *graph, int src, int dest) {
    if (graph == NULL || src &lt; 0 || src &gt;= graph-&gt;vertices || 
        dest &lt; 0 || dest &gt;= graph-&gt;vertices) {
        return false;
    }

    return graph-&gt;matrix[src][dest] != 0;
}

// Print adjacency matrix
void print_adj_matrix(AdjMatrixGraph *graph) {
    if (graph == NULL) return;

    printf("Adjacency Matrix:\n");
    printf("    ");
    for (int i = 0; i &lt; graph-&gt;vertices; i++) {
        printf("%3d", i);
    }
    printf("\n");

    for (int i = 0; i &lt; graph-&gt;vertices; i++) {
        printf("%3d ", i);
        for (int j = 0; j &lt; graph-&gt;vertices; j++) {
            printf("%3d", graph-&gt;matrix[i][j]);
        }
        printf("\n");
    }
}

int main() {
    AdjMatrixGraph *graph = create_adj_matrix_graph(5);
    if (graph == NULL) {
        printf("Failed to create graph\n");
        return 1;
    }

    // Add edges
    add_edge_matrix(graph, 0, 1, 1);
    add_edge_matrix(graph, 0, 4, 1);
    add_edge_matrix(graph, 1, 2, 1);
    add_edge_matrix(graph, 1, 3, 1);
    add_edge_matrix(graph, 1, 4, 1);
    add_edge_matrix(graph, 2, 3, 1);
    add_edge_matrix(graph, 3, 4, 1);

    print_adj_matrix(graph);

    printf("\nEdge checks:\n");
    printf("Edge (0,1): %s\n", has_edge_matrix(graph, 0, 1) ? "Yes" : "No");
    printf("Edge (0,2): %s\n", has_edge_matrix(graph, 0, 2) ? "Yes" : "No");

    free(graph);
    return 0;
}


Adjacency List
An adjacency list represents a graph as an array of lists, where each list contains the neighbors of a vertex.
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;stdbool.h&gt;

#define MAX_VERTICES 100

typedef struct AdjListNode {
    int vertex;
    int weight;
    struct AdjListNode *next;
} AdjListNode;

typedef struct {
    int vertices;
    AdjListNode *adj_list[MAX_VERTICES];
} AdjListGraph;

// Create new adjacency list node
AdjListNode* create_adj_list_node(int vertex, int weight) {
    AdjListNode *node = malloc(sizeof(AdjListNode));
    if (node == NULL) return NULL;

    node-&gt;vertex = vertex;
    node-&gt;weight = weight;
    node-&gt;next = NULL;
    return node;
}

// Create adjacency list graph
AdjListGraph* create_adj_list_graph(int vertices) {
    AdjListGraph *graph = malloc(sizeof(AdjListGraph));
    if (graph == NULL) return NULL;

    graph-&gt;vertices = vertices;

    // Initialize adjacency lists
    for (int i = 0; i &lt; vertices; i++) {
        graph-&gt;adj_list[i] = NULL;
    }

    return graph;
}

// Free adjacency list graph
void free_adj_list_graph(AdjListGraph *graph) {
    if (graph == NULL) return;

    for (int i = 0; i &lt; graph-&gt;vertices; i++) {
        AdjListNode *current = graph-&gt;adj_list[i];
        while (current != NULL) {
            AdjListNode *next = current-&gt;next;
            free(current);
            current = next;
        }
    }

    free(graph);
}

// Add edge to adjacency list graph
void add_edge_list(AdjListGraph *graph, int src, int dest, int weight) {
    if (graph == NULL || src &lt; 0 || src &gt;= graph-&gt;vertices || 
        dest &lt; 0 || dest &gt;= graph-&gt;vertices) {
        return;
    }

    // Add edge from src to dest
    AdjListNode *new_node = create_adj_list_node(dest, weight);
    new_node-&gt;next = graph-&gt;adj_list[src];
    graph-&gt;adj_list[src] = new_node;

    // For undirected graph, also add reverse edge
    new_node = create_adj_list_node(src, weight);
    new_node-&gt;next = graph-&gt;adj_list[dest];
    graph-&gt;adj_list[dest] = new_node;
}

// Remove edge from adjacency list graph
void remove_edge_list(AdjListGraph *graph, int src, int dest) {
    if (graph == NULL || src &lt; 0 || src &gt;= graph-&gt;vertices || 
        dest &lt; 0 || dest &gt;= graph-&gt;vertices) {
        return;
    }

    // Remove edge from src to dest
    AdjListNode *current = graph-&gt;adj_list[src];
    AdjListNode *prev = NULL;

    while (current != NULL) {
        if (current-&gt;vertex == dest) {
            if (prev == NULL) {
                graph-&gt;adj_list[src] = current-&gt;next;
            } else {
                prev-&gt;next = current-&gt;next;
            }
            free(current);
            break;
        }
        prev = current;
        current = current-&gt;next;
    }

    // Remove edge from dest to src
    current = graph-&gt;adj_list[dest];
    prev = NULL;

    while (current != NULL) {
        if (current-&gt;vertex == src) {
            if (prev == NULL) {
                graph-&gt;adj_list[dest] = current-&gt;next;
            } else {
                prev-&gt;next = current-&gt;next;
            }
            free(current);
            break;
        }
        prev = current;
        current = current-&gt;next;
    }
}

// Print adjacency list
void print_adj_list(AdjListGraph *graph) {
    if (graph == NULL) return;

    printf("Adjacency List:\n");
    for (int i = 0; i &lt; graph-&gt;vertices; i++) {
        printf("%d: ", i);
        AdjListNode *current = graph-&gt;adj_list[i];
        while (current != NULL) {
            printf("(%d, %d) -&gt; ", current-&gt;vertex, current-&gt;weight);
            current = current-&gt;next;
        }
        printf("NULL\n");
    }
}

int main() {
    AdjListGraph *graph = create_adj_list_graph(5);
    if (graph == NULL) {
        printf("Failed to create graph\n");
        return 1;
    }

    // Add edges
    add_edge_list(graph, 0, 1, 1);
    add_edge_list(graph, 0, 4, 1);
    add_edge_list(graph, 1, 2, 1);
    add_edge_list(graph, 1, 3, 1);
    add_edge_list(graph, 1, 4, 1);
    add_edge_list(graph, 2, 3, 1);
    add_edge_list(graph, 3, 4, 1);

    print_adj_list(graph);

    free_adj_list_graph(graph);
    return 0;
}

Graph Traversal Algorithms

Breadth-First Search (BFS)
BFS explores vertices level by level, visiting all neighbors of a vertex before moving to the next level.
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;stdbool.h&gt;

#define MAX_VERTICES 100

typedef struct Queue {
    int items[MAX_VERTICES];
    int front;
    int rear;
} Queue;

// Initialize queue
Queue* create_queue(void) {
    Queue *queue = malloc(sizeof(Queue));
    if (queue == NULL) return NULL;

    queue-&gt;front = 0;
    queue-&gt;rear = -1;
    return queue;
}

// Check if queue is empty
bool is_queue_empty(Queue *queue) {
    return queue-&gt;rear &lt; queue-&gt;front;
}

// Enqueue
void enqueue(Queue *queue, int item) {
    if (queue-&gt;rear &lt; MAX_VERTICES - 1) {
        queue-&gt;items[++queue-&gt;rear] = item;
    }
}

// Dequeue
int dequeue(Queue *queue) {
    if (is_queue_empty(queue)) {
        return -1;
    }
    return queue-&gt;items[queue-&gt;front++];
}

typedef struct BFSGraph {
    int vertices;
    struct AdjListNode **adj_list;
} BFSGraph;

typedef struct AdjListNode {
    int vertex;
    struct AdjListNode *next;
} AdjListNode;

// Create new adjacency list node
AdjListNode* create_bfs_node(int vertex) {
    AdjListNode *node = malloc(sizeof(AdjListNode));
    if (node == NULL) return NULL;

    node-&gt;vertex = vertex;
    node-&gt;next = NULL;
    return node;
}

// Create BFS graph
BFSGraph* create_bfs_graph(int vertices) {
    BFSGraph *graph = malloc(sizeof(BFSGraph));
    if (graph == NULL) return NULL;

    graph-&gt;vertices = vertices;
    graph-&gt;adj_list = malloc(vertices * sizeof(AdjListNode*));
    if (graph-&gt;adj_list == NULL) {
        free(graph);
        return NULL;
    }

    for (int i = 0; i &lt; vertices; i++) {
        graph-&gt;adj_list[i] = NULL;
    }

    return graph;
}

// Free BFS graph
void free_bfs_graph(BFSGraph *graph) {
    if (graph == NULL) return;

    for (int i = 0; i &lt; graph-&gt;vertices; i++) {
        AdjListNode *current = graph-&gt;adj_list[i];
        while (current != NULL) {
            AdjListNode *next = current-&gt;next;
            free(current);
            current = next;
        }
    }

    free(graph-&gt;adj_list);
    free(graph);
}

// Add edge to BFS graph
void add_bfs_edge(BFSGraph *graph, int src, int dest) {
    if (graph == NULL || src &lt; 0 || src &gt;= graph-&gt;vertices || 
        dest &lt; 0 || dest &gt;= graph-&gt;vertices) {
        return;
    }

    // Add edge from src to dest
    AdjListNode *new_node = create_bfs_node(dest);
    new_node-&gt;next = graph-&gt;adj_list[src];
    graph-&gt;adj_list[src] = new_node;

    // For undirected graph, also add reverse edge
    new_node = create_bfs_node(src);
    new_node-&gt;next = graph-&gt;adj_list[dest];
    graph-&gt;adj_list[dest] = new_node;
}

// BFS traversal
void bfs(BFSGraph *graph, int start_vertex) {
    if (graph == NULL || start_vertex &lt; 0 || start_vertex &gt;= graph-&gt;vertices) {
        return;
    }

    bool *visited = calloc(graph-&gt;vertices, sizeof(bool));
    if (visited == NULL) return;

    Queue *queue = create_queue();
    if (queue == NULL) {
        free(visited);
        return;
    }

    visited[start_vertex] = true;
    enqueue(queue, start_vertex);

    printf("BFS Traversal starting from vertex %d: ", start_vertex);

    while (!is_queue_empty(queue)) {
        int current_vertex = dequeue(queue);
        printf("%d ", current_vertex);

        AdjListNode *current = graph-&gt;adj_list[current_vertex];
        while (current != NULL) {
            int adj_vertex = current-&gt;vertex;
            if (!visited[adj_vertex]) {
                visited[adj_vertex] = true;
                enqueue(queue, adj_vertex);
            }
            current = current-&gt;next;
        }
    }

    printf("\n");

    free(visited);
    free(queue);
}

int main() {
    BFSGraph *graph = create_bfs_graph(6);
    if (graph == NULL) {
        printf("Failed to create graph\n");
        return 1;
    }

    // Add edges to create a sample graph
    add_bfs_edge(graph, 0, 1);
    add_bfs_edge(graph, 0, 2);
    add_bfs_edge(graph, 1, 3);
    add_bfs_edge(graph, 1, 4);
    add_bfs_edge(graph, 2, 4);
    add_bfs_edge(graph, 3, 5);
    add_bfs_edge(graph, 4, 5);

    bfs(graph, 0);
    bfs(graph, 2);

    free_bfs_graph(graph);
    return 0;
}


