#include &lt;sys/select.h&gt;
#include &lt;sys/socket.h&gt;
#include &lt;netinet/in.h&gt;
#include &lt;arpa/inet.h&gt;
#include &lt;errno.h&gt;

#define PORT 8080
#define MAX_CLIENTS 100
#define BUFFER_SIZE 4096

typedef struct {
    int fd;
    char buffer[BUFFER_SIZE];
    int buffer_pos;
    int buffer_len;
} client_t;

int main() {
    int server_fd;
    struct sockaddr_in address;
    client_t clients[MAX_CLIENTS];
    int max_clients = MAX_CLIENTS;
    fd_set read_fds, write_fds;
    int max_fd;

    // Initialize client structures
    for (int i = 0; i &lt; max_clients; i++) {
        clients[i].fd = -1;
        clients[i].buffer_pos = 0;
        clients[i].buffer_len = 0;
    }

    // Create server socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    // Set socket options
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, (char *)&opt, sizeof(opt)) &lt; 0) {
        perror("setsockopt");
        exit(EXIT_FAILURE);
    }

    // Configure address
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Bind and listen
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) &lt; 0) {
        perror("bind failed");
        exit(EXIT_FAILURE);
    }

    if (listen(server_fd, 10) &lt; 0) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    printf("High-performance echo server listening on port %d\n", PORT);

    while (1) {
        // Clear file descriptor sets
        FD_ZERO(&read_fds);
        FD_ZERO(&write_fds);

        // Add server socket to read set
        FD_SET(server_fd, &read_fds);
        max_fd = server_fd;

        // Add client sockets to appropriate sets
        for (int i = 0; i &lt; max_clients; i++) {
            if (clients[i].fd &gt; 0) {
                FD_SET(clients[i].fd, &read_fds);

                // If we have data to send, add to write set
                if (clients[i].buffer_len &gt; 0) {
                    FD_SET(clients[i].fd, &write_fds);
                }

                if (clients[i].fd &gt; max_fd) {
                    max_fd = clients[i].fd;
                }
            }
        }

        // Wait for activity
        int activity = select(max_fd + 1, &read_fds, &write_fds, NULL, NULL);

        if (activity &lt; 0 && errno != EINTR) {
            perror("select error");
            exit(EXIT_FAILURE);
        }

        // Check for new connections
        if (FD_ISSET(server_fd, &read_fds)) {
            int new_socket;
            int addrlen = sizeof(address);

            if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) &lt; 0) {
                perror("accept");
                continue;
            }

            // Add new socket to clients array
            int i;
            for (i = 0; i &lt; max_clients; i++) {
                if (clients[i].fd == -1) {
                    clients[i].fd = new_socket;
                    clients[i].buffer_pos = 0;
                    clients[i].buffer_len = 0;
                    printf("New connection: socket %d\n", new_socket);
                    break;
                }
            }

            if (i == max_clients) {
                printf("Too many clients, closing new connection\n");
                close(new_socket);
            }
        }

        // Check for data from clients
        for (int i = 0; i &lt; max_clients; i++) {
            int sd = clients[i].fd;

            if (sd &lt; 0) continue;

            // Check for data to read
            if (FD_ISSET(sd, &read_fds)) {
                int valread = read(sd, clients[i].buffer + clients[i].buffer_len, 
                                  BUFFER_SIZE - clients[i].buffer_len);

                if (valread &lt;= 0) {
                    // Client disconnected
                    getpeername(sd, (struct sockaddr*)&address, (socklen_t*)&addrlen);
                    printf("Client disconnected: %s:%d\n", 
                           inet_ntoa(address.sin_addr), ntohs(address.sin_port));
                    close(sd);
                    clients[i].fd = -1;
                    clients[i].buffer_pos = 0;
                    clients[i].buffer_len = 0;
                } else {
                    // Add data to buffer
                    clients[i].buffer_len += valread;
                    printf("Received %d bytes from client\n", valread);
                }
            }

            // Check for ability to write
            if (sd &gt; 0 && FD_ISSET(sd, &write_fds) && clients[i].buffer_len &gt; 0) {
                int to_send = clients[i].buffer_len - clients[i].buffer_pos;
                int sent = write(sd, clients[i].buffer + clients[i].buffer_pos, to_send);

                if (sent &lt; 0) {
                    if (errno != EAGAIN && errno != EWOULDBLOCK) {
                        printf("Write error, closing connection\n");
                        close(sd);
                        clients[i].fd = -1;
                        clients[i].buffer_pos = 0;
                        clients[i].buffer_len = 0;
                    }
                } else {
                    clients[i].buffer_pos += sent;

                    // If we've sent all data, reset buffer
                    if (clients[i].buffer_pos &gt;= clients[i].buffer_len) {
                        clients[i].buffer_pos = 0;
                        clients[i].buffer_len = 0;
                    }
                }
            }
        }
    }

    return 0;
}

HTTP Protocol Implementation
HTTP (HyperText Transfer Protocol) is the foundation of data communication on the World Wide Web. Understanding HTTP is crucial for developing web applications and services.

HTTP Request Structure
An HTTP request consists of: 1. Request Line - Method, URI, and HTTP version 2. Headers - Key-value pairs providing metadata 3. Body - Optional data (for POST, PUT requests)
Example HTTP GET request:
GET /index.html HTTP/1.1
Host: www.example.com
User-Agent: Mozilla/5.0
Accept: text/html
Connection: close



HTTP Response Structure
An HTTP response consists of: 1. Status Line - HTTP version, status code, and reason phrase 2. Headers - Key-value pairs providing metadata 3. Body - Response content
Example HTTP response:
HTTP/1.1 200 OK
Content-Type: text/html
Content-Length: 1234
Connection: close

&lt;HTML&gt;...&lt;/HTML&gt;


Simple HTTP Client
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;
#include &lt;unistd.h&gt;
#include &lt;sys/socket.h&gt;
#include &lt;netinet/in.h&gt;
#include &lt;arpa/inet.h&gt;
#include &lt;netdb.h&gt;

#define BUFFER_SIZE 4096

int create_socket(const char *hostname, int port) {
    int sockfd;
    struct hostent *server;
    struct sockaddr_in serv_addr;

    // Create socket
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd &lt; 0) {
        perror("ERROR opening socket");
        return -1;
    }

    // Get server IP address
    server = gethostbyname(hostname);
    if (server == NULL) {
        fprintf(stderr, "ERROR, no such host\n");
        return -1;
    }

    // Configure server address
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    memcpy(server-&gt;h_addr, &serv_addr.sin_addr.s_addr, server-&gt;h_length);
    serv_addr.sin_port = htons(port);

    // Connect to server
    if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) &lt; 0) {
        perror("ERROR connecting");
        return -1;
    }

    return sockfd;
}

int http_get(const char *hostname, const char *path) {
    int sockfd;
    char request[BUFFER_SIZE];
    char response[BUFFER_SIZE];
    int bytes_sent, bytes_received;

    // Create socket and connect
    sockfd = create_socket(hostname, 80);
    if (sockfd &lt; 0) {
        return -1;
    }

    // Create HTTP GET request
    snprintf(request, BUFFER_SIZE,
             "GET %s HTTP/1.1\r\n"
             "Host: %s\r\n"
             "Connection: close\r\n"
             "\r\n",
             path, hostname);

    // Send request
    bytes_sent = send(sockfd, request, strlen(request), 0);
    if (bytes_sent &lt; 0) {
        perror("ERROR sending request");
        close(sockfd);
        return -1;
    }

    printf("HTTP Request sent:\n%s", request);

    // Receive response
    while ((bytes_received = recv(sockfd, response, BUFFER_SIZE - 1, 0)) &gt; 0) {
        response[bytes_received] = '\0';
        printf("%s", response);
    }

    if (bytes_received &lt; 0) {
        perror("ERROR receiving response");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

int main() {
    const char *hostname = "httpbin.org";
    const char *path = "/get";

    printf("Sending HTTP GET request to %s%s\n", hostname, path);
    http_get(hostname, path);

    return 0;
}


Simple HTTP Server
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;
#include &lt;unistd.h&gt;
#include &lt;sys/socket.h&gt;
#include &lt;netinet/in.h&gt;
#include &lt;arpa/inet.h&gt;
#include &lt;time.h&gt;

#define PORT 8080
#define BUFFER_SIZE 4096

void send_http_response(int client_fd, const char *status, const char *content_type, const char *body) {
    char response[BUFFER_SIZE];
    time_t now;
    char time_str[100];

    // Get current time
    time(&now);
    strftime(time_str, sizeof(time_str), "%a, %d %b %Y %H:%M:%S GMT", gmtime(&now));

    // Create HTTP response
    int content_length = strlen(body);
    snprintf(response, BUFFER_SIZE,
             "HTTP/1.1 %s\r\n"
             "Date: %s\r\n"
             "Server: SimpleHTTPServer/1.0\r\n"
             "Content-Type: %s\r\n"
             "Content-Length: %d\r\n"
             "Connection: close\r\n"
             "\r\n"
             "%s",
             status, time_str, content_type, content_length, body);

    // Send response
    send(client_fd, response, strlen(response), 0);
}

void handle_request(int client_fd, const char *request) {
    printf("Received request:\n%s\n", request);

    // Parse request line (first line)
    char method[16], path[256], version[16];
    if (sscanf(request, "%15s %255s %15s", method, path, version) != 3) {
        send_http_response(client_fd, "400 Bad Request", "text/plain", "Bad Request");
        return;
    }

    // Handle different HTTP methods and paths
    if (strcmp(method, "GET") == 0) {
        if (strcmp(path, "/") == 0 || strcmp(path, "/index.html") == 0) {
            const char *html = 
                "&lt;!DOCTYPE html&gt;\n"
                "&lt;html&gt;\n"
                "&lt;head&gt;&lt;title&gt;Simple HTTP Server&lt;/title&gt;&lt;/head&gt;\n"
                "&lt;body&gt;&lt;h1&gt;Welcome to Simple HTTP Server&lt;/h1&gt;\n"
                "&lt;p&gt;This is a simple HTTP server implemented in C.&lt;/p&gt;\n"
                "&lt;/body&gt;\n"
                "&lt;/html&gt;";
            send_http_response(client_fd, "200 OK", "text/html", html);
        } else if (strcmp(path, "/api/time") == 0) {
            time_t now = time(NULL);
            char time_str[100];
            snprintf(time_str, sizeof(time_str), "{\"time\": \"%s\"}", ctime(&now));
            send_http_response(client_fd, "200 OK", "application/json", time_str);
        } else {
            const char *not_found = 
                "&lt;!DOCTYPE html&gt;\n"
                "&lt;html&gt;\n"
                "&lt;head&gt;&lt;title&gt;404 Not Found&lt;/title&gt;&lt;/head&gt;\n"
                "&lt;body&gt;&lt;h1&gt;404 Not Found&lt;/h1&gt;\n"
                "&lt;p&gt;The requested resource was not found.&lt;/p&gt;\n"
                "&lt;/body&gt;\n"
                "&lt;/html&gt;";
            send_http_response(client_fd, "404 Not Found", "text/html", not_found);
        }
    } else {
        send_http_response(client_fd, "405 Method Not Allowed", "text/plain", "Method Not Allowed");
    }
}

int main() {
    int server_fd, client_fd;
    struct sockaddr_in address;
    int opt = 1;
    int addrlen = sizeof(address);
    char buffer[BUFFER_SIZE];

    // Create socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    // Set socket options
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT,
                   &opt, sizeof(opt))) {
        perror("setsockopt");
        exit(EXIT_FAILURE);
    }

    // Configure address
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Bind socket
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) &lt; 0) {
        perror("bind failed");
        exit(EXIT_FAILURE);
    }

    // Listen for connections
    if (listen(server_fd, 10) &lt; 0) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    printf("HTTP Server listening on port %d\n", PORT);

    while (1) {
        // Accept connection
        if ((client_fd = accept(server_fd, (struct sockaddr *)&address,
                               (socklen_t*)&addrlen)) &lt; 0) {
            perror("accept");
            continue;
        }

        // Read request
        int bytes_read = read(client_fd, buffer, BUFFER_SIZE - 1);
        if (bytes_read &gt; 0) {
            buffer[bytes_read] = '\0';
            handle_request(client_fd, buffer);
        }

        // Close client connection
        close(client_fd);
    }

    close(server_fd);
    return 0;
}

