void analyze_ip_packet(const unsigned char *buffer, int size) {
    struct iphdr *iph = (struct iphdr*)buffer;

    printf("IP Header\n");
    printf("   |-Version           : %d\n", (unsigned int)iph-&gt;version);
    printf("   |-Internet Header Length : %d DWORDS or %d Bytes\n", 
           (unsigned int)iph-&gt;ihl, ((unsigned int)(iph-&gt;ihl))*4);
    printf("   |-Type Of Service   : %d\n", (unsigned int)iph-&gt;tos);
    printf("   |-Total Length      : %d Bytes\n", ntohs(iph-&gt;tot_len));
    printf("   |-Identification    : %d\n", ntohs(iph-&gt;id));
    printf("   |-Time To Live      : %d\n", (unsigned int)iph-&gt;ttl);
    printf("   |-Protocol          : %d\n", (unsigned int)iph-&gt;protocol);
    printf("   |-Header Checksum   : %d\n", ntohs(iph-&gt;check));
    printf("   |-Source IP         : %s\n", inet_ntoa(*(struct in_addr*)&iph-&gt;saddr));
    printf("   |-Destination IP    : %s\n", inet_ntoa(*(struct in_addr*)&iph-&gt;daddr));

    // Analyze protocol-specific headers
    switch (iph-&gt;protocol) {
        case 6: // TCP
            printf("TCP Protocol\n");
            break;
        case 17: // UDP
            printf("UDP Protocol\n");
            break;
        case 1: // ICMP
            printf("ICMP Protocol\n");
            break;
        default:
            printf("Other Protocol\n");
            break;
    }
}

int main() {
    int sockfd;
    unsigned char buffer[65536];
    struct sockaddr_in dest;
    socklen_t dest_len = sizeof(dest);

    // Create raw socket (requires root privileges)
    sockfd = socket(AF_INET, SOCK_RAW, IPPROTO_TCP);
    if (sockfd &lt; 0) {
        perror("socket creation failed (try running as root)");
        exit(EXIT_FAILURE);
    }

    printf("Protocol Analyzer started...\n");

    // Capture packets
    while (1) {
        int packet_size = recvfrom(sockfd, buffer, 65536, 0, (struct sockaddr*)&dest, &dest_len);
        if (packet_size &lt; 0) {
            perror("recvfrom failed");
            continue;
        }

        printf("\n----------------------------------------\n");
        analyze_ip_packet(buffer, packet_size);
        printf("----------------------------------------\n");
    }

    close(sockfd);
    return 0;
}

Cryptography Basics
Cryptography is the practice of securing communication from adversaries. Understanding basic cryptographic concepts is essential for implementing secure network applications.

Symmetric Encryption
Symmetric encryption uses the same key for both encryption and decryption.
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;

// Simple XOR cipher (for demonstration only - not secure)
void xor_encrypt_decrypt(char *data, size_t data_len, const char *key, size_t key_len) {
    for (size_t i = 0; i &lt; data_len; i++) {
        data[i] ^= key[i % key_len];
    }
}

int main() {
    char message[] = "This is a secret message";
    char key[] = "mykey";
    size_t message_len = strlen(message);

    printf("Original message: %s\n", message);

    // Encrypt
    xor_encrypt_decrypt(message, message_len, key, strlen(key));
    printf("Encrypted message: ");
    for (size_t i = 0; i &lt; message_len; i++) {
        printf("%02x ", (unsigned char)message[i]);
    }
    printf("\n");

    // Decrypt (XOR is symmetric)
    xor_encrypt_decrypt(message, message_len, key, strlen(key));
    printf("Decrypted message: %s\n", message);

    return 0;
}


