// GPIO register structure using bit fields
typedef struct {
    volatile uint32_t MODER   : 32;  // Port mode register
    volatile uint32_t OTYPER  : 16;  // Port output type register
    volatile uint32_t OSPEEDR : 32;  // Port output speed register
