Program 3 — Complexity reduction: nested ifs → early return
/* file: access.c */
#include &lt;stdio.h&gt;
#include &lt;stdbool.h&gt;

struct User {
    bool active;
    bool banned;
    int age;
    int role;  /* 0 guest, 1 user, 2 admin */
};

/* Opaque quality: one exit path per failure reason, easy to test. */
const char *can_edit(const struct User *u) {
    if (u == NULL) {
        return "null user";
    }
    if (!u-&gt;active) {
        return "inactive";
    }
    if (u-&gt;banned) {
        return "banned";
    }
    if (u-&gt;age &lt; 13) {
        return "underage";
    }
    if (u-&gt;role &lt; 1) {
        return "guest cannot edit";
    }
    return NULL;  /* allowed */
}

int main(void) {
    struct User samples[] = {
        {true, false, 20, 1},
        {false, false, 20, 1},
        {true, true, 20, 2},
        {true, false, 10, 1},
        {true, false, 25, 0},
    };
    size_t i;

    for (i = 0; i &lt; sizeof samples / sizeof samples[0]; i++) {
        const char *err = can_edit(&samples[i]);
        if (err == NULL) {
            printf("sample %zu: OK\n", i);
        } else {
            printf("sample %zu: DENY (%s)\n", i, err);
