typedef struct {
    char *filename;
    FILE *file;
    char *buffer;
    int *data;
} ResourceManager;

int initialize_resources(ResourceManager *rm) {
    // Allocate filename
    rm-&gt;filename = malloc(100);
    if (!rm-&gt;filename) {
        goto cleanup;
    }
    strcpy(rm-&gt;filename, "data.txt");

    // Open file
    rm-&gt;file = fopen(rm-&gt;filename, "w");
    if (!rm-&gt;file) {
        printf("Error opening file\n");
        goto cleanup;
    }

    // Allocate buffer
    rm-&gt;buffer = malloc(1024);
    if (!rm-&gt;buffer) {
        printf("Error allocating buffer\n");
        goto cleanup;
    }

    // Allocate data
    rm-&gt;data = malloc(100 * sizeof(int));
    if (!rm-&gt;data) {
        printf("Error allocating data\n");
        goto cleanup;
    }

    printf("All resources initialized successfully\n");
    return 0;  // Success

cleanup:
    // Cleanup in reverse order
    if (rm-&gt;data) {
        free(rm-&gt;data);
        rm-&gt;data = NULL;
    }
    if (rm-&gt;buffer) {
        free(rm-&gt;buffer);
        rm-&gt;buffer = NULL;
    }
    if (rm-&gt;file) {
        fclose(rm-&gt;file);
        rm-&gt;file = NULL;
    }
    if (rm-&gt;filename) {
        free(rm-&gt;filename);
        rm-&gt;filename = NULL;
    }
    return -1;  // Error
}

void cleanup_resources(ResourceManager *rm) {
    if (rm-&gt;data) {
        free(rm-&gt;data);
        rm-&gt;data = NULL;
    }
    if (rm-&gt;buffer) {
        free(rm-&gt;buffer);
        rm-&gt;buffer = NULL;
    }
    if (rm-&gt;file) {
        fclose(rm-&gt;file);
        rm-&gt;file = NULL;
    }
    if (rm-&gt;filename) {
        free(rm-&gt;filename);
        rm-&gt;filename = NULL;
    }
    printf("All resources cleaned up\n");
}

int main() {
    ResourceManager rm = {0};

    if (initialize_resources(&rm) == 0) {
        printf("Resource management successful\n");
        // Use resources here
        cleanup_resources(&rm);
    } else {
        printf("Resource management failed\n");
        return 1;
    }

    return 0;
}

