    }

    return 0;
}


Exercise 3.2: Pattern Printer
#include &lt;stdio.h&gt;

void print_triangle(int n) {
    for (int i = 1; i &lt;= n; i++) {
        // Print spaces
        for (int j = 1; j &lt;= n - i; j++) {
            printf(" ");
        }
        // Print stars
        for (int j = 1; j &lt;= 2 * i - 1; j++) {
            printf("*");
        }
        printf("\n");
    }
}

void print_diamond(int n) {
    // Upper half (including middle)
    for (int i = 1; i &lt;= n; i++) {
        for (int j = 1; j &lt;= n - i; j++) {
            printf(" ");
        }
        for (int j = 1; j &lt;= 2 * i - 1; j++) {
            printf("*");
        }
        printf("\n");
    }

    // Lower half
    for (int i = n - 1; i &gt;= 1; i--) {
        for (int j = 1; j &lt;= n - i; j++) {
            printf(" ");
        }
        for (int j = 1; j &lt;= 2 * i - 1; j++) {
            printf("*");
        }
        printf("\n");
    }
}

int main() {
    int n;
    int choice;

    printf("Pattern Printer\n");
    printf("1. Triangle\n");
    printf("2. Diamond\n");
    printf("Enter your choice (1 or 2): ");
    scanf("%d", &choice);

    printf("Enter the size: ");
    scanf("%d", &n);

    if (choice == 1) {
        print_triangle(n);
    } else if (choice == 2) {
        print_diamond(n);
    } else {
        printf("Invalid choice\n");
    }

    return 0;
}

