            break;

        case 3:
            printf("Enter first number: ");
            scanf("%d", &a);
            printf("Enter second number: ");
            scanf("%d", &b);
            printf("GCD of %d and %d = %d\n", a, b, gcd(a, b));
            break;

        case 4:
            printf("Enter first number: ");
            scanf("%d", &a);
            printf("Enter second number: ");
