                printf("Fibonacci number at position %d = %d\n", n, recursive_fibonacci(n));
            } else {
                printf("Invalid position\n");
            }
            break;

        case 3:
            printf("Enter base: ");
            scanf("%lf", &x);
            printf("Enter exponent: ");
            scanf("%d", &exp);
