Exercise 10.1: Linked List Implementation
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

typedef struct Node {
    int data;
    struct Node* next;
} Node;

// Function to create new node
Node* create_node(int data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    new_node-&gt;data = data;
    new_node-&gt;next = NULL;
    return new_node;
}

// Function to insert at beginning
void insert_at_beginning(Node** head, int data) {
    Node* new_node = create_node(data);
    if (new_node == NULL) return;

    new_node-&gt;next = *head;
    *head = new_node;
}

// Function to insert at end
void insert_at_end(Node** head, int data) {
    Node* new_node = create_node(data);
    if (new_node == NULL) return;

    if (*head == NULL) {
        *head = new_node;
        return;
    }

    Node* current = *head;
    while (current-&gt;next != NULL) {
        current = current-&gt;next;
    }
    current-&gt;next = new_node;
}

// Function to delete node
void delete_node(Node** head, int key) {
    if (*head == NULL) return;

    // If head node holds the key
    if ((*head)-&gt;data == key) {
        Node* temp = *head;
        *head = (*head)-&gt;next;
        free(temp);
        return;
    }

    // Search for the key to be deleted
    Node* current = *head;
    while (current-&gt;next != NULL && current-&gt;next-&gt;data != key) {
        current = current-&gt;next;
    }

    // If key was not present
    if (current-&gt;next == NULL) return;

    // Remove the node
    Node* temp = current-&gt;next;
    current-&gt;next = current-&gt;next-&gt;next;
    free(temp);
}

// Function to search for a node
Node* search_node(Node* head, int key) {
    Node* current = head;
    while (current != NULL) {
        if (current-&gt;data == key) {
            return current;
        }
        current = current-&gt;next;
    }
    return NULL;
}

// Function to display the list
void display_list(Node* head) {
    if (head == NULL) {
        printf("List is empty\n");
        return;
    }

    printf("List: ");
    Node* current = head;
    while (current != NULL) {
        printf("%d", current-&gt;data);
        if (current-&gt;next != NULL) printf(" -&gt; ");
        current = current-&gt;next;
    }
    printf(" -&gt; NULL\n");
}

// Function to free the entire list
void free_list(Node* head) {
    Node* current = head;
    while (current != NULL) {
        Node* next = current-&gt;next;
        free(current);
        current = next;
    }
}

int main() {
    Node* head = NULL;
    int choice, data;

    while (1) {
        printf("\nLinked List Operations:\n");
        printf("1. Insert at beginning\n");
        printf("2. Insert at end\n");
        printf("3. Delete node\n");
        printf("4. Search node\n");
        printf("5. Display list\n");
        printf("6. Exit\n");
        printf("Enter your choice: ");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                printf("Enter data: ");
                scanf("%d", &data);
                insert_at_beginning(&head, data);
                break;

            case 2:
                printf("Enter data: ");
                scanf("%d", &data);
                insert_at_end(&head, data);
                break;

            case 3:
                printf("Enter data to delete: ");
                scanf("%d", &data);
                delete_node(&head, data);
                break;

            case 4:
                printf("Enter data to search: ");
                scanf("%d", &data);
                Node* found = search_node(head, data);
                if (found != NULL) {
                    printf("Node found with data: %d\n", found-&gt;data);
                } else {
                    printf("Node not found\n");
                }
                break;

            case 5:
                display_list(head);
                break;

            case 6:
                free_list(head);
                printf("Exiting program\n");
                return 0;

            default:
                printf("Invalid choice\n");
        }
    }

    return 0;
}


Exercise 10.2: Binary Search Tree Implementation
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

typedef struct TreeNode {
    int data;
    struct TreeNode* left;
    struct TreeNode* right;
} TreeNode;

// Function to create new node
TreeNode* create_node(int data) {
    TreeNode* new_node = (TreeNode*)malloc(sizeof(TreeNode));
    if (new_node == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    new_node-&gt;data = data;
    new_node-&gt;left = NULL;
    new_node-&gt;right = NULL;
    return new_node;
}

// Function to insert node
TreeNode* insert_node(TreeNode* root, int data) {
    if (root == NULL) {
        return create_node(data);
    }

    if (data &lt; root-&gt;data) {
        root-&gt;left = insert_node(root-&gt;left, data);
    } else if (data &gt; root-&gt;data) {
        root-&gt;right = insert_node(root-&gt;right, data);
    }
    // If data is equal, we don't insert (no duplicates)

    return root;
}

// Function for inorder traversal
void inorder_traversal(TreeNode* root) {
    if (root != NULL) {
        inorder_traversal(root-&gt;left);
        printf("%d ", root-&gt;data);
        inorder_traversal(root-&gt;right);
    }
}

// Function for preorder traversal
void preorder_traversal(TreeNode* root) {
    if (root != NULL) {
        printf("%d ", root-&gt;data);
        preorder_traversal(root-&gt;left);
        preorder_traversal(root-&gt;right);
    }
}

// Function for postorder traversal
void postorder_traversal(TreeNode* root) {
    if (root != NULL) {
        postorder_traversal(root-&gt;left);
        postorder_traversal(root-&gt;right);
        printf("%d ", root-&gt;data);
    }
}

// Function to search for a node
TreeNode* search_node(TreeNode* root, int data) {
    if (root == NULL || root-&gt;data == data) {
        return root;
    }

    if (data &lt; root-&gt;data) {
        return search_node(root-&gt;left, data);
    } else {
        return search_node(root-&gt;right, data);
    }
}

// Function to find minimum value node
TreeNode* find_min(TreeNode* root) {
    while (root && root-&gt;left != NULL) {
        root = root-&gt;left;
    }
    return root;
}

// Function to delete node
TreeNode* delete_node(TreeNode* root, int data) {
    if (root == NULL) return root;

    if (data &lt; root-&gt;data) {
        root-&gt;left = delete_node(root-&gt;left, data);
    } else if (data &gt; root-&gt;data) {
        root-&gt;right = delete_node(root-&gt;right, data);
    } else {
        // Node to be deleted found
        if (root-&gt;left == NULL) {
            TreeNode* temp = root-&gt;right;
            free(root);
            return temp;
        } else if (root-&gt;right == NULL) {
            TreeNode* temp = root-&gt;left;
            free(root);
            return temp;
        }

        // Node with two children
        TreeNode* temp = find_min(root-&gt;right);
        root-&gt;data = temp-&gt;data;
        root-&gt;right = delete_node(root-&gt;right, temp-&gt;data);
    }
    return root;
}

// Function to free the entire tree
void free_tree(TreeNode* root) {
    if (root != NULL) {
        free_tree(root-&gt;left);
        free_tree(root-&gt;right);
        free(root);
    }
}

int main() {
    TreeNode* root = NULL;
    int choice, data;

    while (1) {
        printf("\nBinary Search Tree Operations:\n");
        printf("1. Insert node\n");
        printf("2. Delete node\n");
        printf("3. Search node\n");
        printf("4. Inorder traversal\n");
        printf("5. Preorder traversal\n");
        printf("6. Postorder traversal\n");
        printf("7. Exit\n");
        printf("Enter your choice: ");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                printf("Enter data: ");
                scanf("%d", &data);
                root = insert_node(root, data);
                break;

            case 2:
                printf("Enter data to delete: ");
                scanf("%d", &data);
                root = delete_node(root, data);
                break;

            case 3:
                printf("Enter data to search: ");
                scanf("%d", &data);
                TreeNode* found = search_node(root, data);
                if (found != NULL) {
                    printf("Node found with data: %d\n", found-&gt;data);
                } else {
                    printf("Node not found\n");
                }
                break;

            case 4:
                printf("Inorder traversal: ");
                inorder_traversal(root);
                printf("\n");
                break;

            case 5:
                printf("Preorder traversal: ");
                preorder_traversal(root);
                printf("\n");
                break;

            case 6:
                printf("Postorder traversal: ");
                postorder_traversal(root);
                printf("\n");
                break;

            case 7:
                free_tree(root);
                printf("Exiting program\n");
                return 0;

            default:
                printf("Invalid choice\n");
        }
    }

    return 0;
}

