#include &lt;sys/socket.h&gt;
#include &lt;netinet/in.h&gt;
#include &lt;arpa/inet.h&gt;
#include &lt;netdb.h&gt;

int http_get_request(const char *hostname, const char *path) {
    int sock;
    struct hostent *server;
    struct sockaddr_in serv_addr;
    char request[1024];
    char response[4096];

    // Create socket
    sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock &lt; 0) {
        perror("socket creation failed");
        return 1;
    }

    // Get server IP address
    server = gethostbyname(hostname);
    if (server == NULL) {
        fprintf(stderr, "Error, no such host\n");
        close(sock);
        return 1;
    }

    // Set up server address
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    memcpy(server-&gt;h_addr, &serv_addr.sin_addr.s_addr, server-&gt;h_length);
    serv_addr.sin_port = htons(80);

    // Connect to server
    if (connect(sock, (struct sockaddr*)&serv_addr, sizeof(serv_addr)) &lt; 0) {
        perror("connection failed");
        close(sock);
        return 1;
    }

    // Create HTTP GET request
    snprintf(request, sizeof(request),
             "GET %s HTTP/1.1\r\n"
             "Host: %s\r\n"
             "Connection: close\r\n\r\n",
             path, hostname);

    // Send request
    if (send(sock, request, strlen(request), 0) &lt; 0) {
        perror("send failed");
        close(sock);
        return 1;
    }

    // Receive response
    int bytes_received;
    while ((bytes_received = recv(sock, response, sizeof(response) - 1, 0)) &gt; 0) {
        response[bytes_received] = '\0';
        printf("%s", response);
    }

    close(sock);
    return 0;
}

int main() {
    char hostname[256];
    char path[256];

    printf("Enter hostname (e.g., httpbin.org): ");
    scanf("%s", hostname);

    printf("Enter path (e.g., /get): ");
    scanf("%s", path);

    return http_get_request(hostname, path);
}

