    *reg &= ~(1U &lt;&lt; bit);
}

void toggle_bit(uint32_t *reg, int bit) {
    *reg ^= (1U &lt;&lt; bit);
}

int check_bit(uint32_t reg, int bit) {
    return (reg &gt;&gt; bit) & 1U;
}

